/*
 * OCR B (MEI) A-Level Mathematics (H640) — Exam Practice Question Bank
 * Written, exam-style questions with mark schemes, self-marked Full / Partial / Missed.
 * Single A-Level entry: AS (H630) content is folded into the same topic ids.
 * Keyed by topic id: 1.1–1.13 Pure, 2.1–2.5 Statistics, 3.1–3.7 Mechanics.
 * Shape A: { topicId: { name, questions: [{ q, marks, markScheme }] } }
 * Target: 40 questions per topic.
 */

const MATHS_OCR_B_ALEVEL_PRACTICE = {

  '1.1': {
    name: 'Proof',
    questions: [
      { q: 'State what is meant by a mathematical conjecture, and explain how it differs from a theorem.', marks: 2, markScheme: `• A conjecture is a mathematical statement that is believed to be true but has not been proved (1)\n• A theorem is a statement that has been proved from axioms and previously established results (1)` },

      { q: 'Explain the difference between the converse and the contrapositive of the statement "if P then Q", and state which is logically equivalent to the original.', marks: 3, markScheme: `• Converse is "if Q then P" (1)\n• Contrapositive is "if not Q then not P" (1)\n• The contrapositive is logically equivalent to the original statement; the converse is not (1)` },

      { q: 'Prove by deduction that the sum of any two consecutive integers is odd.', marks: 3, markScheme: `• Let the integers be n and n + 1, where n is an integer (1)\n• Sum = 2n + 1 (1)\n• 2n is even, so 2n + 1 is odd; hence the sum of any two consecutive integers is odd (1)` },

      { q: 'Prove that the sum of any three consecutive integers is divisible by 3.', marks: 3, markScheme: `• Let the integers be n − 1, n, n + 1 (or n, n + 1, n + 2) (1)\n• Sum = 3n (or 3n + 3) (1)\n• 3n = 3 × n is a multiple of 3 for every integer n, with conclusion stated (1)` },

      { q: 'Prove that the sum of two odd numbers is always even.', marks: 3, markScheme: `• Let the odd numbers be 2a + 1 and 2b + 1, where a and b are integers — different letters required (1)\n• Sum = 2a + 2b + 2 = 2(a + b + 1) (1)\n• This is 2 × an integer, hence even; conclusion stated (1)` },

      { q: 'Prove that the product of any two consecutive integers is even.', marks: 3, markScheme: `• Let the integers be n and n + 1 (1)\n• One of any two consecutive integers must be even (1)\n• An even number multiplied by any integer is even, so the product is even (1)` },

      { q: 'Prove that the square of any odd number is odd.', marks: 3, markScheme: `• Let the odd number be 2k + 1, where k is an integer (1)\n• (2k + 1)² = 4k² + 4k + 1 = 2(2k² + 2k) + 1 (1)\n• This is 2 × an integer + 1, hence odd; conclusion stated (1)` },

      { q: 'Prove that the difference between the squares of any two consecutive odd numbers is a multiple of 8.', marks: 4, markScheme: `• Let the odd numbers be 2n − 1 and 2n + 1 (1)\n• Difference = (2n + 1)² − (2n − 1)² (1)\n• Expand and simplify: (4n² + 4n + 1) − (4n² − 4n + 1) = 8n (1)\n• 8n is a multiple of 8 for every integer n; conclusion stated (1)` },

      { q: 'Disprove the statement "every odd number is prime".', marks: 2, markScheme: `• Provide a counter-example, e.g. n = 9 (1)\n• 9 = 3 × 3 is odd but not prime, so the statement is disproved (1)` },

      { q: 'Disprove the statement "2ⁿ − 1 is prime for every positive integer n".', marks: 3, markScheme: `• Choose a counter-example, n = 4 (1)\n• 2⁴ − 1 = 15 (1)\n• 15 = 3 × 5 is not prime, so the statement is false (1)` },

      { q: 'Disprove the statement "if n is prime then 2ⁿ − 1 is prime".', marks: 3, markScheme: `• Take n = 11, which is prime (1)\n• 2¹¹ − 1 = 2047 (1)\n• 2047 = 23 × 89, which is not prime, so the statement is disproved (1)` },

      { q: 'The expression n² − n + 41 gives a prime number for n = 1, 2, …, 40. Explain why this does not prove that it is prime for every positive integer n, and give a value of n for which it fails.', marks: 3, markScheme: `• Checking finitely many cases cannot establish a statement about infinitely many integers (1)\n• At n = 41 the expression equals 41² − 41 + 41 = 41² (1)\n• 41² is divisible by 41 and so is not prime; the statement is therefore false (1)` },

      { q: 'Disprove the statement "x² > x for all real numbers x".', marks: 2, markScheme: `• Take a counter-example with 0 < x < 1, e.g. x = ½ (1)\n• (½)² = ¼ < ½, so the statement fails (1)` },

      { q: 'Explain why a single example can disprove a general statement but cannot prove one.', marks: 2, markScheme: `• A general statement claims something for every case, so one failing case makes it false (1)\n• One successful case leaves infinitely many others unchecked, so it establishes nothing in general (1)` },

      { q: 'Prove by exhaustion that n² leaves a remainder of 0 or 1 when divided by 4, for every integer n.', marks: 4, markScheme: `• State that every integer is either even or odd, so these two cases are exhaustive (1)\n• If n = 2k then n² = 4k², remainder 0 (1)\n• If n = 2k + 1 then n² = 4k² + 4k + 1 = 4(k² + k) + 1, remainder 1 (1)\n• The two cases cover all integers, so the statement holds (1)` },

      { q: 'Prove by exhaustion that if 3 does not divide n, then n² leaves a remainder of 1 when divided by 3.', marks: 4, markScheme: `• If 3 ∤ n then n is of the form 3k + 1 or 3k + 2 — state that these cases are exhaustive (1)\n• n = 3k + 1: n² = 9k² + 6k + 1 = 3(3k² + 2k) + 1 (1)\n• n = 3k + 2: n² = 9k² + 12k + 4 = 3(3k² + 4k + 1) + 1 (1)\n• In both cases the remainder is 1; conclusion stated (1)` },

      { q: 'Explain what is meant by proof by exhaustion, and state one limitation of the method.', marks: 3, markScheme: `• A proof that establishes a result by checking every case of a finite set of cases (1)\n• Each case must be verified and the cases must together cover all possibilities (1)\n• Limitation: it cannot be used when there are infinitely many cases, unless they can first be reduced to finitely many classes (1)` },

      { q: 'Prove by contradiction that √2 is irrational.', marks: 5, markScheme: `• Assume for contradiction that √2 is rational, so √2 = p/q with p, q integers, q ≠ 0, and the fraction in its lowest terms (1)\n• Squaring and rearranging gives p² = 2q², so p² is even and therefore p is even (1)\n• Write p = 2k, so 4k² = 2q², giving q² = 2k², so q² is even and therefore q is even (1)\n• p and q are both even, contradicting the assumption that p/q was in its lowest terms (1)\n• Therefore the assumption is false and √2 is irrational (1)` },

      { q: 'In the proof that √2 is irrational, explain why the assumption that p/q is in its lowest terms is essential.', marks: 2, markScheme: `• The contradiction reached is that p and q share a common factor of 2 (1)\n• Without the assumption of lowest terms this would not be a contradiction, so the proof would fail (1)` },

      { q: 'Explain why the standard proof that √2 is irrational cannot be adapted to show that √4 is irrational.', marks: 3, markScheme: `• The adapted argument would require the step "p² divisible by 4 ⇒ p divisible by 4" (1)\n• This step is false — for example p = 2 gives p² = 4, which is divisible by 4, while p is not (1)\n• The proof therefore breaks down, as it must, since √4 = 2 is rational (1)` },

      { q: 'Prove by contradiction that √3 is irrational, stating clearly the divisibility fact you use.', marks: 5, markScheme: `• Assume √3 = p/q with p, q integers, q ≠ 0, in lowest terms (1)\n• p² = 3q², so 3 divides p² (1)\n• State and use the fact that if 3 divides a² then 3 divides a, hence p = 3k (1)\n• 9k² = 3q² gives q² = 3k², so 3 divides q² and hence q (1)\n• p and q share a factor 3, contradicting lowest terms; therefore √3 is irrational (1)` },

      { q: 'Prove that there are infinitely many prime numbers.', marks: 6, markScheme: `• Assume for contradiction that there are finitely many primes p₁, p₂, …, pₙ (1)\n• Define N = p₁p₂⋯pₙ + 1 (1)\n• Each pᵢ divides the product, so N leaves remainder 1 on division by each pᵢ (1)\n• Hence no prime in the list divides N (1)\n• Since N > 1, either N is prime or it has a prime factor not in the list (1)\n• Either case contradicts the list being complete, so there are infinitely many primes (1)` },

      { q: "A student writes: 'In Euclid's proof, N = p₁p₂⋯pₙ + 1 must be prime.' Explain why this is incorrect, and give a numerical example.", marks: 3, markScheme: `• N need only fail to be divisible by any prime in the list; it may still be composite (1)\n• Example: with the list 2, 3, 5, 7, 11, 13 we get N = 30031 (1)\n• 30031 = 59 × 509, so N is composite, but both factors are primes outside the list — which is all the proof requires (1)` },

      { q: 'Prove by contradiction that there is no smallest positive rational number.', marks: 4, markScheme: `• Assume for contradiction that there is a smallest positive rational, r > 0 (1)\n• Consider r/2, which is rational since r is (1)\n• 0 < r/2 < r, so r/2 is a positive rational smaller than r (1)\n• This contradicts r being smallest, so no smallest positive rational exists (1)` },

      { q: 'Prove by contradiction that if n² is even then n is even.', marks: 4, markScheme: `• Assume n² is even but n is odd (1)\n• Write n = 2k + 1 (1)\n• Then n² = 4k² + 4k + 1 = 2(2k² + 2k) + 1, which is odd (1)\n• This contradicts n² being even, so n must be even (1)` },

      { q: 'Explain the structure of a proof by contradiction, setting out the steps in order.', marks: 4, markScheme: `• Assume the negation of the statement to be proved (1)\n• Reason correctly forwards from that assumption (1)\n• Reach a contradiction — of the assumption itself, of a known result, or of a definition (1)\n• Conclude that the assumption is false and hence the original statement is true (1)` },

      { q: 'Write down the negation of each of the following: (a) all swans are white; (b) for every x, P(x) is true; (c) x > 3.', marks: 3, markScheme: `• (a) There exists a swan that is not white (1)\n• (b) There exists an x for which P(x) is false (1)\n• (c) x ≤ 3 (1)` },

      { q: 'A student claims that the negation of "all swans are white" is "no swans are white". Explain why this is wrong.', marks: 2, markScheme: `• The negation only requires that the statement fails in at least one case (1)\n• "No swans are white" is a much stronger claim; the correct negation is "there exists a swan that is not white" (1)` },

      { q: 'Prove that if a and b are both odd, then a² + b² is even but not divisible by 4.', marks: 5, markScheme: `• Write a = 2m + 1 and b = 2n + 1 with m, n integers (1)\n• a² + b² = (4m² + 4m + 1) + (4n² + 4n + 1) (1)\n• = 4(m² + m + n² + n) + 2 (1)\n• This is 2 × an odd-shaped expression, so it is even (1)\n• It leaves remainder 2 on division by 4, so it is not divisible by 4; conclusion stated (1)` },

      { q: 'Prove that (2n + 1)² − (2n − 1)² = 8n for all integers n, and state what this shows about consecutive odd squares.', marks: 3, markScheme: `• Expand both squares: 4n² + 4n + 1 and 4n² − 4n + 1 (1)\n• Subtract to obtain 8n (1)\n• Hence the difference between the squares of consecutive odd numbers is always a multiple of 8 (1)` },

      { q: 'Use the contrapositive to prove that if n² is odd then n is odd.', marks: 4, markScheme: `• State the contrapositive: if n is even then n² is even (1)\n• Let n = 2k (1)\n• n² = 4k² = 2(2k²), which is even (1)\n• The contrapositive is proved, and since it is logically equivalent to the original, the original statement holds (1)` },

      { q: 'Explain what is meant by the statement "without loss of generality", and give an example of when it may legitimately be used.', marks: 3, markScheme: `• It means a particular case may be assumed because the remaining cases follow by an identical argument (1)\n• It is legitimate when the situation is symmetric in the quantities concerned (1)\n• Example: in proving a result about two integers a and b, assuming a ≤ b, since otherwise the labels may simply be exchanged (1)` },

      { q: 'Prove that the sum of a rational number and an irrational number is always irrational.', marks: 4, markScheme: `• Let r be rational and x irrational, and assume for contradiction that r + x is rational, say s (1)\n• Then x = s − r (1)\n• The difference of two rationals is rational, so x would be rational (1)\n• This contradicts x being irrational; hence r + x is irrational (1)` },

      { q: 'Show that the statement "x² = 4 ⇒ x = 2" is false, and write down a correct statement using the appropriate symbol.', marks: 3, markScheme: `• x = −2 also satisfies x² = 4, so the implication fails (1)\n• A correct statement is x = 2 ⇒ x² = 4 (1)\n• Or, using the full solution set, x² = 4 ⇔ x = 2 or x = −2 (1)` },

      { q: 'Explain the difference between the symbols ⇒ and ⇔, giving one example of each.', marks: 4, markScheme: `• ⇒ means "implies": if the left-hand statement is true then the right-hand one is (1)\n• Example: x = 3 ⇒ x² = 9 (1)\n• ⇔ means "if and only if": each statement implies the other (1)\n• Example: x + 1 = 4 ⇔ x = 3 (1)` },

      { q: 'Prove that n³ − n is divisible by 6 for every integer n.', marks: 5, markScheme: `• Factorise n³ − n = n(n² − 1) = (n − 1)n(n + 1) (1)\n• This is the product of three consecutive integers (1)\n• At least one of any three consecutive integers is even, so the product is divisible by 2 (1)\n• Exactly one of any three consecutive integers is divisible by 3, so the product is divisible by 3 (1)\n• Since 2 and 3 are coprime, the product is divisible by 6; conclusion stated (1)` },

      { q: 'Prove by contradiction that √2 + √3 is irrational. You may assume that √6 is irrational.', marks: 5, markScheme: `• Assume √2 + √3 = r, a rational number (1)\n• Square both sides: 2 + 2√6 + 3 = r², so 5 + 2√6 = r² (1)\n• Rearrange to √6 = (r² − 5)/2 (1)\n• The right-hand side is rational, since r is rational (1)\n• This contradicts the assumption that √6 is irrational, so √2 + √3 is irrational (1)` },

      { q: 'Define the terms axiom, lemma and corollary as used in mathematical writing.', marks: 3, markScheme: `• Axiom — a statement assumed to be true without proof (1)\n• Lemma — a smaller result proved as a step towards a larger theorem (1)\n• Corollary — a result that follows readily from a theorem already proved (1)` },

      { q: 'A student attempts to prove that the sum of two even numbers is even by writing "let the numbers be 2n and 2n". Identify the error and give a correct proof.', marks: 4, markScheme: `• The error is using the same letter for both numbers, which only proves the case where they are equal (1)\n• Correct start: let the numbers be 2a and 2b, where a and b are integers (1)\n• Sum = 2a + 2b = 2(a + b) (1)\n• This is 2 × an integer, hence even; conclusion stated (1)` },

      { q: 'Explain why proof by contradiction is a logically valid method of proof.', marks: 3, markScheme: `• A statement and its negation cannot both be true (1)\n• If assuming the negation leads to an impossibility, the negation must be false (1)\n• Therefore the original statement must be true (1)` },
    ]
  },

  '1.2': {
    name: 'Algebra',
    questions: [
      { q: 'Simplify √50 + √18, giving your answer in the form k√2.', marks: 3, markScheme: `• √50 = 5√2 (1)\n• √18 = 3√2 (1)\n• Sum = 8√2 (1)` },
      { q: 'Rationalise the denominator of 1/√7, giving your answer in simplest form.', marks: 2, markScheme: `• Multiply numerator and denominator by √7 (1)\n• Answer √7/7 (1)` },
      { q: 'Express 1/(3 + √5) with a rational denominator, giving your answer in simplest form.', marks: 3, markScheme: `• Multiply numerator and denominator by the conjugate 3 − √5 (1)\n• Denominator becomes 9 − 5 = 4 (1)\n• Answer (3 − √5)/4 (1)` },
      { q: 'Express (√7 − √3)/(√7 + √3) in the form a + b√21, where a and b are rational.', marks: 4, markScheme: `• Multiply numerator and denominator by √7 − √3 (1)\n• Numerator (√7 − √3)² = 10 − 2√21 (1)\n• Denominator 7 − 3 = 4 (1)\n• Answer (10 − 2√21)/4 = 5/2 − (1/2)√21 (1)` },
      { q: 'Explain why √(a + b) is not equal to √a + √b, giving a numerical counter-example.', marks: 2, markScheme: `• The square root does not distribute over addition (1)\n• Counter-example: √(9 + 16) = 5 but √9 + √16 = 7 (1)` },
      { q: 'Evaluate 8^(2/3) without a calculator, showing your method.', marks: 2, markScheme: `• Take the cube root first: 8^(1/3) = 2 (1)\n• Then square: 2² = 4 (1)` },
      { q: 'Simplify (2x²y³)³.', marks: 2, markScheme: `• Cube each factor: 2³ = 8 (1)\n• x⁶ and y⁹, giving 8x⁶y⁹ (1)` },
      { q: 'Write down the values of x⁰, x^(−a) and x^(1/n) for x > 0, and state any restriction.', marks: 3, markScheme: `• x⁰ = 1, provided x ≠ 0 (1)\n• x^(−a) = 1/x^a (1)\n• x^(1/n) = the nth root of x (1)` },
      { q: 'Solve 9^x = 3^(x+1).', marks: 3, markScheme: `• Write 9^x as 3^(2x) (1)\n• Equate indices: 2x = x + 1 (1)\n• x = 1 (1)` },
      { q: 'Solve the quadratic equation 2x² + 7x − 15 = 0 by factorising.', marks: 3, markScheme: `• Factorise as (2x − 3)(x + 5) (1)\n• Set each factor to zero (1)\n• x = 3/2 or x = −5 (1)` },
      { q: 'Express x² + 6x + 2 in the form (x + a)² + b, and hence state the coordinates of the minimum point of y = x² + 6x + 2.', marks: 4, markScheme: `• (x + 3)² accounts for x² + 6x (1)\n• Subtract 9 and add 2 to give (x + 3)² − 7 (1)\n• Minimum where the squared term is zero, at x = −3 (1)\n• Minimum point (−3, −7) (1)` },
      { q: 'Solve x⁴ − 5x² + 4 = 0.', marks: 4, markScheme: `• Substitute u = x², giving u² − 5u + 4 = 0 (1)\n• Factorise (u − 1)(u − 4) = 0, so u = 1 or u = 4 (1)\n• x² = 1 gives x = ±1 (1)\n• x² = 4 gives x = ±2; four roots in total (1)` },
      { q: 'Solve 2^(2x) − 5(2^x) + 4 = 0.', marks: 4, markScheme: `• Let u = 2^x, so 2^(2x) = u² (1)\n• u² − 5u + 4 = 0, factorising to (u − 1)(u − 4) = 0 (1)\n• u = 1 gives 2^x = 1, so x = 0 (1)\n• u = 4 gives 2^x = 4, so x = 2 (1)` },
      { q: 'Write down the discriminant of ax² + bx + c = 0 and state what each of the three cases tells you about the roots.', marks: 4, markScheme: `• Discriminant is b² − 4ac (1)\n• If b² − 4ac > 0 there are two distinct real roots (1)\n• If b² − 4ac = 0 there is one repeated root (1)\n• If b² − 4ac < 0 there are no real roots (1)` },
      { q: 'Find the values of k for which kx² + 4x + k = 0 has a repeated root.', marks: 3, markScheme: `• Set the discriminant to zero: 16 − 4k² = 0 (1)\n• k² = 4 (1)\n• k = ±2 (1)` },
      { q: 'Find the set of values of k for which kx² + (k + 3)x + 4 = 0 has no real roots.', marks: 5, markScheme: `• Require discriminant < 0 (1)\n• (k + 3)² − 16k < 0 (1)\n• Expand: k² − 10k + 9 < 0 (1)\n• Factorise (k − 1)(k − 9) < 0 (1)\n• Conclude 1 < k < 9 (1)` },
      { q: 'Find the condition on m and c for the line y = mx + c to be a tangent to the curve y = x².', marks: 4, markScheme: `• Set x² = mx + c (1)\n• Rearrange to x² − mx − c = 0 (1)\n• Tangency requires the discriminant to be zero (1)\n• m² + 4c = 0 (1)` },
      { q: 'Solve the simultaneous equations 2x + 3y = 7 and 3x − y = 5.', marks: 3, markScheme: `• Multiply the second equation by 3 and add, or substitute y = 3x − 5 (1)\n• Obtain x = 2 (1)\n• y = 1 (1)` },
      { q: 'Solve the simultaneous equations y = x + 1 and x² + y² = 25.', marks: 5, markScheme: `• Substitute the linear equation into the quadratic (1)\n• x² + (x + 1)² = 25, giving 2x² + 2x + 1 = 25 (1)\n• Simplify to x² + x − 12 = 0 (1)\n• Factorise (x + 4)(x − 3) = 0, so x = −4 or x = 3 (1)\n• Pair the values correctly: (−4, −3) and (3, 4) (1)` },
      { q: 'Explain the geometric meaning of the solutions of a pair of simultaneous equations, and say what it means if the resulting quadratic has no real roots.', marks: 3, markScheme: `• The solutions are the coordinates of the points of intersection of the two graphs (1)\n• No real roots means the quadratic has a negative discriminant (1)\n• Hence the graphs do not intersect (1)` },
      { q: 'Solve the inequality 3x − 7 < 5.', marks: 2, markScheme: `• Add 7 to both sides: 3x < 12 (1)\n• Divide by 3: x < 4 (1)` },
      { q: 'Solve the inequality 5 − 2x ≥ 11, explaining carefully any change of sign.', marks: 3, markScheme: `• Rearrange to −2x ≥ 6 (1)\n• Divide by −2, reversing the inequality because the divisor is negative (1)\n• x ≤ −3 (1)` },
      { q: 'Solve the inequality x² − 4x − 5 > 0.', marks: 4, markScheme: `• Factorise (x − 5)(x + 1) > 0 (1)\n• Critical values x = −1 and x = 5 (1)\n• Consider the shape: the parabola opens upwards, so it is positive outside the roots (1)\n• x < −1 or x > 5 (1)` },
      { q: 'Solve the inequality 2x² + 5x − 3 ≤ 0.', marks: 4, markScheme: `• Factorise (2x − 1)(x + 3) ≤ 0 (1)\n• Critical values x = −3 and x = 1/2 (1)\n• Upward parabola, so it is negative or zero between the roots (1)\n• −3 ≤ x ≤ 1/2 (1)` },
      { q: 'Solve the inequality (2x + 1)/(x − 3) > 1, explaining why you may not simply multiply both sides by (x − 3).', marks: 5, markScheme: `• Explain that the sign of x − 3 is unknown, so multiplying could reverse the inequality (1)\n• Subtract 1 and combine over a common denominator: (2x + 1 − (x − 3))/(x − 3) > 0 (1)\n• Simplify to (x + 4)/(x − 3) > 0 (1)\n• Critical values x = −4 and x = 3 (1)\n• x < −4 or x > 3 (1)` },
      { q: 'Express the solution set "x ≤ 1 or x ≥ 4" in set notation.', marks: 2, markScheme: `• Recognise this as a union of two sets (1)\n• {x : x ≤ 1} ∪ {x : x ≥ 4} (1)` },
      { q: 'A student writes the solution of x² − 4x − 5 > 0 as "x < −1 and x > 5". Explain why this is wrong and give the correct form.', marks: 2, markScheme: `• No number is simultaneously less than −1 and greater than 5, so the set described is empty (1)\n• The correct connective is "or": x < −1 or x > 5 (1)` },
      { q: 'The quantity y is inversely proportional to x². Given that y = 4 when x = 3, find y when x = 6.', marks: 4, markScheme: `• Write y = k/x² (1)\n• Substitute to find 4 = k/9, so k = 36 (1)\n• Substitute x = 6: y = 36/36 (1)\n• y = 1 (1)` },
      { q: 'The quantity y is directly proportional to √x. If x is multiplied by 9, by what factor is y multiplied? Justify your answer.', marks: 3, markScheme: `• Write y = k√x (1)\n• Replacing x by 9x gives y = k√(9x) = 3k√x (1)\n• So y is multiplied by 3 (1)` },
      { q: 'Express (5x + 1)/((x + 1)(x − 2)) in partial fractions.', marks: 4, markScheme: `• Write as A/(x + 1) + B/(x − 2) (1)\n• Multiply through: 5x + 1 = A(x − 2) + B(x + 1) (1)\n• Substitute x = 2 to find B = 11/3 (1)\n• Substitute x = −1 to find A = 4/3 (1)` },
      { q: 'Express (2x + 3)/((x + 1)(x + 2)) in partial fractions.', marks: 4, markScheme: `• Write as A/(x + 1) + B/(x + 2) (1)\n• 2x + 3 = A(x + 2) + B(x + 1) (1)\n• Substitute x = −1 to find A = 1 (1)\n• Substitute x = −2 to find B = 1 (1)` },
      { q: 'Write down the correct form to assume when expressing (2x + 3)/((x + 1)²(x − 2)) in partial fractions, and explain why the repeated factor needs two terms.', marks: 3, markScheme: `• Form is A/(x + 1) + B/(x + 1)² + C/(x − 2) (1)\n• The repeated factor requires terms with both the first and second powers in the denominator (1)\n• Omitting the A/(x + 1) term gives a system with no solution, since the general numerator over (x + 1)² is linear, not constant (1)` },
      { q: 'Make r the subject of the formula A = πr² + 2πrh.', marks: 4, markScheme: `• Recognise this as a quadratic in r: πr² + 2πrh − A = 0 (1)\n• Apply the quadratic formula with a = π, b = 2πh, c = −A (1)\n• r = [−2πh ± √(4π²h² + 4πA)]/(2π) (1)\n• Take the positive root since r > 0, giving r = −h + √(h² + A/π) (1)` },
      { q: 'Make x the subject of y = (x + 1)/(x − 2).', marks: 4, markScheme: `• Multiply through: y(x − 2) = x + 1 (1)\n• Expand: yx − 2y = x + 1 (1)\n• Collect x terms: x(y − 1) = 2y + 1 (1)\n• x = (2y + 1)/(y − 1) (1)` },
      { q: 'Solve the equation 3/(x − 1) = x + 1.', marks: 3, markScheme: `• Multiply both sides by x − 1: 3 = (x + 1)(x − 1) (1)\n• Expand to 3 = x² − 1, so x² = 4 (1)\n• x = 2 or x = −2, checking neither makes the denominator zero (1)` },
      { q: 'Given that α and β are the roots of x² + bx + c = 0, write down expressions for α + β and αβ in terms of b and c.', marks: 2, markScheme: `• α + β = −b (1)\n• αβ = c (1)` },
      { q: 'Simplify (√3 + 1)/(√3 − 1) + (√3 − 1)/(√3 + 1).', marks: 4, markScheme: `• Rationalise the first fraction to (√3 + 1)²/2 = 2 + √3 (1)\n• Rationalise the second to (√3 − 1)²/2 = 2 − √3 (1)\n• Add the two results (1)\n• Total = 4 (1)` },
      { q: 'Solve x³ − 4x = 0.', marks: 3, markScheme: `• Factorise x(x² − 4) = 0 (1)\n• Further factorise x(x − 2)(x + 2) = 0 (1)\n• x = 0, x = 2 or x = −2 (1)` },
      { q: 'Explain what is meant by an identity, and state how it differs from an equation. Give one example of each.', marks: 4, markScheme: `• An identity is true for every value of the variable (1)\n• An equation is true only for particular values (1)\n• Example identity: (x + 1)² ≡ x² + 2x + 1 (1)\n• Example equation: x² = 9, true only for x = ±3 (1)` },
      { q: 'The equation x² + kx + 9 = 0 has equal roots. Find the possible values of k, and state the repeated root in each case.', marks: 4, markScheme: `• Discriminant zero: k² − 36 = 0 (1)\n• k = ±6 (1)\n• For k = 6 the equation is (x + 3)² = 0, root x = −3 (1)\n• For k = −6 the equation is (x − 3)² = 0, root x = 3 (1)` },
    ]
  },

  '1.3': {
    name: 'Functions',
    questions: [
      { q: 'State the factor theorem and the remainder theorem.', marks: 2, markScheme: `• Factor theorem: if f(a) = 0 then (x − a) is a factor of f(x), and conversely (1)\n• Remainder theorem: the remainder on dividing f(x) by (x − a) is f(a) (1)` },
      { q: 'Show that (x + 3) is a factor of f(x) = x³ + 2x² − 5x − 6, and hence factorise f(x) completely.', marks: 5, markScheme: `• Apply the factor theorem by evaluating f(−3) (1)\n• f(−3) = −27 + 18 + 15 − 6 = 0, so (x + 3) is a factor (1)\n• Divide to obtain the quadratic x² − x − 2 (1)\n• Factorise as (x − 2)(x + 1) (1)\n• f(x) = (x + 3)(x − 2)(x + 1) (1)` },
      { q: 'Find the remainder when x³ + 2x² − x + 4 is divided by (x + 1).', marks: 2, markScheme: `• Apply the remainder theorem with a = −1 (1)\n• f(−1) = −1 + 2 + 1 + 4 = 6 (1)` },
      { q: 'Given that (x − 2) is a factor of x³ + ax² − 5x + 6, find the value of a.', marks: 3, markScheme: `• Set f(2) = 0 (1)\n• 8 + 4a − 10 + 6 = 0, so 4 + 4a = 0 (1)\n• a = −1 (1)` },
      { q: 'Fully factorise x³ − 3x + 2, and describe the behaviour of the curve y = x³ − 3x + 2 at each root.', marks: 5, markScheme: `• Test small values: f(1) = 0, so (x − 1) is a factor (1)\n• Divide to obtain x² + x − 2 (1)\n• Factorise as (x + 2)(x − 1) (1)\n• Complete factorisation (x − 1)²(x + 2) (1)\n• The curve touches the axis at x = 1 (repeated root) and crosses at x = −2 (1)` },
      { q: 'Fully factorise 2x³ − x² − 13x − 6.', marks: 4, markScheme: `• Test divisors of 6: f(3) = 54 − 9 − 39 − 6 = 0, so (x − 3) is a factor (1)\n• Divide to obtain 2x² + 5x + 2 (1)\n• Factorise as (2x + 1)(x + 2) (1)\n• Answer (x − 3)(2x + 1)(x + 2) (1)` },
      { q: 'Explain why, when searching for a first factor of a cubic with integer coefficients, it is sensible to test the divisors of the constant term.', marks: 2, markScheme: `• Any integer root must divide the constant term, since the product of the roots relates to it (1)\n• This gives a short finite list of candidates rather than testing arbitrary values (1)` },
      { q: 'Define the domain and range of a function, and state the natural domain and range of f(x) = √(x − 3).', marks: 4, markScheme: `• Domain is the set of permitted input values (1)\n• Range is the set of output values the function takes (1)\n• Domain x ≥ 3, since the expression under the root cannot be negative (1)\n• Range f(x) ≥ 0 (1)` },
      { q: 'Explain the difference between a one-to-one and a many-to-one function, giving an example of each.', marks: 4, markScheme: `• One-to-one: each output arises from exactly one input (1)\n• Example f(x) = 2x + 1 (1)\n• Many-to-one: different inputs may give the same output (1)\n• Example f(x) = x², since f(2) = f(−2) = 4 (1)` },
      { q: 'Find the range of f(x) = x² − 4x + 7 for real x, showing your method.', marks: 3, markScheme: `• Complete the square: f(x) = (x − 2)² + 3 (1)\n• (x − 2)² ≥ 0 for all real x, with minimum 0 at x = 2 (1)\n• Range is f(x) ≥ 3 (1)` },
      { q: 'The functions f and g are defined by f(x) = 2x + 3 and g(x) = x². Find fg(x) and gf(x), and state whether they are equal.', marks: 4, markScheme: `• fg(x) means f(g(x)) (1)\n• fg(x) = 2x² + 3 (1)\n• gf(x) = (2x + 3)² (1)\n• They are not equal, so composition is not commutative (1)` },
      { q: 'The function f is defined by f(x) = 2x + 5. Find f⁻¹(x).', marks: 3, markScheme: `• Write y = 2x + 5 (1)\n• Rearrange: x = (y − 5)/2 (1)\n• f⁻¹(x) = (x − 5)/2 (1)` },
      { q: 'Find the inverse of f(x) = 3/(x − 2), stating the domain of the inverse.', marks: 4, markScheme: `• Write y = 3/(x − 2) (1)\n• Rearrange: x − 2 = 3/y (1)\n• f⁻¹(x) = 3/x + 2 (1)\n• Domain x ≠ 0 (1)` },
      { q: 'Find the inverse of f(x) = (2x + 1)/(x − 3).', marks: 4, markScheme: `• y(x − 3) = 2x + 1 (1)\n• yx − 3y = 2x + 1 (1)\n• x(y − 2) = 3y + 1 (1)\n• f⁻¹(x) = (3x + 1)/(x − 2) (1)` },
      { q: 'The function f is defined by f(x) = x² − 4x with domain x ≥ 2. Find f⁻¹(x), explaining how the domain determines your choice of sign.', marks: 5, markScheme: `• Complete the square: y = (x − 2)² − 4 (1)\n• Rearrange: (x − 2)² = y + 4 (1)\n• x − 2 = ±√(y + 4) (1)\n• The domain x ≥ 2 requires x − 2 ≥ 0, so the positive root is taken (1)\n• f⁻¹(x) = 2 + √(x + 4) (1)` },
      { q: 'Explain why f(x) = x² has no inverse over the real numbers, and state a restricted domain on which an inverse does exist.', marks: 3, markScheme: `• f is many-to-one, since f(a) = f(−a) for every a (1)\n• An inverse requires each output to come from exactly one input (1)\n• Restricting to x ≥ 0 (or x ≤ 0) makes f one-to-one, so an inverse exists (1)` },
      { q: 'State the relationship between the graphs of y = f(x) and y = f⁻¹(x), and explain what this implies about any point where they intersect.', marks: 3, markScheme: `• The graph of the inverse is the reflection of the original in the line y = x (1)\n• Domain and range are interchanged between f and f⁻¹ (1)\n• Any intersection therefore lies on the line y = x (1)` },
      { q: 'Explain what must be true for the composite function gf to exist.', marks: 2, markScheme: `• The output of f becomes the input of g (1)\n• So the range of f must lie within the domain of g (1)` },
      { q: 'Write down the definition of |x| as a piecewise function, and sketch the graph of y = |x|.', marks: 3, markScheme: `• |x| = x for x ≥ 0 (1)\n• |x| = −x for x < 0 (1)\n• Sketch shows a V with vertex at the origin and gradients ±1 (1)` },
      { q: 'Solve |2x − 1| = 5.', marks: 3, markScheme: `• Consider 2x − 1 = 5, giving x = 3 (1)\n• Consider 2x − 1 = −5 (1)\n• x = −2, so the solutions are x = 3 and x = −2 (1)` },
      { q: 'Solve |x − 1| = |x + 3|.', marks: 3, markScheme: `• Square both sides, valid since both are non-negative (1)\n• x² − 2x + 1 = x² + 6x + 9, giving −8x = 8 (1)\n• x = −1 (1)` },
      { q: 'Solve |x + 2| > 3.', marks: 3, markScheme: `• Split into two cases (1)\n• x + 2 > 3 gives x > 1 (1)\n• x + 2 < −3 gives x < −5, so x < −5 or x > 1 (1)` },
      { q: 'Solve |x − 3| < 2 and express your answer as a single inequality.', marks: 3, markScheme: `• Use the equivalence |A| < a ⇔ −a < A < a (1)\n• −2 < x − 3 < 2 (1)\n• 1 < x < 5 (1)` },
      { q: 'Solve |2x − 3| < |x|, justifying your method.', marks: 5, markScheme: `• Both sides are non-negative, so squaring is valid (1)\n• 4x² − 12x + 9 < x² (1)\n• 3x² − 12x + 9 < 0, so x² − 4x + 3 < 0 (1)\n• Factorise (x − 1)(x − 3) < 0 (1)\n• 1 < x < 3 (1)` },
      { q: 'Explain why squaring both sides is a valid method for solving |A| = |B| but not for solving |A| = B in general.', marks: 3, markScheme: `• Squaring is valid when both sides are known to be non-negative (1)\n• Two moduli are always non-negative, so |A| = |B| may be squared safely (1)\n• If B could be negative, squaring introduces solutions that do not satisfy the original equation, so any answers must be checked (1)` },
      { q: 'Describe how to obtain the graph of y = |f(x)| from the graph of y = f(x).', marks: 2, markScheme: `• Reflect in the x-axis any part of the graph lying below it (1)\n• Leave the part on or above the x-axis unchanged (1)` },
      { q: 'Describe how to obtain the graph of y = f(|x|) from the graph of y = f(x).', marks: 2, markScheme: `• Keep the part of the graph for x ≥ 0 (1)\n• Reflect that part in the y-axis, discarding the original x < 0 part (1)` },
      { q: 'Explain the essential difference between the transformations y = |f(x)| and y = f(|x|).', marks: 2, markScheme: `• |f(x)| takes the modulus of the output, so it folds the graph upwards about the x-axis (1)\n• f(|x|) takes the modulus of the input, so it makes the graph symmetric about the y-axis (1)` },
      { q: 'Sketch y = |x − 2| − 1, stating the coordinates of the vertex and of the points where the graph meets the x-axis.', marks: 4, markScheme: `• Vertex at (2, −1) (1)\n• V-shape with gradients ±1 (1)\n• Solve |x − 2| = 1 to find the x-intercepts (1)\n• Intercepts at (1, 0) and (3, 0) (1)` },
      { q: 'Solve |x² − 4| = 3.', marks: 4, markScheme: `• Case x² − 4 = 3 gives x² = 7 (1)\n• x = ±√7 (1)\n• Case x² − 4 = −3 gives x² = 1 (1)\n• x = ±1, so four solutions in total (1)` },
      { q: 'Explain why the equation |x − 1| + |x + 2| = 3 has infinitely many solutions, and state the solution set.', marks: 4, markScheme: `• The two terms measure the distances from x to 1 and to −2 (1)\n• The distance between −2 and 1 is 3 (1)\n• For any x between −2 and 1 the two distances add to exactly 3 (1)\n• Solution set is −2 ≤ x ≤ 1 (1)` },
      { q: 'The function f is defined by f(x) = x + 3. Find ff(x) and fff(x).', marks: 2, markScheme: `• ff(x) = (x + 3) + 3 = x + 6 (1)\n• fff(x) = x + 9 (1)` },
      { q: 'Given f(x) = 1/x with domain x > 0, state the range, and explain why f is its own inverse.', marks: 3, markScheme: `• Range is f(x) > 0 (1)\n• Applying f twice gives f(f(x)) = 1/(1/x) = x (1)\n• Since ff(x) = x, f is its own inverse (1)` },
      { q: 'A polynomial of degree 4 is divided by a quadratic. State the greatest possible degree of the remainder, and justify your answer.', marks: 2, markScheme: `• The remainder must have degree less than the divisor (1)\n• The divisor has degree 2, so the remainder has degree at most 1 (1)` },
      { q: 'Explain why a graph represents a function if and only if every vertical line meets it at most once.', marks: 2, markScheme: `• A function assigns exactly one output to each input (1)\n• A vertical line meeting the graph twice would mean one input with two outputs, so the relation would not be a function (1)` },
      { q: 'The function f is defined by f(x) = x² with domain −2 ≤ x ≤ 3. Find the range.', marks: 3, markScheme: `• The minimum occurs at x = 0, giving f = 0 (1)\n• Evaluate at the endpoints: f(−2) = 4 and f(3) = 9 (1)\n• Range is 0 ≤ f(x) ≤ 9 (1)` },
      { q: 'Determine the number of real solutions of |x² − 1| = k for 0 < k < 1, justifying your answer.', marks: 4, markScheme: `• Case x² − 1 = k gives x² = 1 + k, so x = ±√(1 + k) — two solutions (1)\n• Case x² − 1 = −k gives x² = 1 − k (1)\n• Since 0 < k < 1, 1 − k is positive, giving x = ±√(1 − k) — two more solutions (1)\n• Four real solutions in total (1)` },
      { q: 'Given f(x) = 2x − 1 and g(x) = x + 4, solve fg(x) = gf(x).', marks: 4, markScheme: `• fg(x) = 2(x + 4) − 1 = 2x + 7 (1)\n• gf(x) = (2x − 1) + 4 = 2x + 3 (1)\n• Set equal: 2x + 7 = 2x + 3 (1)\n• This gives 7 = 3, which is impossible, so there are no solutions (1)` },
      { q: 'Explain why the graph of y = x³ − 3x + 2 touches the x-axis at one point and crosses it at another, referring to the factorised form.', marks: 3, markScheme: `• Factorised form is (x − 1)²(x + 2) (1)\n• The squared factor at x = 1 means the curve meets the axis without changing sign, so it touches (1)\n• The single factor at x = −2 means the curve changes sign there, so it crosses (1)` },
      { q: 'Given that f(x) = ax³ + bx² − 4x + 3 has factors (x − 1) and (x + 3), find a and b.', marks: 5, markScheme: `• f(1) = 0 gives a + b − 4 + 3 = 0, so a + b = 1 (1)\n• f(−3) = 0 gives −27a + 9b + 12 + 3 = 0 (1)\n• Simplify to −27a + 9b = −15, i.e. −9a + 3b = −5 (1)\n• Solve simultaneously with a + b = 1 (1)\n• a = 2/3 and b = 1/3 (1)` },
    ]
  },

  '1.4': {
    name: 'Graphs',
    questions: [
      { q: 'List four features that a sketch of a curve should show if the question asks for key features.', marks: 4, markScheme: `• Intercepts with both axes (1)\n• Any asymptotes, drawn dashed and labelled with their equations (1)\n• Turning points where relevant (1)\n• The behaviour as x tends to plus and minus infinity (1)` },
      { q: 'Describe the single transformation that maps y = f(x) onto y = f(x − 4).', marks: 2, markScheme: `• A translation (1)\n• 4 units in the positive x-direction (1)` },
      { q: 'Describe the single transformation that maps y = f(x) onto y = f(x) + 3.', marks: 2, markScheme: `• A translation (1)\n• 3 units in the positive y-direction (1)` },
      { q: 'Write down, as a column vector, the translation that maps y = f(x) onto y = f(x − 2) + 5.', marks: 2, markScheme: `• Horizontal component +2, since f(x − 2) shifts right (1)\n• Vector is (2, 5) written as a column (1)` },
      { q: 'Describe the transformation that maps y = f(x) onto y = 3f(x), and state its effect on the y-coordinate of any point.', marks: 2, markScheme: `• A stretch parallel to the y-axis, scale factor 3 (1)\n• Every y-coordinate is multiplied by 3, while x-coordinates are unchanged (1)` },
      { q: 'Describe the transformation that maps y = f(x) onto y = f(2x), and state its effect on the x-coordinate of any point.', marks: 2, markScheme: `• A stretch parallel to the x-axis, scale factor 1/2 (1)\n• Every x-coordinate is halved, while y-coordinates are unchanged (1)` },
      { q: 'Explain why transformations applied inside the function bracket behave in the opposite sense to what might be expected.', marks: 3, markScheme: `• The transformation acts on the input before the function is applied (1)\n• To obtain the same output, the new x must be adjusted in the opposite direction (1)\n• So f(x + a) shifts the graph left, and f(ax) compresses it by a factor of a (1)` },
      { q: 'Describe the transformations that map y = f(x) onto y = −f(x) and onto y = f(−x).', marks: 2, markScheme: `• y = −f(x) is a reflection in the x-axis (1)\n• y = f(−x) is a reflection in the y-axis (1)` },
      { q: 'The curve y = f(x) has a maximum at (2, 5). Find the coordinates of the maximum of y = 3f(x + 1) − 2.', marks: 4, markScheme: `• The translation x → x + 1 moves the point 1 unit left, so x becomes 1 (1)\n• The stretch of factor 3 parallel to the y-axis gives y = 15 (1)\n• The translation 2 units down gives y = 13 (1)\n• Maximum at (1, 13) (1)` },
      { q: 'Describe y = 2f(3x − 6) as a sequence of transformations of y = f(x), explaining why the inside must be factorised first.', marks: 5, markScheme: `• Factorise the inside: 3x − 6 = 3(x − 2) (1)\n• Explain that without factorising, the order of the stretch and translation would be wrong, since the stretch also scales the translation (1)\n• Translate 2 units in the positive x-direction (1)\n• Stretch parallel to the x-axis, scale factor 1/3 (1)\n• Stretch parallel to the y-axis, scale factor 2 (1)` },
      { q: 'State the equations of the asymptotes of y = 1/(x − 3), and explain how each is found.', marks: 4, markScheme: `• Vertical asymptote x = 3 (1)\n• Found where the denominator is zero and the numerator is not (1)\n• Horizontal asymptote y = 0 (1)\n• Found from the behaviour of the function as x tends to plus or minus infinity (1)` },
      { q: 'Find the equations of the asymptotes of y = 2/(x + 1) − 3.', marks: 3, markScheme: `• Vertical asymptote where x + 1 = 0, so x = −1 (1)\n• As x tends to infinity the fraction tends to 0 (1)\n• Horizontal asymptote y = −3 (1)` },
      { q: 'Find the horizontal asymptote of y = x/(x − 1), showing your reasoning.', marks: 3, markScheme: `• Divide numerator and denominator by x (1)\n• y = 1/(1 − 1/x) (1)\n• As x tends to infinity, 1/x tends to 0, so y tends to 1; asymptote y = 1 (1)` },
      { q: 'Show that y = (x² + 1)/x has an oblique asymptote, and state its equation.', marks: 3, markScheme: `• Divide to obtain y = x + 1/x (1)\n• As x tends to plus or minus infinity, 1/x tends to 0 (1)\n• The curve approaches the line y = x, which is the oblique asymptote (1)` },
      { q: 'Explain why the curve y = (x² − 1)/(x − 1) does not have an asymptote at x = 1, and describe what happens there instead.', marks: 3, markScheme: `• Factorise the numerator: (x − 1)(x + 1) (1)\n• The factor (x − 1) cancels, leaving y = x + 1 (1)\n• The function is undefined at x = 1, so the graph is the line y = x + 1 with a single point removed — a hole, not an asymptote (1)` },
      { q: 'Explain why a curve may cross a horizontal asymptote but can never cross a vertical one.', marks: 3, markScheme: `• A horizontal asymptote describes behaviour only as x tends to infinity, so the curve may cross it at finite values (1)\n• A vertical asymptote occurs where the function is undefined (1)\n• The curve therefore has no point at that x-value and cannot cross it (1)` },
      { q: 'Sketch y = x²(x − 2), stating the coordinates of the points where the curve meets the x-axis and describing the behaviour at each.', marks: 4, markScheme: `• Roots at x = 0 (repeated) and x = 2 (1)\n• At x = 0 the curve touches the axis and turns back (1)\n• At x = 2 the curve crosses the axis (1)\n• Positive cubic shape: from bottom-left, touching at the origin, crossing at (2, 0) and rising (1)` },
      { q: 'The curve y = (x + 1)(x − 2)(x − 4) meets the y-axis at P. Find the coordinates of P.', marks: 2, markScheme: `• Substitute x = 0 (1)\n• y = 1 × (−2) × (−4) = 8, so P is (0, 8) (1)` },
      { q: 'Explain, in terms of the factorised form, how you can tell whether a polynomial curve crosses or touches the x-axis at a given root.', marks: 3, markScheme: `• A factor appearing once means the curve crosses the axis (1)\n• A squared factor means the curve touches the axis and turns back (1)\n• A cubed factor means the curve crosses but flattens at the crossing, giving a point of inflection (1)` },
      { q: 'State the maximum number of real roots and the maximum number of turning points of a polynomial of degree n.', marks: 2, markScheme: `• At most n real roots (1)\n• At most n − 1 turning points (1)` },
      { q: 'Sketch y = 1/x², stating its asymptotes and explaining why the curve lies entirely above the x-axis.', marks: 3, markScheme: `• Asymptotes x = 0 and y = 0 (1)\n• x² is positive for every x ≠ 0, so 1/x² is always positive (1)\n• Sketch shows two branches, both above the x-axis, symmetric about the y-axis (1)` },
      { q: 'Find the vertical asymptotes of y = 1/(x² − 4).', marks: 3, markScheme: `• Set the denominator to zero: x² − 4 = 0 (1)\n• Factorise (x − 2)(x + 2) = 0 (1)\n• Asymptotes at x = 2 and x = −2 (1)` },
      { q: 'Determine the number of points of intersection of y = x² and y = x + 2, showing your working.', marks: 3, markScheme: `• Set x² = x + 2, so x² − x − 2 = 0 (1)\n• Factorise (x − 2)(x + 1) = 0 (1)\n• Two distinct real roots, so the graphs meet at two points (1)` },
      { q: 'By sketching a suitable curve, determine the number of real solutions of x³ − 3x = k when −2 < k < 2.', marks: 4, markScheme: `• Differentiate to find turning points: 3x² − 3 = 0, so x = ±1 (1)\n• Local maximum at (−1, 2) and local minimum at (1, −2) (1)\n• A horizontal line y = k with −2 < k < 2 lies strictly between the turning values (1)\n• The line cuts the curve three times, so there are three real solutions (1)` },
      { q: 'Explain why the graphs of y = eˣ and y = x + 1 meet exactly once, and state the point of intersection.', marks: 3, markScheme: `• At x = 0 both equal 1, so (0, 1) is a point of intersection (1)\n• The line is the tangent to y = eˣ at that point (1)\n• Since eˣ ≥ x + 1 for all x with equality only at x = 0, there are no further intersections (1)` },
      { q: 'State the conditions on f for the graph of y = f(x) to be symmetric about the y-axis and for it to be symmetric about the origin.', marks: 2, markScheme: `• Symmetric about the y-axis if f(−x) = f(x) for all x (1)\n• Symmetric about the origin if f(−x) = −f(x) for all x (1)` },
      { q: 'Sketch y = ln x, stating the asymptote, the domain and one point on the curve.', marks: 3, markScheme: `• Domain x > 0 (1)\n• Vertical asymptote x = 0 (1)\n• Passes through (1, 0), increasing but flattening (1)` },
      { q: 'Sketch y = 2ˣ and y = 2^(−x) on the same axes, stating the asymptote and the point of intersection.', marks: 4, markScheme: `• Both pass through (0, 1), which is the point of intersection (1)\n• Both have horizontal asymptote y = 0 (1)\n• y = 2ˣ increases as x increases (1)\n• y = 2^(−x) is its reflection in the y-axis and decreases as x increases (1)` },
      { q: 'The curve y = (x − 3)² − 4 crosses the x-axis at two points. Find their coordinates.', marks: 3, markScheme: `• Set (x − 3)² − 4 = 0, so (x − 3)² = 4 (1)\n• x − 3 = ±2 (1)\n• Points (1, 0) and (5, 0) (1)` },
      { q: 'Find the coordinates of the minimum point of y = x + 1/x for x > 0.', marks: 4, markScheme: `• Differentiate: dy/dx = 1 − 1/x² (1)\n• Set to zero: x² = 1, so x = 1 for x > 0 (1)\n• y = 1 + 1 = 2 (1)\n• Minimum point (1, 2) (1)` },
      { q: 'Find the value of k for which the curve y = k/(x − 2) + 1 passes through the origin.', marks: 3, markScheme: `• Substitute x = 0 and y = 0 (1)\n• 0 = k/(−2) + 1, so k/2 = 1 (1)\n• k = 2 (1)` },
      { q: 'Sketch y = 1/(x² + 1), stating any turning point and any asymptote.', marks: 3, markScheme: `• The denominator is never zero, so there is no vertical asymptote (1)\n• Maximum at (0, 1), since the denominator is least there (1)\n• As x tends to plus or minus infinity, y tends to 0; horizontal asymptote y = 0 (1)` },
      { q: 'The curve y = f(x) passes through (3, 0). State the coordinates of the corresponding point on y = f(2x) and on y = f(x) − 4.', marks: 2, markScheme: `• On y = f(2x) the x-coordinate is halved, giving (1.5, 0) (1)\n• On y = f(x) − 4 the y-coordinate falls by 4, giving (3, −4) (1)` },
      { q: 'Explain how the graph of y = |f(x)| differs from that of y = f(x), and describe the effect on any x-axis intercepts.', marks: 3, markScheme: `• Parts of the graph below the x-axis are reflected up into it (1)\n• Parts on or above the axis are unchanged (1)\n• The x-intercepts stay in the same places, but the curve now touches rather than crosses at each of them (1)` },
      { q: 'Sketch y = x⁴ and y = x² on the same axes for −1 ≤ x ≤ 1, and state which lies above the other in that interval.', marks: 3, markScheme: `• Both are symmetric about the y-axis with a minimum at the origin (1)\n• They meet at (0, 0), (1, 1) and (−1, 1) (1)\n• For 0 < |x| < 1, x⁴ < x², so y = x² lies above y = x⁴ (1)` },
      { q: 'A curve has equation y = a/(x − b) + c. State how a, b and c affect the graph.', marks: 3, markScheme: `• b determines the vertical asymptote, at x = b (1)\n• c determines the horizontal asymptote, at y = c (1)\n• a determines the steepness of the branches and, by its sign, which pair of regions they occupy (1)` },
      { q: 'The graph of y = f(x) is stretched by scale factor 1/2 parallel to the y-axis and then translated 3 units up. Write down the equation of the resulting curve.', marks: 2, markScheme: `• The stretch gives y = (1/2)f(x) (1)\n• The translation gives y = (1/2)f(x) + 3 (1)` },
      { q: 'Explain how the graph of y = f(x) can be used to solve the equation f(x) = k graphically.', marks: 3, markScheme: `• Draw the horizontal line y = k on the same axes (1)\n• The solutions are the x-coordinates of the points where the line meets the curve (1)\n• The number of intersections gives the number of real solutions (1)` },
      { q: 'Sketch y = √x and y = x on the same axes for x ≥ 0, stating the points of intersection and which curve is higher for 0 < x < 1.', marks: 4, markScheme: `• Both pass through the origin (1)\n• They also meet at (1, 1) (1)\n• For 0 < x < 1, √x > x, so y = √x is higher (1)\n• For x > 1 the line y = x is higher (1)` },
      { q: 'Describe fully the transformation that maps y = x² onto y = (x + 2)² − 5, and state the coordinates of the new vertex.', marks: 3, markScheme: `• A translation 2 units in the negative x-direction (1)\n• Followed by a translation 5 units in the negative y-direction (1)\n• New vertex at (−2, −5) (1)` },
    ]
  },

  '1.5': {
    name: 'Coordinate Geometry',
    questions: [
      { q: 'Find the gradient, midpoint and length of the line segment joining A(1, 2) and B(3, 8).', marks: 4, markScheme: `• Gradient = (8 − 2)/(3 − 1) = 3 (1)\n• Midpoint = ((1 + 3)/2, (2 + 8)/2) (1)\n• Midpoint = (2, 5) (1)\n• Length = √(2² + 6²) = √40 = 2√10 (1)` },
      { q: 'Find the equation of the line through (2, 3) with gradient −4, giving your answer in the form y = mx + c.', marks: 3, markScheme: `• Use y − y₁ = m(x − x₁) (1)\n• y − 3 = −4(x − 2) (1)\n• y = −4x + 11 (1)` },
      { q: 'Find the equation of the line through (2, 3) parallel to y = 4x − 1.', marks: 3, markScheme: `• Parallel lines have equal gradients, so m = 4 (1)\n• y − 3 = 4(x − 2) (1)\n• y = 4x − 5 (1)` },
      { q: 'Find the equation of the line through the origin perpendicular to 2x + 3y = 6.', marks: 4, markScheme: `• Rearrange to y = −2x/3 + 2, so the gradient is −2/3 (1)\n• Perpendicular gradient is the negative reciprocal (1)\n• Perpendicular gradient = 3/2 (1)\n• Line through the origin: y = 3x/2 (1)` },
      { q: 'Find the equation of the perpendicular bisector of the segment joining (1, 2) and (5, 6).', marks: 4, markScheme: `• Midpoint is (3, 4) (1)\n• Gradient of the segment is 1 (1)\n• Perpendicular gradient is −1 (1)\n• y − 4 = −(x − 3), giving y = −x + 7 (1)` },
      { q: 'Determine whether the points A(1, 2), B(3, 6) and C(6, 12) are collinear, justifying your answer.', marks: 3, markScheme: `• Gradient AB = (6 − 2)/(3 − 1) = 2 (1)\n• Gradient BC = (12 − 6)/(6 − 3) = 2 (1)\n• The gradients are equal and the segments share the point B, so the three points are collinear (1)` },
      { q: 'Explain why the rule "perpendicular gradients multiply to −1" cannot be applied to the lines y = 5 and x = 3, even though they are perpendicular.', marks: 2, markScheme: `• The line x = 3 is vertical, so its gradient is undefined (1)\n• An undefined gradient cannot be multiplied, so the rule does not apply, although the lines are still perpendicular (1)` },
      { q: 'Find the coordinates of the point of intersection of y = 2x + 1 and y = −x + 7.', marks: 3, markScheme: `• Set 2x + 1 = −x + 7 (1)\n• 3x = 6, so x = 2 (1)\n• y = 5, so the point is (2, 5) (1)` },
      { q: 'Write down the equation of the circle with centre (4, −1) and radius 6.', marks: 2, markScheme: `• Use (x − a)² + (y − b)² = r² (1)\n• (x − 4)² + (y + 1)² = 36 (1)` },
      { q: 'State the centre and radius of the circle (x − 2)² + (y + 3)² = 16.', marks: 2, markScheme: `• Centre (2, −3) (1)\n• Radius 4, taking the square root of 16 (1)` },
      { q: 'Find the centre and radius of the circle x² + y² − 6x + 4y − 12 = 0.', marks: 4, markScheme: `• Complete the square in x: (x − 3)² − 9 (1)\n• Complete the square in y: (y + 2)² − 4 (1)\n• Rearrange to (x − 3)² + (y + 2)² = 25 (1)\n• Centre (3, −2), radius 5 (1)` },
      { q: 'Find the centre and radius of the circle x² + y² + 2x − 6y + 1 = 0.', marks: 4, markScheme: `• (x + 1)² − 1 (1)\n• (y − 3)² − 9 (1)\n• (x + 1)² + (y − 3)² = 9 (1)\n• Centre (−1, 3), radius 3 (1)` },
      { q: 'A circle has a diameter with endpoints (1, 2) and (7, 10). Find its equation.', marks: 4, markScheme: `• Centre is the midpoint, (4, 6) (1)\n• Length of diameter = √(6² + 8²) = 10 (1)\n• Radius = 5 (1)\n• Equation (x − 4)² + (y − 6)² = 25 (1)` },
      { q: 'Determine whether the point (5, 5) lies inside, on, or outside the circle x² + y² = 25, justifying your answer.', marks: 3, markScheme: `• Substitute the coordinates: 5² + 5² = 50 (1)\n• Compare with r² = 25 (1)\n• Since 50 > 25 the point lies outside the circle (1)` },
      { q: 'Find the equation of the tangent to the circle x² + y² = 25 at the point (3, 4).', marks: 4, markScheme: `• Gradient of the radius to (3, 4) is 4/3 (1)\n• The tangent is perpendicular to the radius, so its gradient is −3/4 (1)\n• y − 4 = −(3/4)(x − 3) (1)\n• 3x + 4y = 25 (1)` },
      { q: 'State the three circle properties given in the specification and say what each is useful for.', marks: 3, markScheme: `• The angle in a semicircle is a right angle — used when a diameter is involved (1)\n• The perpendicular from the centre to a chord bisects the chord — used for chord lengths (1)\n• A tangent is perpendicular to the radius at the point of contact — used to find tangent equations (1)` },
      { q: 'Determine the number of points of intersection of the line y = x + 1 and the circle x² + y² = 25.', marks: 4, markScheme: `• Substitute: x² + (x + 1)² = 25 (1)\n• Simplify to 2x² + 2x − 24 = 0, i.e. x² + x − 12 = 0 (1)\n• Discriminant = 1 + 48 = 49 > 0 (1)\n• Two distinct real roots, so the line cuts the circle at two points (1)` },
      { q: 'Find the values of c for which the line y = x + c is a tangent to the circle x² + y² = 8.', marks: 4, markScheme: `• The perpendicular distance from the centre (0, 0) to the line x − y + c = 0 must equal the radius (1)\n• Distance = |c|/√2 and radius = 2√2 (1)\n• |c|/√2 = 2√2, so |c| = 4 (1)\n• c = 4 or c = −4 (1)` },
      { q: 'Find the values of m for which the line y = mx is a tangent to the circle (x − 5)² + y² = 9.', marks: 4, markScheme: `• Distance from the centre (5, 0) to the line mx − y = 0 must equal 3 (1)\n• Distance = |5m|/√(m² + 1) (1)\n• Square both sides: 25m² = 9(m² + 1) (1)\n• 16m² = 9, so m = ±3/4 (1)` },
      { q: 'Find the length of the chord cut from the line y = x by the circle x² + y² = 8.', marks: 4, markScheme: `• Substitute y = x: 2x² = 8, so x² = 4 (1)\n• x = ±2, giving the points (2, 2) and (−2, −2) (1)\n• Length = √(4² + 4²) (1)\n• Length = √32 = 4√2 (1)` },
      { q: 'Find the centre of the circle passing through (0, 0), (4, 0) and (0, 6).', marks: 4, markScheme: `• The perpendicular bisector of the segment from (0,0) to (4,0) is x = 2 (1)\n• The perpendicular bisector of the segment from (0,0) to (0,6) is y = 3 (1)\n• The centre lies on both bisectors (1)\n• Centre is (2, 3) (1)` },
      { q: 'Two circles have centres 10 units apart and radii 4 and 6. Describe how they are related, justifying your answer.', marks: 3, markScheme: `• The sum of the radii is 4 + 6 = 10 (1)\n• This equals the distance between the centres (1)\n• The circles therefore touch externally at exactly one point (1)` },
      { q: 'Find the perpendicular distance from the point (1, 1) to the line 3x + 4y − 10 = 0.', marks: 3, markScheme: `• Use d = |ax₀ + by₀ + c|/√(a² + b²) (1)\n• Numerator = |3 + 4 − 10| = 3 (1)\n• d = 3/5 (1)` },
      { q: 'Explain why the perpendicular distance formula requires the line to be written in the form ax + by + c = 0.', marks: 2, markScheme: `• The formula reads the coefficients a, b and c directly from that form (1)\n• Applying it to y = mx + c without rearranging uses the wrong coefficients and gives an incorrect distance (1)` },
      { q: 'A curve has parametric equations x = 2t, y = t². Find its Cartesian equation.', marks: 3, markScheme: `• From the first equation, t = x/2 (1)\n• Substitute into the second: y = (x/2)² (1)\n• y = x²/4 (1)` },
      { q: 'A curve has parametric equations x = t + 1, y = t² − 1. Find its Cartesian equation and describe the curve.', marks: 3, markScheme: `• t = x − 1 (1)\n• y = (x − 1)² − 1 (1)\n• The curve is a parabola with vertex (1, −1) (1)` },
      { q: 'A curve has parametric equations x = cos θ, y = sin θ. Find its Cartesian equation and describe the curve.', marks: 3, markScheme: `• Use the identity sin²θ + cos²θ = 1 (1)\n• x² + y² = 1 (1)\n• The curve is a circle of radius 1 centred at the origin (1)` },
      { q: 'A curve has parametric equations x = 2 + 3cos θ, y = −1 + 3sin θ. Find its Cartesian equation and describe the curve.', marks: 4, markScheme: `• Rearrange: cos θ = (x − 2)/3 and sin θ = (y + 1)/3 (1)\n• Apply sin²θ + cos²θ = 1 (1)\n• (x − 2)² + (y + 1)² = 9 (1)\n• A circle with centre (2, −1) and radius 3 (1)` },
      { q: 'A curve has parametric equations x = 3cos t, y = 2sin t. Find its Cartesian equation and name the curve.', marks: 3, markScheme: `• cos t = x/3 and sin t = y/2 (1)\n• x²/9 + y²/4 = 1 (1)\n• The curve is an ellipse (1)` },
      { q: 'A curve has parametric equations x = t², y = 2t. Find its Cartesian equation.', marks: 3, markScheme: `• From the second equation, t = y/2 (1)\n• Substitute: x = (y/2)² (1)\n• y² = 4x (1)` },
      { q: 'For the curve x = t + 1/t, y = t − 1/t, show that x² − y² = 4.', marks: 4, markScheme: `• x² = t² + 2 + 1/t² (1)\n• y² = t² − 2 + 1/t² (1)\n• Subtract: x² − y² = 4 (1)\n• State that the t² and 1/t² terms cancel, leaving the constant (1)` },
      { q: 'Explain why, when eliminating a parameter, it is preferable to rearrange the simpler of the two equations.', marks: 2, markScheme: `• Rearranging a linear equation gives the parameter uniquely (1)\n• Rearranging a squared equation introduces a plus-or-minus square root, forcing unnecessary case-splitting (1)` },
      { q: 'For the parametric curve x = 2t, y = t², find dy/dx in terms of t.', marks: 3, markScheme: `• dx/dt = 2 (1)\n• dy/dt = 2t (1)\n• dy/dx = (dy/dt)/(dx/dt) = t (1)` },
      { q: 'For the parametric curve x = t², y = t³, find dy/dx in terms of t.', marks: 3, markScheme: `• dx/dt = 2t (1)\n• dy/dt = 3t² (1)\n• dy/dx = 3t²/(2t) = 3t/2 (1)` },
      { q: 'Find the equation of the locus of points equidistant from (0, 0) and (4, 0).', marks: 3, markScheme: `• The locus is the perpendicular bisector of the segment joining the two points (1)\n• The midpoint is (2, 0) and the segment is horizontal (1)\n• The locus is the vertical line x = 2 (1)` },
      { q: 'A circle has centre (3, −2) and passes through the point (7, 1). Find its equation.', marks: 4, markScheme: `• Radius is the distance from the centre to the point (1)\n• r = √(4² + 3²) (1)\n• r = 5 (1)\n• (x − 3)² + (y + 2)² = 25 (1)` },
      { q: 'Show that the line 3x + 4y = 25 is a tangent to the circle x² + y² = 25, and find the point of contact.', marks: 5, markScheme: `• Perpendicular distance from the origin to the line = |−25|/√(9 + 16) (1)\n• Distance = 5, which equals the radius, so the line is a tangent (1)\n• The point of contact lies on the perpendicular from the centre, along the direction (3, 4) (1)\n• Scale to length 5: the point is (3, 4) (1)\n• Verify: 3(3) + 4(4) = 25 and 3² + 4² = 25 (1)` },
      { q: 'A(1, 4) and B(7, 2) are the ends of a diameter of a circle. Find the equation of the circle and verify that (1, 2) lies on it.', marks: 5, markScheme: `• Centre is the midpoint (4, 3) (1)\n• Radius = half of |AB| = half of √(6² + 2²) = half of √40 (1)\n• r² = 10 (1)\n• Equation (x − 4)² + (y − 3)² = 10 (1)\n• Check (1, 2): (−3)² + (−1)² = 10, so the point lies on the circle (1)` },
      { q: 'Explain why the circle x² + y² + 2x + 4y + 10 = 0 does not exist as a real circle.', marks: 3, markScheme: `• Complete the square: (x + 1)² − 1 + (y + 2)² − 4 + 10 = 0 (1)\n• Rearrange to (x + 1)² + (y + 2)² = −5 (1)\n• A sum of two squares cannot be negative, so there are no real points on the curve (1)` },
      { q: 'For the parametric curve x = t², y = t³, explain what happens at the origin.', marks: 3, markScheme: `• Both x and y are zero at t = 0, so the curve passes through the origin (1)\n• dy/dx = 3t/2, which tends to 0 as t tends to 0 (1)\n• Since x = t² is never negative, the curve reverses direction in x at that point, producing a cusp (1)` },
    ]
  },

  '1.6': {
    name: 'Sequences & Series',
    questions: [
      { q: 'Explain the difference between a sequence and a series.', marks: 2, markScheme: `• A sequence is an ordered list of terms (1)\n• A series is the sum of the terms of a sequence (1)` },
      { q: 'Write down formulae for the nth term and the sum of the first n terms of an arithmetic sequence with first term a and common difference d.', marks: 2, markScheme: `• nth term is a + (n − 1)d (1)\n• Sum is (n/2)(2a + (n − 1)d), or equivalently (n/2)(a + l) (1)` },
      { q: 'Find the sum of the first 20 terms of an arithmetic series with first term 3 and common difference 5.', marks: 3, markScheme: `• Use Sₙ = (n/2)(2a + (n − 1)d) (1)\n• Substitute a = 3, d = 5, n = 20 (1)\n• S = 10(6 + 95) = 1010 (1)` },
      { q: 'How many terms are there in the arithmetic sequence 5, 9, 13, …, 101?', marks: 3, markScheme: `• Set a + (n − 1)d = 101 with a = 5 and d = 4 (1)\n• 4(n − 1) = 96 (1)\n• n = 25 (1)` },
      { q: 'An arithmetic sequence has 5th term 17 and 10th term 32. Find the first term and the common difference.', marks: 4, markScheme: `• The gap between the 5th and 10th terms is 5d (1)\n• 5d = 32 − 17 = 15, so d = 3 (1)\n• a + 4d = 17 (1)\n• a = 17 − 12 = 5 (1)` },
      { q: 'Find the sum of the arithmetic series 2 + 5 + 8 + … + 59.', marks: 4, markScheme: `• Identify a = 2, d = 3, last term 59 (1)\n• Find n: 2 + 3(n − 1) = 59, so n = 20 (1)\n• Use S = (n/2)(a + l) = 10(2 + 59) (1)\n• S = 610 (1)` },
      { q: 'An arithmetic series has first term 20 and common difference −3. Find the value of n for which the sum of the first n terms is greatest, justifying your answer.', marks: 4, markScheme: `• The sum increases while the terms remain positive (1)\n• Set 20 − 3(n − 1) > 0, giving 23 > 3n (1)\n• n < 7.67, so the last positive term is the 7th (u₇ = 2) (1)\n• The sum is greatest when n = 7 (1)` },
      { q: 'Write down formulae for the nth term and the sum of the first n terms of a geometric sequence with first term a and common ratio r.', marks: 2, markScheme: `• nth term is arⁿ⁻¹ (1)\n• Sum is a(1 − rⁿ)/(1 − r), valid for r ≠ 1 (1)` },
      { q: 'Find the sum of the first 5 terms of a geometric series with first term 2 and common ratio 3.', marks: 3, markScheme: `• Use Sₙ = a(1 − rⁿ)/(1 − r) (1)\n• S₅ = 2(1 − 243)/(1 − 3) (1)\n• S₅ = 242 (1)` },
      { q: 'State the condition for a geometric series to converge, and write down the formula for its sum to infinity.', marks: 2, markScheme: `• The series converges if and only if |r| < 1 (1)\n• Sum to infinity is a/(1 − r) (1)` },
      { q: 'Find the sum to infinity of 8 + 4 + 2 + 1 + …', marks: 3, markScheme: `• Identify a = 8 and r = 1/2 (1)\n• Confirm |r| < 1, so the series converges (1)\n• S∞ = 8/(1 − 1/2) = 16 (1)` },
      { q: 'A geometric series has sum to infinity equal to three times its first term. Find the common ratio.', marks: 3, markScheme: `• a/(1 − r) = 3a (1)\n• Divide by a: 1/(1 − r) = 3, so 1 − r = 1/3 (1)\n• r = 2/3 (1)` },
      { q: 'Explain why it is essential to check that |r| < 1 before using the sum to infinity formula.', marks: 2, markScheme: `• If |r| ≥ 1 the terms do not tend to zero and the series diverges, so no finite sum exists (1)\n• Applying the formula regardless produces a numerical answer that has no meaning (1)` },
      { q: 'The 6th term of a geometric sequence with first term 1 is −32. Find the common ratio.', marks: 3, markScheme: `• Use arⁿ⁻¹ with a = 1 and n = 6 (1)\n• r⁵ = −32 (1)\n• r = −2 (1)` },
      { q: 'Write the sum 3 + 6 + 9 + … + 30 in sigma notation.', marks: 2, markScheme: `• Recognise the general term as 3k (1)\n• Sum from k = 1 to 10 of 3k (1)` },
      { q: 'Evaluate the sum from k = 0 to 4 of 2ᵏ.', marks: 2, markScheme: `• Terms are 1, 2, 4, 8, 16 (1)\n• Total = 31 (1)` },
      { q: 'Prove that the sum from k = 1 to n of (2k − 1) is n², by relating it to a known arithmetic sum.', marks: 4, markScheme: `• The terms form an arithmetic sequence with a = 1 and d = 2 (1)\n• Last term is 2n − 1 (1)\n• Sum = (n/2)(1 + 2n − 1) (1)\n• = (n/2)(2n) = n² (1)` },
      { q: 'A recurrence relation is given by u₍ₙ₊₁₎ = uₙ + 3 with u₁ = 2. Write down the first four terms and describe the sequence.', marks: 3, markScheme: `• Terms are 2, 5, 8, 11 (1)\n• Each term exceeds the previous by 3 (1)\n• The sequence is arithmetic with common difference 3 (1)` },
      { q: 'The recurrence relation u₍ₙ₊₁₎ = √(2 + uₙ) converges to a limit L. Find L, rejecting any invalid solution with a reason.', marks: 4, markScheme: `• At the limit, L = √(2 + L) (1)\n• Square: L² = 2 + L, so L² − L − 2 = 0 (1)\n• Factorise (L − 2)(L + 1) = 0, giving L = 2 or L = −1 (1)\n• Reject L = −1 since a square root is non-negative; L = 2 (1)` },
      { q: 'Explain the method used to find the limit of a convergent recurrence relation.', marks: 2, markScheme: `• At the limit, successive terms are equal, so uₙ and u₍ₙ₊₁₎ may both be replaced by L (1)\n• This produces an equation in L which is then solved, rejecting any root inconsistent with the sequence (1)` },
      { q: 'Write down the binomial expansion of (1 + x)ⁿ for a positive integer n, and state how many terms it has.', marks: 3, markScheme: `• 1 + nx + [n(n − 1)/2!]x² + [n(n − 1)(n − 2)/3!]x³ + … (1)\n• The expansion terminates because a factor of zero eventually appears (1)\n• It has n + 1 terms (1)` },
      { q: 'Find the coefficient of x³ in the expansion of (1 + 2x)⁵.', marks: 3, markScheme: `• The required term is ⁵C₃(2x)³ (1)\n• ⁵C₃ = 10 and (2x)³ = 8x³ (1)\n• Coefficient = 80 (1)` },
      { q: 'Find the coefficient of x² in the expansion of (2 + x)⁶.', marks: 3, markScheme: `• Required term is ⁶C₂ × 2⁴ × x² (1)\n• ⁶C₂ = 15 and 2⁴ = 16 (1)\n• Coefficient = 240 (1)` },
      { q: 'Find the coefficient of x² in the expansion of (2 − x)⁴.', marks: 3, markScheme: `• Required term is ⁴C₂ × 2² × (−x)² (1)\n• ⁴C₂ = 6 and 2² = 4, with (−1)² = 1 (1)\n• Coefficient = 24 (1)` },
      { q: 'Explain the common error of writing (2x)³ as 2x³, and state the correct value.', marks: 2, markScheme: `• The whole bracket is cubed, so both the coefficient and the variable are raised to the power (1)\n• (2x)³ = 8x³ (1)` },
      { q: 'Find the coefficient of x³ in the expansion of (1 + x)(1 + 2x)⁴.', marks: 4, markScheme: `• Expand (1 + 2x)⁴ = 1 + 8x + 24x² + 32x³ + 16x⁴ (1)\n• The x³ term arises from 1 × 32x³ (1)\n• and from x × 24x² (1)\n• Total coefficient = 32 + 24 = 56 (1)` },
      { q: 'State the binomial series for (1 + x)ⁿ when n is not a positive integer, and give the condition for validity.', marks: 3, markScheme: `• The same series applies: 1 + nx + [n(n − 1)/2!]x² + … (1)\n• The expansion no longer terminates, so it is an infinite series (1)\n• It is valid only for |x| < 1 (1)` },
      { q: 'Expand (1 + x)^(1/2) in ascending powers of x up to and including the term in x².', marks: 3, markScheme: `• First-order term is (1/2)x (1)\n• Second-order term is [(1/2)(−1/2)/2]x² (1)\n• Expansion is 1 + x/2 − x²/8 (1)` },
      { q: 'Expand (1 + 3x)⁻² in ascending powers of x up to and including the term in x².', marks: 4, markScheme: `• Apply the series with n = −2 and the term 3x (1)\n• First-order term: (−2)(3x) = −6x (1)\n• Second-order term: [(−2)(−3)/2](3x)² = 3 × 9x² (1)\n• Expansion is 1 − 6x + 27x² (1)` },
      { q: 'Find the coefficient of x² in the expansion of (1 + x)^(−1/2).', marks: 3, markScheme: `• The coefficient is n(n − 1)/2! with n = −1/2 (1)\n• = (−1/2)(−3/2)/2 (1)\n• = 3/8 (1)` },
      { q: 'Expand (1 + 2x)^(1/2) up to the term in x², and state the range of values of x for which the expansion is valid.', marks: 5, markScheme: `• Apply the series with n = 1/2 and the term 2x (1)\n• First-order term: (1/2)(2x) = x (1)\n• Second-order term: [(1/2)(−1/2)/2](2x)² = −x²/2 (1)\n• Expansion is 1 + x − x²/2 (1)\n• Valid for |2x| < 1, that is |x| < 1/2 (1)` },
      { q: 'Explain why the validity condition for the expansion of (1 + ax)ⁿ with non-integer n is |x| < 1/|a| rather than |x| < 1.', marks: 2, markScheme: `• The standard condition applies to the whole term inside the bracket, so |ax| < 1 (1)\n• Dividing by |a| gives |x| < 1/|a| (1)` },
      { q: 'Use a binomial expansion to find an approximation for √1.02, giving your answer to 5 decimal places.', marks: 4, markScheme: `• Use the expansion of (1 + x)^(1/2) with x = 0.02 (1)\n• 1 + 0.02/2 = 1 + 0.01 (1)\n• Subtract (0.02)²/8 = 0.00005 (1)\n• Approximation is 1.00995 (1)` },
      { q: 'Explain how you would expand √(4 + x) using the binomial series, and why the series cannot be applied directly.', marks: 3, markScheme: `• The series requires a bracket of the form (1 + something) (1)\n• Factorise: √(4 + x) = 2(1 + x/4)^(1/2) (1)\n• The series is then applied to (1 + x/4)^(1/2), valid for |x| < 4 (1)` },
      { q: 'Write down the expansion of (1 − x)⁻¹ for |x| < 1 and identify the type of series obtained.', marks: 2, markScheme: `• 1 + x + x² + x³ + … (1)\n• This is a geometric series with first term 1 and common ratio x (1)` },
      { q: 'The sum of the first n terms of a series is n². Find the nth term.', marks: 3, markScheme: `• The nth term is Sₙ − S₍ₙ₋₁₎ (1)\n• = n² − (n − 1)² (1)\n• = 2n − 1 (1)` },
      { q: 'A geometric sequence has second term 6 and fifth term 48. Find the first term and the common ratio.', marks: 4, markScheme: `• ar = 6 and ar⁴ = 48 (1)\n• Divide: r³ = 8 (1)\n• r = 2 (1)\n• a = 6/2 = 3 (1)` },
      { q: 'Explain why the sequence 1, 3, 5, 7, … is not geometric.', marks: 2, markScheme: `• Compute successive ratios: 3/1 = 3 but 5/3 ≈ 1.67 (1)\n• The ratio is not constant, so the sequence is arithmetic rather than geometric (1)` },
      { q: 'A savings scheme pays 4% interest per year. £1000 is invested. Write down an expression for the value after n years and find the value after 10 years to the nearest pound.', marks: 4, markScheme: `• The values form a geometric sequence with r = 1.04 (1)\n• Value after n years = 1000 × 1.04ⁿ (1)\n• After 10 years: 1000 × 1.04¹⁰ (1)\n• ≈ £1480 (1)` },
      { q: 'The first three terms of an arithmetic sequence are 2k, 5k − 4 and 7k + 2. Find the value of k.', marks: 4, markScheme: `• In an arithmetic sequence successive differences are equal (1)\n• (5k − 4) − 2k = (7k + 2) − (5k − 4) (1)\n• 3k − 4 = 2k + 6 (1)\n• k = 10 (1)` },
    ]
  },

  '1.7': {
    name: 'Trigonometry',
    questions: [
      { q: 'Write down the exact values of sin 30°, cos 30° and tan 60°.', marks: 3, markScheme: `• sin 30° = 1/2 (1)\n• cos 30° = √3/2 (1)\n• tan 60° = √3 (1)` },
      { q: 'Define a radian and state the relationship between radians and degrees.', marks: 2, markScheme: `• One radian is the angle subtended at the centre of a circle by an arc equal in length to the radius (1)\n• π radians = 180° (1)` },
      { q: 'Convert 135° to radians and 5π/6 radians to degrees.', marks: 2, markScheme: `• 135° = 135 × π/180 = 3π/4 radians (1)\n• 5π/6 radians = 150° (1)` },
      { q: 'A sector of a circle has radius 6 cm and subtends an angle of π/3 radians. Find the arc length and the area of the sector.', marks: 4, markScheme: `• Arc length s = rθ (1)\n• s = 6 × π/3 = 2π cm (1)\n• Area A = ½r²θ (1)\n• A = ½ × 36 × π/3 = 6π cm² (1)` },
      { q: 'Explain why the formulae s = rθ and A = ½r²θ require θ to be in radians.', marks: 2, markScheme: `• The formulae are derived from the proportion of the full circle, using 2π radians for a complete turn (1)\n• Substituting degrees uses the wrong measure of a full turn, giving an answer wrong by a factor of about 57 (1)` },
      { q: 'A sector has radius 5 cm and arc length 4 cm. Find the angle subtended, in radians.', marks: 2, markScheme: `• Use s = rθ, so θ = s/r (1)\n• θ = 4/5 = 0.8 radians (1)` },
      { q: 'State the sine rule, the cosine rule and the formula for the area of a triangle.', marks: 3, markScheme: `• Sine rule: a/sin A = b/sin B = c/sin C (1)\n• Cosine rule: a² = b² + c² − 2bc cos A (1)\n• Area = ½ab sin C (1)` },
      { q: 'Explain when you should use the cosine rule rather than the sine rule.', marks: 2, markScheme: `• Use the cosine rule when given three sides, or two sides and the angle between them (1)\n• Use the sine rule otherwise, when a side and its opposite angle are known (1)` },
      { q: 'Explain what is meant by the ambiguous case of the sine rule.', marks: 3, markScheme: `• It arises when two sides and a non-included angle are given (1)\n• The equation sin θ = k has two solutions in the range 0° to 180°, namely θ and 180° − θ (1)\n• Both may give a valid triangle, so each must be checked against the given information (1)` },
      { q: 'State the periods of y = sin x, y = cos x and y = tan x.', marks: 3, markScheme: `• sin x has period 2π (1)\n• cos x has period 2π (1)\n• tan x has period π (1)` },
      { q: 'Solve sin x = √3/2 for 0 ≤ x < 2π, giving exact answers.', marks: 3, markScheme: `• Principal value x = π/3 (1)\n• Second solution from symmetry: x = π − π/3 = 2π/3 (1)\n• State both and confirm there are no others in the interval (1)` },
      { q: 'Solve cos x = −1/2 for 0 ≤ x < 2π, giving exact answers.', marks: 3, markScheme: `• The related acute angle is π/3 (1)\n• Cosine is negative in the second and third quadrants (1)\n• x = 2π/3 or 4π/3 (1)` },
      { q: 'Solve tan x = 1 for 0 ≤ x < 2π.', marks: 2, markScheme: `• Principal value x = π/4 (1)\n• Adding the period π gives x = 5π/4, so the solutions are π/4 and 5π/4 (1)` },
      { q: 'Solve 2 cos x = 1 for 0° ≤ x < 360°.', marks: 3, markScheme: `• cos x = 1/2 (1)\n• Principal value x = 60° (1)\n• Second solution x = 300° (1)` },
      { q: 'Solve sin 2x = 0.5 for 0° ≤ x < 360°, explaining your method.', marks: 5, markScheme: `• Widen the range: if 0° ≤ x < 360° then 0° ≤ 2x < 720° (1)\n• Solve for 2x in that range (1)\n• 2x = 30°, 150°, 390°, 510° (1)\n• Halve each value (1)\n• x = 15°, 75°, 195°, 255° (1)` },
      { q: 'Explain why, when solving sin 2x = k, you must widen the range before solving rather than halving afterwards.', marks: 2, markScheme: `• The substitution u = 2x doubles the interval, so there are twice as many solutions for u (1)\n• Solving in the original range and then halving finds only half of them (1)` },
      { q: 'Determine the number of solutions of sin 3x = 0.5 for 0 ≤ x < 2π, justifying your answer.', marks: 3, markScheme: `• If 0 ≤ x < 2π then 0 ≤ 3x < 6π (1)\n• Over each interval of 2π there are two solutions of sin u = 0.5 (1)\n• Three such intervals give 6 solutions (1)` },
      { q: 'Write down the definitions of sec θ, cosec θ and cot θ.', marks: 3, markScheme: `• sec θ = 1/cos θ (1)\n• cosec θ = 1/sin θ (1)\n• cot θ = 1/tan θ = cos θ/sin θ (1)` },
      { q: 'Starting from sin²θ + cos²θ = 1, derive the identities 1 + tan²θ = sec²θ and 1 + cot²θ = cosec²θ.', marks: 4, markScheme: `• Divide sin²θ + cos²θ = 1 through by cos²θ (1)\n• tan²θ + 1 = sec²θ (1)\n• Divide the original identity through by sin²θ (1)\n• 1 + cot²θ = cosec²θ (1)` },
      { q: 'Solve sec x = 2 for 0 ≤ x < 2π.', marks: 3, markScheme: `• sec x = 2 means cos x = 1/2 (1)\n• Principal value x = π/3 (1)\n• Second solution x = 5π/3 (1)` },
      { q: 'Write down the compound angle formulae for sin(A + B), cos(A + B) and tan(A + B).', marks: 3, markScheme: `• sin(A + B) = sin A cos B + cos A sin B (1)\n• cos(A + B) = cos A cos B − sin A sin B (1)\n• tan(A + B) = (tan A + tan B)/(1 − tan A tan B) (1)` },
      { q: 'Explain the common error made with the sign in the cosine compound angle formula.', marks: 2, markScheme: `• Candidates often write cos(A + B) = cos A cos B + sin A sin B (1)\n• The correct formula has a minus sign for cos(A + B), and a plus sign for cos(A − B) (1)` },
      { q: 'Use the compound angle formula to find the exact value of sin 75°.', marks: 4, markScheme: `• Write 75° = 45° + 30° (1)\n• sin 75° = sin 45° cos 30° + cos 45° sin 30° (1)\n• = (√2/2)(√3/2) + (√2/2)(1/2) (1)\n• = (√6 + √2)/4 (1)` },
      { q: 'Write down the three forms of the double angle identity for cos 2θ, and explain how to choose between them.', marks: 4, markScheme: `• cos 2θ = cos²θ − sin²θ (1)\n• cos 2θ = 2cos²θ − 1 (1)\n• cos 2θ = 1 − 2sin²θ (1)\n• Choose the form that matches the other trigonometric function in the equation, so that the whole equation is in one function (1)` },
      { q: 'Derive the identity sin 2θ = 2 sin θ cos θ from the compound angle formula.', marks: 2, markScheme: `• Write sin 2θ = sin(θ + θ) = sin θ cos θ + cos θ sin θ (1)\n• Combine the two identical terms to give 2 sin θ cos θ (1)` },
      { q: 'Show that (1 − cos 2θ)/sin 2θ simplifies to tan θ.', marks: 4, markScheme: `• Use cos 2θ = 1 − 2sin²θ, so the numerator becomes 2sin²θ (1)\n• Use sin 2θ = 2 sin θ cos θ for the denominator (1)\n• The expression becomes 2sin²θ/(2 sin θ cos θ) (1)\n• Cancel to give sin θ/cos θ = tan θ (1)` },
      { q: 'Solve 2 sin²x + sin x − 1 = 0 for 0 ≤ x < 2π.', marks: 5, markScheme: `• Factorise as (2 sin x − 1)(sin x + 1) = 0 (1)\n• sin x = 1/2 or sin x = −1 (1)\n• sin x = 1/2 gives x = π/6 (1)\n• and x = 5π/6 (1)\n• sin x = −1 gives x = 3π/2 (1)` },
      { q: 'Solve 3 cos 2x + sin x = 2 for 0 ≤ x < 2π, giving non-exact answers to 3 decimal places.', marks: 6, markScheme: `• Use cos 2x = 1 − 2sin²x (1)\n• 3(1 − 2sin²x) + sin x = 2 (1)\n• Rearrange to 6sin²x − sin x − 1 = 0 (1)\n• Factorise (3 sin x + 1)(2 sin x − 1) = 0 (1)\n• sin x = 1/2 gives x = π/6 and 5π/6 (1)\n• sin x = −1/3 gives x = 3.481 and 5.943 (1)` },
      { q: 'Express 3 sin x + 4 cos x in the form R sin(x + α), where R > 0 and 0 < α < π/2.', marks: 4, markScheme: `• R = √(3² + 4²) (1)\n• R = 5 (1)\n• tan α = 4/3 (1)\n• α = 0.927 radians to 3 significant figures (1)` },
      { q: 'Using your answer to the previous question, state the maximum and minimum values of 3 sin x + 4 cos x and the value of x at which the maximum occurs.', marks: 3, markScheme: `• Maximum is 5, minimum is −5 (1)\n• The maximum occurs when sin(x + α) = 1, so x + α = π/2 (1)\n• x = π/2 − 0.927 = 0.644 radians (1)` },
      { q: 'Express 5 sin x − 12 cos x in the form R sin(x − α), stating R and tan α.', marks: 3, markScheme: `• R = √(25 + 144) (1)\n• R = 13 (1)\n• tan α = 12/5 (1)` },
      { q: 'Find the maximum value of 5 + 2 cos x and the minimum value of 3 − 4 sin x.', marks: 2, markScheme: `• cos x has maximum 1, so 5 + 2cos x has maximum 7 (1)\n• sin x has maximum 1, so 3 − 4 sin x has minimum −1 (1)` },
      { q: 'Write down the small angle approximations for sin θ, tan θ and cos θ, stating the condition under which they hold.', marks: 4, markScheme: `• sin θ ≈ θ (1)\n• tan θ ≈ θ (1)\n• cos θ ≈ 1 − θ²/2 (1)\n• These hold for small θ measured in radians (1)` },
      { q: 'State the value of the limit of (sin θ)/θ as θ tends to 0, and explain its significance for calculus.', marks: 3, markScheme: `• The limit is 1 (1)\n• It follows from the small angle approximation sin θ ≈ θ in radians (1)\n• It is the reason the derivative of sin x is cos x only when x is measured in radians (1)` },
      { q: 'Solve sin x = cos x for 0 ≤ x < 2π.', marks: 3, markScheme: `• Divide by cos x, noting cos x ≠ 0 at any solution (1)\n• tan x = 1 (1)\n• x = π/4 or 5π/4 (1)` },
      { q: 'Explain why dividing a trigonometric equation by cos x can lose solutions, and state how to avoid this.', marks: 3, markScheme: `• Division by cos x is invalid where cos x = 0 (1)\n• Any solutions with cos x = 0 are therefore lost (1)\n• Instead, factorise rather than divide, and check the cases where the factor is zero separately (1)` },
      { q: 'Determine the number of solutions of tan 2x = 1 for 0 ≤ x < 2π.', marks: 3, markScheme: `• If 0 ≤ x < 2π then 0 ≤ 2x < 4π (1)\n• tan has period π, so solutions occur every π (1)\n• Over an interval of 4π there are 4 solutions (1)` },
      { q: 'Prove the identity (sin θ)/(1 + cos θ) + (1 + cos θ)/(sin θ) ≡ 2 cosec θ.', marks: 5, markScheme: `• Combine over the common denominator sin θ(1 + cos θ) (1)\n• Numerator = sin²θ + (1 + cos θ)² (1)\n• Expand: sin²θ + 1 + 2cos θ + cos²θ (1)\n• Use sin²θ + cos²θ = 1 to get 2 + 2cos θ = 2(1 + cos θ) (1)\n• Cancel (1 + cos θ) to leave 2/sin θ = 2 cosec θ (1)` },
      { q: 'Given that sin θ = 3/5 and θ is acute, find the exact values of cos θ and tan θ.', marks: 3, markScheme: `• Use sin²θ + cos²θ = 1, so cos²θ = 1 − 9/25 = 16/25 (1)\n• θ acute means cos θ is positive, so cos θ = 4/5 (1)\n• tan θ = (3/5)/(4/5) = 3/4 (1)` },
      { q: 'Using sin 3θ = 3 sin θ − 4 sin³θ, find the exact value of sin 3θ when sin θ = 1/2.', marks: 3, markScheme: `• Substitute sin θ = 1/2 (1)\n• 3(1/2) − 4(1/8) = 1.5 − 0.5 (1)\n• sin 3θ = 1 (1)` },
    ]
  },

  '1.8': {
    name: 'Exponentials & Logarithms',
    questions: [
      { q: 'Sketch y = aˣ for a > 1, stating the coordinates of the point where it crosses the y-axis and the equation of its asymptote.', marks: 3, markScheme: `• Curve increasing, always positive (1)\n• Passes through (0, 1) (1)\n• Horizontal asymptote y = 0 (1)` },
      { q: 'Explain the relationship between y = aˣ and y = log_a x, and describe how their graphs are related.', marks: 3, markScheme: `• They are inverse functions of one another (1)\n• x = a^y is equivalent to y = log_a x (1)\n• Each graph is the reflection of the other in the line y = x (1)` },
      { q: 'Write 2⁵ = 32 in logarithmic form, and write log₃ 81 = 4 in index form.', marks: 2, markScheme: `• log₂ 32 = 5 (1)\n• 3⁴ = 81 (1)` },
      { q: 'State the three laws of logarithms.', marks: 3, markScheme: `• log(xy) = log x + log y (1)\n• log(x/y) = log x − log y (1)\n• log(xᵏ) = k log x (1)` },
      { q: 'Write down the values of log_a a and log_a 1, and explain each briefly.', marks: 2, markScheme: `• log_a a = 1, since a¹ = a (1)\n• log_a 1 = 0, since a⁰ = 1 (1)` },
      { q: 'Explain why there is no law for log(x + y), and give a numerical example showing that log(x + y) ≠ log x + log y.', marks: 3, markScheme: `• The addition law applies to a product inside the logarithm, not a sum (1)\n• Example: log(2 + 8) = log 10 = 1 (base 10) (1)\n• But log 2 + log 8 = log 16 ≈ 1.204, which is different (1)` },
      { q: 'Solve 3ˣ = 20, giving your answer to 3 decimal places.', marks: 3, markScheme: `• Take logarithms of both sides: x log 3 = log 20 (1)\n• x = log 20 / log 3 (1)\n• x = 2.727 (1)` },
      { q: 'Solve 2^(x + 1) = 32 without using a calculator.', marks: 3, markScheme: `• Write 32 as 2⁵ (1)\n• Equate indices: x + 1 = 5 (1)\n• x = 4 (1)` },
      { q: 'Solve 5^(2x) = 5^(x + 3).', marks: 2, markScheme: `• Equate indices since the bases are equal: 2x = x + 3 (1)\n• x = 3 (1)` },
      { q: 'Solve log₂ x + log₂(x − 2) = 3, explaining why one root must be rejected.', marks: 5, markScheme: `• Combine using the addition law: log₂(x(x − 2)) = 3 (1)\n• x² − 2x = 2³ = 8 (1)\n• x² − 2x − 8 = 0, factorising to (x − 4)(x + 2) = 0 (1)\n• Roots x = 4 and x = −2 (1)\n• Reject x = −2 because log₂(x − 2) requires x > 2; hence x = 4 (1)` },
      { q: 'Solve 2 ln x = ln 9 for x > 0.', marks: 3, markScheme: `• Apply the power law: ln x² = ln 9 (1)\n• x² = 9 (1)\n• x = 3, rejecting x = −3 since ln x requires x > 0 (1)` },
      { q: 'Solve ln(x + 1) − ln(x − 1) = ln 3.', marks: 4, markScheme: `• Apply the subtraction law: ln((x + 1)/(x − 1)) = ln 3 (1)\n• (x + 1)/(x − 1) = 3 (1)\n• x + 1 = 3x − 3 (1)\n• x = 2, which satisfies x > 1 (1)` },
      { q: 'Solve log_x 16 = 2.', marks: 2, markScheme: `• Rewrite in index form: x² = 16 (1)\n• x = 4, rejecting x = −4 since a logarithm base must be positive (1)` },
      { q: 'Solve log₄ x = 3/2 without a calculator.', marks: 2, markScheme: `• x = 4^(3/2) (1)\n• x = 8 (1)` },
      { q: 'State the change of base formula for logarithms and use it to evaluate log₂ 8 using base 10 logarithms.', marks: 3, markScheme: `• log_a b = log b / log a (1)\n• log₂ 8 = log 8 / log 2 (1)\n• = 0.903/0.301 = 3 (1)` },
      { q: 'Solve 3^(2x) − 4(3ˣ) + 3 = 0.', marks: 4, markScheme: `• Substitute u = 3ˣ, so 3^(2x) = u² (1)\n• u² − 4u + 3 = 0, factorising to (u − 1)(u − 3) = 0 (1)\n• u = 1 gives 3ˣ = 1, so x = 0 (1)\n• u = 3 gives 3ˣ = 3, so x = 1 (1)` },
      { q: 'Solve eˣ − 5e^(−x) = 4, explaining why one value must be rejected.', marks: 5, markScheme: `• Multiply through by eˣ (1)\n• e^(2x) − 4eˣ − 5 = 0 (1)\n• Substitute u = eˣ: u² − 4u − 5 = 0, factorising to (u − 5)(u + 1) = 0 (1)\n• Reject u = −1 because eˣ is always positive (1)\n• eˣ = 5, so x = ln 5 (1)` },
      { q: 'Solve 2ˣ = 3^(x − 1), giving your answer in terms of natural logarithms.', marks: 4, markScheme: `• Take natural logarithms: x ln 2 = (x − 1) ln 3 (1)\n• Expand: x ln 2 = x ln 3 − ln 3 (1)\n• Collect terms: ln 3 = x(ln 3 − ln 2) (1)\n• x = ln 3/(ln 3 − ln 2) (1)` },
      { q: 'Explain what is special about the number e, and state the derivative of e^(kx).', marks: 3, markScheme: `• e is the base for which the gradient of the curve y = eˣ equals eˣ itself at every point (1)\n• e ≈ 2.718 (1)\n• The derivative of e^(kx) is k e^(kx) (1)` },
      { q: 'Explain why the exponential function is suitable for modelling situations where a quantity changes at a rate proportional to its size.', marks: 3, markScheme: `• The derivative of e^(kt) is k e^(kt), which is k times the function itself (1)\n• So the rate of change is proportional to the current value (1)\n• This is exactly the condition described, so the exponential is the solution of that model (1)` },
      { q: 'Sketch y = ln x, stating the domain, the asymptote and one point on the curve.', marks: 3, markScheme: `• Domain x > 0 (1)\n• Vertical asymptote x = 0 (1)\n• Passes through (1, 0), increasing but flattening (1)` },
      { q: 'Write down the values of ln e, ln 1 and e^(ln x), stating any restriction on x.', marks: 3, markScheme: `• ln e = 1 (1)\n• ln 1 = 0 (1)\n• e^(ln x) = x, valid for x > 0 (1)` },
      { q: 'Find the inverse of f(x) = 3e^(2x).', marks: 4, markScheme: `• Write y = 3e^(2x), so e^(2x) = y/3 (1)\n• Take natural logarithms: 2x = ln(y/3) (1)\n• x = ½ln(y/3) (1)\n• f⁻¹(x) = ½ln(x/3) (1)` },
      { q: 'State the equation of the horizontal asymptote of y = 2 + e^(−x), and describe the behaviour of the curve as x increases.', marks: 3, markScheme: `• As x increases, e^(−x) tends to 0 (1)\n• So y tends to 2 from above (1)\n• Horizontal asymptote y = 2 (1)` },
      { q: 'Data are believed to satisfy y = axⁿ. Explain how a graph can be used to estimate a and n, stating what should be plotted.', marks: 5, markScheme: `• Take logarithms of both sides (1)\n• log y = log a + n log x (1)\n• This is linear in log x (1)\n• Plot log y (vertical) against log x (horizontal) (1)\n• The gradient gives n and the vertical intercept gives log a, so a = 10^(intercept) (1)` },
      { q: 'Data are believed to satisfy y = abˣ. Explain how a graph can be used to estimate a and b, stating what should be plotted.', marks: 4, markScheme: `• Take logarithms: log y = log a + x log b (1)\n• Plot log y against x (not log x) (1)\n• The gradient is log b, so b = 10^(gradient) (1)\n• The vertical intercept is log a, so a = 10^(intercept) (1)` },
      { q: 'Explain how you can tell, from which quantities give a straight-line graph, whether a relationship is a power law or an exponential law.', marks: 3, markScheme: `• If log y against log x is linear, the relationship is a power law y = axⁿ (1)\n• If log y against x is linear, the relationship is exponential, y = abˣ (1)\n• The distinguishing feature is whether the horizontal axis carries a logarithm (1)` },
      { q: 'A log–log plot of experimental data gives a straight line of gradient 1.5 and vertical intercept 0.6. Find the relationship between y and x.', marks: 4, markScheme: `• The form is y = axⁿ (1)\n• n = gradient = 1.5 (1)\n• log a = 0.6, so a = 10^0.6 (1)\n• a ≈ 3.98, giving y ≈ 3.98x^1.5 (1)` },
      { q: 'A population is modelled by P = P₀e^(kt). Given P₀ = 500 and P = 800 after 4 years, find k to 3 significant figures.', marks: 4, markScheme: `• 800 = 500e^(4k) (1)\n• e^(4k) = 1.6 (1)\n• 4k = ln 1.6 (1)\n• k = 0.1175, so k = 0.118 to 3 s.f. (1)` },
      { q: 'A radioactive substance decays according to N = N₀e^(−kt) and has a half-life of 5 days. Find k in exact form.', marks: 4, markScheme: `• At t = 5, N = N₀/2, so e^(−5k) = 1/2 (1)\n• Take natural logarithms: −5k = ln(1/2) (1)\n• −5k = −ln 2 (1)\n• k = (ln 2)/5 (1)` },
      { q: 'For the model y = 5e^(−0.2t), state the initial value and the long-term value, justifying the second.', marks: 3, markScheme: `• At t = 0, e⁰ = 1, so y = 5 (1)\n• As t tends to infinity, e^(−0.2t) tends to 0 (1)\n• So y tends to 0 (1)` },
      { q: 'An amount P is invested at a continuous compound interest rate r. Write down the value after time t, and find the value of £2000 after 5 years at 3%.', marks: 4, markScheme: `• Value = Pe^(rt) (1)\n• Substitute P = 2000, r = 0.03, t = 5 (1)\n• 2000e^0.15 (1)\n• ≈ £2323.67 (1)` },
      { q: 'Explain two limitations of using P = P₀e^(kt) to model the growth of a real population.', marks: 4, markScheme: `• The model predicts growth without limit (1)\n• Real populations are constrained by finite food, space or other resources (1)\n• The growth constant k is assumed fixed, but may vary with conditions over time (1)\n• Populations are discrete, whereas the model treats them as continuous (1)` },
      { q: 'Suggest one refinement to an exponential growth model that addresses its main limitation, and describe its effect.', marks: 3, markScheme: `• Introduce a carrying capacity, giving a logistic model (1)\n• The growth rate then falls as the population approaches the ceiling (1)\n• The population levels off rather than growing without limit (1)` },
      { q: 'The curve y = ln(x − 2) crosses the x-axis at P. Find the coordinates of P and state the equation of the asymptote.', marks: 3, markScheme: `• Set ln(x − 2) = 0, so x − 2 = 1 (1)\n• P is (3, 0) (1)\n• Vertical asymptote where x − 2 = 0, that is x = 2 (1)` },
      { q: 'Solve e^(2x) = 7, giving your answer in exact form and to 3 significant figures.', marks: 3, markScheme: `• Take natural logarithms: 2x = ln 7 (1)\n• x = ½ln 7 (1)\n• x = 0.973 to 3 s.f. (1)` },
      { q: 'A quantity satisfies dy/dx proportional to y. State the type of graph obtained, and contrast it with the case where dy/dx is proportional to x.', marks: 3, markScheme: `• If dy/dx is proportional to y the graph is exponential (1)\n• If dy/dx is proportional to x the graph is quadratic (1)\n• In the first case the rate depends on the current value; in the second it depends only on position along the horizontal axis (1)` },
      { q: 'Solve the inequality 2ˣ > 100, giving your answer to 3 significant figures.', marks: 3, markScheme: `• Take logarithms: x log 2 > log 100 (1)\n• x > log 100 / log 2 (1)\n• x > 6.64 to 3 s.f. (1)` },
      { q: 'The value of a car is modelled by V = 18000 × 0.85ᵗ, where t is in years. Find, to the nearest year, how long until the car is worth half its original value.', marks: 4, markScheme: `• Set 0.85ᵗ = 0.5 (1)\n• Take logarithms: t log 0.85 = log 0.5 (1)\n• t = log 0.5 / log 0.85 (1)\n• t ≈ 4.27, so 4 years to the nearest year (1)` },
      { q: 'Explain why an exponential decay model that tends to zero may be unrealistic in some contexts, giving an example.', marks: 3, markScheme: `• The model predicts the quantity becomes arbitrarily small but never reaches a floor (1)\n• In practice a background or residual level may remain (1)\n• Example: a drug concentration may not fall below a detectable baseline, or a cooling body cannot fall below the ambient temperature (1)` },
    ]
  },

  '1.9': {
    name: 'Differentiation',
    questions: [
      { q: 'Write down the definition of the derivative as a limit, and explain what it represents geometrically.', marks: 3, markScheme: `• f′(x) = limit as h tends to 0 of (f(x + h) − f(x))/h (1)\n• The fraction is the gradient of a chord between two points on the curve (1)\n• As h tends to 0 the chord becomes the tangent, so the derivative is the gradient of the tangent (1)` },
      { q: 'Differentiate y = x² from first principles.', marks: 4, markScheme: `• Form ((x + h)² − x²)/h (1)\n• Expand the numerator to 2xh + h² (1)\n• Divide by h to obtain 2x + h (1)\n• Let h tend to 0 to give dy/dx = 2x (1)` },
      { q: 'Differentiate y = 3x² − 5x from first principles.', marks: 5, markScheme: `• Form (3(x + h)² − 5(x + h) − (3x² − 5x))/h (1)\n• Expand: (3x² + 6xh + 3h² − 5x − 5h − 3x² + 5x)/h (1)\n• Simplify the numerator to 6xh + 3h² − 5h (1)\n• Divide by h: 6x + 3h − 5 (1)\n• Let h tend to 0 to give 6x − 5 (1)` },
      { q: 'Explain why, in a first principles derivation, you must cancel the h before letting h tend to zero.', marks: 2, markScheme: `• Substituting h = 0 directly gives 0/0, which is undefined (1)\n• Cancelling the common factor of h first produces an expression that has a finite limit (1)` },
      { q: 'Differentiate y = 3x³ − 4x² + 5x − 7.', marks: 2, markScheme: `• Apply the power rule term by term (1)\n• dy/dx = 9x² − 8x + 5 (1)` },
      { q: 'Differentiate y = √x + 1/x, first writing each term as a power of x.', marks: 4, markScheme: `• Rewrite as x^(1/2) + x^(−1) (1)\n• Derivative of x^(1/2) is ½x^(−1/2) (1)\n• Derivative of x^(−1) is −x^(−2) (1)\n• dy/dx = 1/(2√x) − 1/x² (1)` },
      { q: 'Write down the derivatives of eˣ, ln x, sin x, cos x and tan x.', marks: 5, markScheme: `• d/dx(eˣ) = eˣ (1)\n• d/dx(ln x) = 1/x (1)\n• d/dx(sin x) = cos x (1)\n• d/dx(cos x) = −sin x (1)\n• d/dx(tan x) = sec²x (1)` },
      { q: 'Explain why the derivative of sin x is cos x only when x is measured in radians.', marks: 3, markScheme: `• The derivation relies on the limit of (sin h)/h as h tends to 0 (1)\n• That limit equals 1 only when h is in radians (1)\n• In degrees the limit is π/180, so the derivative would carry an extra constant factor (1)` },
      { q: 'State the chain rule and use it to differentiate y = sin 3x.', marks: 3, markScheme: `• Chain rule: the derivative of f(g(x)) is f′(g(x)) × g′(x) (1)\n• Outer derivative gives cos 3x (1)\n• Inner derivative is 3, so dy/dx = 3cos 3x (1)` },
      { q: 'Differentiate y = (2x + 1)⁵.', marks: 2, markScheme: `• Apply the chain rule: 5(2x + 1)⁴ times the inner derivative (1)\n• dy/dx = 10(2x + 1)⁴ (1)` },
      { q: 'Differentiate y = e^(x²).', marks: 2, markScheme: `• Outer derivative is e^(x²) (1)\n• Inner derivative is 2x, so dy/dx = 2xe^(x²) (1)` },
      { q: 'Differentiate y = ln(2x + 1).', marks: 2, markScheme: `• Outer derivative is 1/(2x + 1) (1)\n• Inner derivative is 2, so dy/dx = 2/(2x + 1) (1)` },
      { q: 'State the product rule and use it to differentiate y = x²eˣ.', marks: 4, markScheme: `• Product rule: derivative of uv is u′v + uv′ (1)\n• Take u = x² and v = eˣ, so u′ = 2x and v′ = eˣ (1)\n• dy/dx = 2xeˣ + x²eˣ (1)\n• Factorise: xeˣ(2 + x) (1)` },
      { q: 'Differentiate y = x ln x.', marks: 3, markScheme: `• Product rule with u = x and v = ln x (1)\n• u′v = ln x and uv′ = x × 1/x = 1 (1)\n• dy/dx = ln x + 1 (1)` },
      { q: 'Differentiate y = x³ ln x.', marks: 3, markScheme: `• Product rule with u = x³ and v = ln x (1)\n• u′v = 3x² ln x and uv′ = x³ × 1/x = x² (1)\n• dy/dx = 3x² ln x + x² (1)` },
      { q: 'State the quotient rule and use it to differentiate y = (x + 1)/(x − 1).', marks: 4, markScheme: `• Quotient rule: derivative of u/v is (u′v − uv′)/v² (1)\n• u = x + 1, v = x − 1, so u′ = 1 and v′ = 1 (1)\n• Numerator = (x − 1) − (x + 1) = −2 (1)\n• dy/dx = −2/(x − 1)² (1)` },
      { q: 'Explain the consequence of writing the quotient rule numerator as uv′ − u′v instead of u′v − uv′.', marks: 2, markScheme: `• The two expressions differ by a factor of −1 (1)\n• Every answer obtained would have the wrong sign (1)` },
      { q: 'Differentiate y = cos²x, giving your answer in its simplest form.', marks: 3, markScheme: `• Chain rule: 2cos x times the derivative of cos x (1)\n• = 2cos x × (−sin x) = −2 sin x cos x (1)\n• Simplify using the double angle identity: −sin 2x (1)` },
      { q: 'Differentiate y = sin x cos x, giving your answer in its simplest form.', marks: 3, markScheme: `• Product rule: cos x cos x + sin x(−sin x) (1)\n• = cos²x − sin²x (1)\n• = cos 2x (1)` },
      { q: 'Differentiate y = ln(sec x), simplifying your answer.', marks: 3, markScheme: `• Chain rule: (1/sec x) times the derivative of sec x (1)\n• The derivative of sec x is sec x tan x (1)\n• dy/dx = tan x (1)` },
      { q: 'Differentiate xˣ for x > 0, showing your method.', marks: 4, markScheme: `• Let y = xˣ and take natural logarithms: ln y = x ln x (1)\n• Differentiate implicitly: (1/y)(dy/dx) = ln x + 1 (1)\n• dy/dx = y(ln x + 1) (1)\n• dy/dx = xˣ(1 + ln x) (1)` },
      { q: 'For x² + y² = 25, find dy/dx by implicit differentiation.', marks: 3, markScheme: `• Differentiate each term with respect to x (1)\n• 2x + 2y(dy/dx) = 0 (1)\n• dy/dx = −x/y (1)` },
      { q: 'For x³ + y³ = 6xy, find dy/dx.', marks: 5, markScheme: `• Differentiate the left side: 3x² + 3y²(dy/dx) (1)\n• Differentiate the right side using the product rule: 6y + 6x(dy/dx) (1)\n• Collect the dy/dx terms: (3y² − 6x)(dy/dx) = 6y − 3x² (1)\n• Divide through by 3 (1)\n• dy/dx = (2y − x²)/(y² − 2x) (1)` },
      { q: 'Explain why a dy/dx factor appears whenever a term in y is differentiated with respect to x.', marks: 2, markScheme: `• y is a function of x, so the chain rule applies (1)\n• Differentiating f(y) with respect to x gives f′(y) times dy/dx (1)` },
      { q: 'For the parametric curve x = 2t, y = t², find dy/dx and d²y/dx².', marks: 5, markScheme: `• dx/dt = 2 and dy/dt = 2t (1)\n• dy/dx = 2t/2 = t (1)\n• For the second derivative, differentiate dy/dx with respect to t: d/dt(t) = 1 (1)\n• Divide by dx/dt (1)\n• d²y/dx² = 1/2 (1)` },
      { q: 'Explain why d²y/dx² for a parametric curve is not obtained by simply differentiating dy/dx with respect to t.', marks: 2, markScheme: `• Differentiating with respect to t gives the rate of change with respect to t, not with respect to x (1)\n• The result must be divided by dx/dt to convert it (1)` },
      { q: 'Find the equation of the tangent to y = x² at the point (2, 4).', marks: 3, markScheme: `• dy/dx = 2x, so the gradient at x = 2 is 4 (1)\n• y − 4 = 4(x − 2) (1)\n• y = 4x − 4 (1)` },
      { q: 'Find the equation of the normal to y = x³ at the point (1, 1).', marks: 4, markScheme: `• dy/dx = 3x², so the tangent gradient at x = 1 is 3 (1)\n• The normal gradient is −1/3 (1)\n• y − 1 = −(1/3)(x − 1) (1)\n• y = −x/3 + 4/3 (1)` },
      { q: 'Find and classify the stationary points of y = x³ − 3x.', marks: 5, markScheme: `• dy/dx = 3x² − 3 (1)\n• Set to zero: x = 1 and x = −1 (1)\n• Corresponding points (1, −2) and (−1, 2) (1)\n• d²y/dx² = 6x (1)\n• At x = 1 it is positive so a minimum; at x = −1 it is negative so a maximum (1)` },
      { q: 'Find the stationary point of y = xe^(−x) and determine its nature.', marks: 5, markScheme: `• Product rule: dy/dx = e^(−x) − xe^(−x) (1)\n• Factorise: e^(−x)(1 − x) (1)\n• e^(−x) is never zero, so x = 1 (1)\n• y = e^(−1), so the point is (1, 1/e) (1)\n• The gradient changes from positive to negative, so it is a maximum (1)` },
      { q: 'Explain why d²y/dx² = 0 at a stationary point does not prove that the point is a point of inflection, giving a counter-example.', marks: 3, markScheme: `• A point of inflection requires the second derivative to change sign (1)\n• For y = x⁴ at the origin, dy/dx = 0 and d²y/dx² = 12x² = 0 (1)\n• But 12x² is never negative, so there is no sign change and the origin is a minimum (1)` },
      { q: 'State the condition for a function to be increasing on an interval, and find the interval on which y = x² − 4x is increasing.', marks: 3, markScheme: `• A function is increasing where dy/dx > 0 (1)\n• dy/dx = 2x − 4 (1)\n• 2x − 4 > 0 gives x > 2 (1)` },
      { q: 'A sphere has volume V = (4/3)πr³ and its radius increases at 2 cm s⁻¹. Find dV/dt in terms of r.', marks: 4, markScheme: `• Use the chain rule: dV/dt = (dV/dr)(dr/dt) (1)\n• dV/dr = 4πr² (1)\n• dr/dt = 2 (1)\n• dV/dt = 8πr² (1)` },
      { q: 'The area of a circle increases at 3 cm² s⁻¹. Find the rate of increase of the radius when r = 5.', marks: 4, markScheme: `• A = πr², so dA/dr = 2πr (1)\n• dr/dt = (dA/dt)/(dA/dr) (1)\n• = 3/(2π × 5) (1)\n• = 3/(10π) ≈ 0.0955 cm s⁻¹ (1)` },
      { q: 'A closed cylinder has a fixed volume. Show that its surface area is least when the height equals the diameter.', marks: 6, markScheme: `• Volume V = πr²h, so h = V/(πr²) (1)\n• Surface area A = 2πr² + 2πrh (1)\n• Substitute: A = 2πr² + 2V/r (1)\n• dA/dr = 4πr − 2V/r² (1)\n• Set to zero: 4πr³ = 2V, so V = 2πr³ (1)\n• Then h = 2πr³/(πr²) = 2r, which is the diameter (1)` },
      { q: 'A rectangle has perimeter 40 cm. Find the dimensions that maximise its area, justifying that your answer is a maximum.', marks: 5, markScheme: `• Let the sides be x and 20 − x (1)\n• Area A = x(20 − x) = 20x − x² (1)\n• dA/dx = 20 − 2x, set to zero to give x = 10 (1)\n• d²A/dx² = −2 < 0, confirming a maximum (1)\n• The rectangle is a 10 cm square, with area 100 cm² (1)` },
      { q: 'Explain what is meant by a point of inflection, and state the test for one.', marks: 3, markScheme: `• A point where the curve changes from concave up to concave down, or the reverse (1)\n• The second derivative is zero there (1)\n• and must change sign either side, which is what distinguishes it from a stationary point (1)` },
      { q: 'Differentiate y = (3x² + 1)/x, simplifying first.', marks: 3, markScheme: `• Simplify to y = 3x + x^(−1) (1)\n• Differentiate term by term (1)\n• dy/dx = 3 − 1/x² (1)` },
      { q: 'Differentiate y = sin²x cos x.', marks: 4, markScheme: `• Apply the product rule with u = sin²x and v = cos x (1)\n• u′ = 2 sin x cos x by the chain rule (1)\n• u′v = 2 sin x cos²x and uv′ = −sin³x (1)\n• dy/dx = 2 sin x cos²x − sin³x (1)` },
      { q: 'If displacement is s(t), state what ds/dt and d²s/dt² represent, and find the velocity when s = t³ − 3t at t = 2.', marks: 4, markScheme: `• ds/dt is the velocity (1)\n• d²s/dt² is the acceleration (1)\n• v = 3t² − 3 (1)\n• At t = 2, v = 12 − 3 = 9 (1)` },
    ]
  },

  '1.10': {
    name: 'Integration',
    questions: [
      { q: 'Write down the general result for the integral of xⁿ, stating the value of n for which it fails and what is used instead.', marks: 3, markScheme: `• The integral of xⁿ is x^(n+1)/(n + 1) + c (1)\n• It fails for n = −1, since the denominator would be zero (1)\n• In that case the integral of 1/x is ln|x| + c (1)` },
      { q: 'Explain why a constant of integration is needed for an indefinite integral but not for a definite one.', marks: 3, markScheme: `• Differentiating any constant gives zero, so the original constant cannot be recovered (1)\n• An indefinite integral therefore represents a family of functions and needs + c (1)\n• In a definite integral the constant appears in both F(b) and F(a) and cancels on subtraction (1)` },
      { q: 'Explain why the modulus is written in ln|x| when integrating 1/x.', marks: 2, markScheme: `• The function 1/x is defined for negative x as well as positive (1)\n• The modulus allows the result to be valid on both sides of the origin, since the logarithm of a negative number is undefined (1)` },
      { q: 'Find the integral of 3x² − 4x + 5 with respect to x.', marks: 3, markScheme: `• Integrate term by term (1)\n• x³ − 2x² + 5x (1)\n• Include the constant of integration: + c (1)` },
      { q: 'Find the integral of √x + 1/x² with respect to x, writing each term as a power of x first.', marks: 4, markScheme: `• Rewrite as x^(1/2) + x^(−2) (1)\n• Integral of x^(1/2) is (2/3)x^(3/2) (1)\n• Integral of x^(−2) is −x^(−1) (1)\n• Answer (2/3)x^(3/2) − 1/x + c (1)` },
      { q: 'Write down the integrals of eˣ, e^(kx), cos x, sin x and sec²x.', marks: 5, markScheme: `• Integral of eˣ is eˣ + c (1)\n• Integral of e^(kx) is e^(kx)/k + c (1)\n• Integral of cos x is sin x + c (1)\n• Integral of sin x is −cos x + c (1)\n• Integral of sec²x is tan x + c (1)` },
      { q: 'State the Fundamental Theorem of Calculus and explain what it tells you about integration and differentiation.', marks: 3, markScheme: `• The definite integral from a to b of f(x) equals F(b) − F(a), where F′ = f (1)\n• It connects the area under a curve with the antiderivative (1)\n• It establishes that differentiation and integration are inverse processes (1)` },
      { q: 'Evaluate the definite integral from 1 to 3 of (2x + 1) dx.', marks: 3, markScheme: `• Antiderivative is x² + x (1)\n• Substitute the limits: (9 + 3) − (1 + 1) (1)\n• Value is 10 (1)` },
      { q: 'Evaluate the definite integral from 0 to 2 of (3x² + 2x) dx.', marks: 3, markScheme: `• Antiderivative is x³ + x² (1)\n• Substitute: (8 + 4) − 0 (1)\n• Value is 12 (1)` },
      { q: 'Evaluate the definite integral from 1 to e of (1/x) dx.', marks: 2, markScheme: `• Antiderivative is ln|x| (1)\n• ln e − ln 1 = 1 − 0 = 1 (1)` },
      { q: 'Evaluate the definite integral from −1 to 1 of x³ dx, and explain the result using symmetry.', marks: 3, markScheme: `• Antiderivative is x⁴/4 (1)\n• (1/4) − (1/4) = 0 (1)\n• x³ is an odd function, so the areas either side of the origin are equal in size and opposite in sign, cancelling exactly (1)` },
      { q: 'Explain why a definite integral can be zero even though the curve encloses a non-zero area, and describe how to find the actual area.', marks: 3, markScheme: `• Regions below the x-axis contribute negatively to the integral (1)\n• Positive and negative contributions may cancel (1)\n• Split the integral at each point where the curve crosses the axis and add the magnitudes of the separate values (1)` },
      { q: 'Find the area between the curve y = 4 − x² and the x-axis, between the points where it crosses the axis.', marks: 4, markScheme: `• Roots at x = ±2 (1)\n• Integrate from −2 to 2 (1)\n• Antiderivative 4x − x³/3 (1)\n• Area = (8 − 8/3) − (−8 + 8/3) = 32/3 (1)` },
      { q: 'Find the area enclosed between the curve y = x² and the line y = 2x.', marks: 5, markScheme: `• Find the intersections: x² = 2x gives x = 0 and x = 2 (1)\n• Integrate the difference (upper minus lower) from 0 to 2 (1)\n• Integrand is 2x − x² (1)\n• Antiderivative x² − x³/3 (1)\n• Area = 4 − 8/3 = 4/3 (1)` },
      { q: 'Find the area enclosed between the curve y = x² and the line y = x, between x = 0 and x = 1.', marks: 4, markScheme: `• The line lies above the curve on this interval (1)\n• Integrate x − x² from 0 to 1 (1)\n• Antiderivative x²/2 − x³/3 (1)\n• Area = 1/2 − 1/3 = 1/6 (1)` },
      { q: 'Explain how to decide which function to subtract from which when finding the area between two curves.', marks: 2, markScheme: `• Determine which curve is above the other on the interval, by sketching or testing a value (1)\n• Integrate upper minus lower, so that the integrand is non-negative and the area comes out positive (1)` },
      { q: 'Find the integral of (2x + 1)⁵ with respect to x, using a substitution.', marks: 4, markScheme: `• Let u = 2x + 1, so du = 2 dx (1)\n• The integral becomes ½ times the integral of u⁵ du (1)\n• = u⁶/12 (1)\n• Answer (2x + 1)⁶/12 + c (1)` },
      { q: 'Find the integral of (3x + 2)⁴ with respect to x.', marks: 3, markScheme: `• Raise the power by one and divide (1)\n• Divide also by the inner derivative, 3 (1)\n• Answer (3x + 2)⁵/15 + c (1)` },
      { q: 'Find the integral of x e^(x²) with respect to x.', marks: 3, markScheme: `• Let u = x², so du = 2x dx (1)\n• The integral becomes ½ times the integral of e^u du (1)\n• Answer ½e^(x²) + c (1)` },
      { q: 'Find the integral of 1/(2x + 1) with respect to x.', marks: 3, markScheme: `• Recognise the form f′/f up to a constant (1)\n• The inner derivative is 2, so divide by 2 (1)\n• Answer ½ln|2x + 1| + c (1)` },
      { q: 'State the standard result for the integral of f′(x)/f(x) and use it to evaluate the definite integral from 0 to 1 of 2x/(x² + 1) dx.', marks: 4, markScheme: `• The integral of f′(x)/f(x) is ln|f(x)| + c (1)\n• Here f(x) = x² + 1 and f′(x) = 2x (1)\n• Antiderivative is ln(x² + 1) (1)\n• Value = ln 2 − ln 1 = ln 2 (1)` },
      { q: 'Find the integral of sin 2x with respect to x, and the integral of cos 3x with respect to x.', marks: 2, markScheme: `• Integral of sin 2x is −½cos 2x + c (1)\n• Integral of cos 3x is ⅓sin 3x + c (1)` },
      { q: 'Explain what must also be changed when a substitution is used in a definite integral, and why.', marks: 2, markScheme: `• The limits must be converted from values of x to the corresponding values of u (1)\n• Otherwise x-limits would be applied to an expression in u, giving a wrong answer; alternatively substitute back to x before applying the original limits (1)` },
      { q: 'State the integration by parts formula and use it to find the integral of x eˣ.', marks: 4, markScheme: `• The formula is the integral of u dv/dx equals uv minus the integral of v du/dx (1)\n• Take u = x and dv/dx = eˣ (1)\n• Obtain xeˣ minus the integral of eˣ (1)\n• Answer eˣ(x − 1) + c (1)` },
      { q: 'Find the integral of ln x with respect to x, explaining the choice of u and dv/dx.', marks: 4, markScheme: `• Write the integrand as 1 × ln x (1)\n• Take u = ln x and dv/dx = 1, since ln x has no elementary antiderivative on its own (1)\n• Obtain x ln x minus the integral of x × 1/x (1)\n• Answer x ln x − x + c (1)` },
      { q: 'Find the integral of x² eˣ with respect to x.', marks: 5, markScheme: `• Apply parts with u = x², dv/dx = eˣ (1)\n• Obtain x²eˣ minus the integral of 2xeˣ (1)\n• Apply parts a second time to the remaining integral (1)\n• The remaining integral gives 2xeˣ − 2eˣ (1)\n• Answer eˣ(x² − 2x + 2) + c (1)` },
      { q: 'Explain how you choose which factor to take as u when integrating by parts.', marks: 2, markScheme: `• Choose u to be the factor that becomes simpler when differentiated (1)\n• The other factor must be one you can integrate; a poor choice makes the remaining integral harder than the original (1)` },
      { q: 'Describe the method used to evaluate the integral of eˣ sin x, without carrying out the full working.', marks: 3, markScheme: `• Apply integration by parts (1)\n• Apply it a second time, which returns a multiple of the original integral (1)\n• Treat the original integral as an unknown and solve the resulting equation algebraically (1)` },
      { q: 'Express (2x + 3)/((x + 1)(x + 2)) in partial fractions and hence find its integral.', marks: 5, markScheme: `• Write as A/(x + 1) + B/(x + 2) (1)\n• 2x + 3 = A(x + 2) + B(x + 1) (1)\n• Substituting gives A = 1 and B = 1 (1)\n• Integrate each term separately (1)\n• Answer ln|x + 1| + ln|x + 2| + c (1)` },
      { q: 'Explain why partial fractions are useful in integration.', marks: 2, markScheme: `• A single fraction with a factorised denominator has no standard integral (1)\n• Splitting it produces terms of the form A/(x + a), each of which integrates to a logarithm (1)` },
      { q: 'Find the integral of cos²x with respect to x, using a double angle identity.', marks: 4, markScheme: `• Use cos²x = ½(1 + cos 2x) (1)\n• The integral becomes ½ times the integral of (1 + cos 2x) (1)\n• = ½(x + ½sin 2x) (1)\n• Answer x/2 + (sin 2x)/4 + c (1)` },
      { q: 'Evaluate the definite integral from 0 to π/2 of sin x cos x dx.', marks: 4, markScheme: `• Use sin x cos x = ½sin 2x (1)\n• Antiderivative is −(cos 2x)/4 (1)\n• Substitute the limits: −(cos π)/4 + (cos 0)/4 (1)\n• Value = 1/4 + 1/4 = 1/2 (1)` },
      { q: 'Evaluate the definite integral from 0 to π of sin x dx.', marks: 3, markScheme: `• Antiderivative is −cos x (1)\n• Substitute: −cos π + cos 0 (1)\n• Value = 1 + 1 = 2 (1)` },
      { q: 'Find the integral of tan x with respect to x, showing your method.', marks: 3, markScheme: `• Write tan x as sin x/cos x (1)\n• This is of the form −f′/f with f = cos x (1)\n• Integral is −ln|cos x| + c, equivalently ln|sec x| + c (1)` },
      { q: 'Find the integral of 1/(x ln x) with respect to x.', marks: 3, markScheme: `• Let u = ln x, so du = (1/x) dx (1)\n• The integral becomes the integral of 1/u du (1)\n• Answer ln|ln x| + c (1)` },
      { q: 'Explain how you would decide which integration technique to use for a given integrand, listing three cases.', marks: 3, markScheme: `• If the integrand contains an inner function together with its derivative, use substitution (1)\n• If it is a product of unlike functions such as x eˣ or ln x, use integration by parts (1)\n• If it is an algebraic fraction with a factorisable denominator, use partial fractions (1)` },
      { q: 'A curve has dy/dx = 6x² and passes through (1, 4). Find its equation.', marks: 4, markScheme: `• Integrate: y = 2x³ + c (1)\n• Substitute x = 1 and y = 4 (1)\n• 4 = 2 + c, so c = 2 (1)\n• y = 2x³ + 2 (1)` },
      { q: 'Explain what a definite integral of a rate of change represents, giving an example.', marks: 3, markScheme: `• It gives the total change in the quantity over the interval (1)\n• Because integrating a rate reverses the differentiation that produced it (1)\n• Example: integrating velocity over a time interval gives the displacement (1)` },
      { q: 'Find the integral of (x + 1)/x with respect to x, simplifying first.', marks: 3, markScheme: `• Split the fraction: 1 + 1/x (1)\n• Integrate term by term (1)\n• Answer x + ln|x| + c (1)` },
      { q: 'The region bounded by y = √x, the x-axis and the line x = 4 is shaded. Find its area.', marks: 4, markScheme: `• Integrate x^(1/2) from 0 to 4 (1)\n• Antiderivative is (2/3)x^(3/2) (1)\n• Substitute the upper limit: (2/3) × 8 (1)\n• Area = 16/3 (1)` },
    ]
  },

  '1.11': {
    name: 'Differential Equations',
    questions: [
      { q: 'Explain the difference between a general solution and a particular solution of a differential equation.', marks: 2, markScheme: `• A general solution contains an arbitrary constant and represents a family of curves (1)\n• A particular solution uses an initial or boundary condition to fix that constant, giving a single curve (1)` },
      { q: 'Write down a differential equation for each of the following: (a) the rate of growth of a population is proportional to its size; (b) the rate of decay of a substance is proportional to the amount present.', marks: 2, markScheme: `• dP/dt = kP (1)\n• dN/dt = −kN, with k positive (1)` },
      { q: 'Write down a differential equation for the statement "the rate of increase of y is proportional to the square of y".', marks: 2, markScheme: `• Identify the rate as dy/dt (1)\n• dy/dt = ky² (1)` },
      { q: "Write down Newton's law of cooling as a differential equation, defining your symbols.", marks: 3, markScheme: `• dθ/dt = −k(θ − θ₀) (1)\n• θ is the temperature of the body and θ₀ the temperature of the surroundings (1)\n• k is a positive constant, and the minus sign gives cooling towards the surroundings (1)` },
      { q: 'Solve dy/dx = 6x², giving the general solution.', marks: 2, markScheme: `• Integrate both sides with respect to x (1)\n• y = 2x³ + c (1)` },
      { q: 'Solve dy/dx = 6x² given that y = 4 when x = 1.', marks: 3, markScheme: `• Integrate: y = 2x³ + c (1)\n• Substitute x = 1, y = 4: 4 = 2 + c (1)\n• y = 2x³ + 2 (1)` },
      { q: 'Describe the method of separating the variables, stating when it can be used.', marks: 3, markScheme: `• It applies when the equation can be written as dy/dx = f(x)g(y) (1)\n• Rearrange so that all the y terms are with dy and all the x terms with dx (1)\n• Integrate both sides, including a single constant of integration (1)` },
      { q: 'Solve dy/dx = xy given that y = 1 when x = 0.', marks: 5, markScheme: `• Separate: (1/y) dy = x dx (1)\n• Integrate both sides (1)\n• ln y = x²/2 + c (1)\n• Substitute x = 0, y = 1 to give c = 0 (1)\n• y = e^(x²/2) (1)` },
      { q: 'Solve dy/dx = y/x for x > 0, giving your answer in the simplest form.', marks: 4, markScheme: `• Separate: (1/y) dy = (1/x) dx (1)\n• Integrate: ln y = ln x + c (1)\n• Write c = ln A so that ln y = ln(Ax) (1)\n• y = Ax (1)` },
      { q: 'Explain the advantage of writing the constant of integration as ln A rather than c when solving a separable equation involving logarithms.', marks: 2, markScheme: `• It converts an additive constant into a multiplicative one (1)\n• The final answer then takes a simpler form such as y = Ax rather than y = e^c × x (1)` },
      { q: 'Solve dy/dx = 2xy².', marks: 4, markScheme: `• Separate: y^(−2) dy = 2x dx (1)\n• Integrate the left side to −1/y (1)\n• Integrate the right side to x² (1)\n• −1/y = x² + c (1)` },
      { q: 'Solve dy/dx = y cos x.', marks: 4, markScheme: `• Separate: (1/y) dy = cos x dx (1)\n• Integrate: ln y = sin x + c (1)\n• Exponentiate both sides (1)\n• y = Ae^(sin x) (1)` },
      { q: 'Solve dy/dx = eˣ/y.', marks: 4, markScheme: `• Separate: y dy = eˣ dx (1)\n• Integrate the left side to y²/2 (1)\n• Integrate the right side to eˣ (1)\n• y² = 2eˣ + c (1)` },
      { q: 'Solve dy/dx = y tan x.', marks: 4, markScheme: `• Separate: (1/y) dy = tan x dx (1)\n• Integrate the right side to ln|sec x| (1)\n• ln y = ln|sec x| + c (1)\n• y = A sec x (1)` },
      { q: 'Solve (1 + x²) dy/dx = xy.', marks: 5, markScheme: `• Separate: (1/y) dy = x/(1 + x²) dx (1)\n• The right side is of the form f′/f up to a factor of ½ (1)\n• Integrate: ln y = ½ln(1 + x²) + c (1)\n• Exponentiate (1)\n• y = A√(1 + x²) (1)` },
      { q: 'Solve x dy/dx + y = 0.', marks: 4, markScheme: `• Rearrange to x dy/dx = −y (1)\n• Separate: (1/y) dy = −(1/x) dx (1)\n• Integrate: ln y = −ln x + c (1)\n• xy = A (1)` },
      { q: 'Solve dy/dx = (x + 1)/(y − 2).', marks: 4, markScheme: `• Separate: (y − 2) dy = (x + 1) dx (1)\n• Integrate the left side to (y − 2)²/2 (1)\n• Integrate the right side to x²/2 + x (1)\n• (y − 2)² = x² + 2x + c (1)` },
      { q: 'Solve dy/dx = e^(x − y).', marks: 4, markScheme: `• Write e^(x − y) as eˣ e^(−y) (1)\n• Separate: e^y dy = eˣ dx (1)\n• Integrate both sides (1)\n• e^y = eˣ + c (1)` },
      { q: 'Solve dy/dt = 3y given that y = 5 when t = 0.', marks: 3, markScheme: `• General solution y = Ae^(3t) (1)\n• Substitute t = 0, y = 5 to give A = 5 (1)\n• y = 5e^(3t) (1)` },
      { q: 'Show that the solution of dP/dt = kP with P = P₀ at t = 0 is P = P₀e^(kt).', marks: 4, markScheme: `• Separate: (1/P) dP = k dt (1)\n• Integrate: ln P = kt + c (1)\n• Exponentiate: P = Ae^(kt) (1)\n• At t = 0, P = P₀ so A = P₀, giving P = P₀e^(kt) (1)` },
      { q: "A body cools according to dθ/dt = −k(θ − 20), with θ = 100 when t = 0. Solve the equation and state the long-term temperature.", marks: 6, markScheme: `• Separate: dθ/(θ − 20) = −k dt (1)\n• Integrate: ln(θ − 20) = −kt + c (1)\n• Exponentiate: θ − 20 = Ae^(−kt) (1)\n• At t = 0, θ = 100, so A = 80 (1)\n• θ = 20 + 80e^(−kt) (1)\n• As t tends to infinity the exponential tends to 0, so θ tends to 20 °C, the temperature of the surroundings (1)` },
      { q: 'Explain how checking the long-term behaviour of a solution can help you detect an error.', marks: 2, markScheme: `• The limit predicted by the solution should agree with what physically must happen (1)\n• For example a cooling body must approach the ambient temperature; any other limit indicates an algebraic mistake (1)` },
      { q: 'The equation dy/dt = k(A − y) describes a quantity approaching a limit. Describe the behaviour of y and state its limiting value.', marks: 3, markScheme: `• The rate of change is proportional to the shortfall A − y (1)\n• As y approaches A the rate falls, so growth slows (1)\n• y tends to A but never exceeds it (1)` },
      { q: 'A falling body satisfies dv/dt = g − kv. Find its terminal velocity and explain the physical meaning.', marks: 3, markScheme: `• Terminal velocity occurs when the acceleration is zero, so dv/dt = 0 (1)\n• g − kv = 0, giving v = g/k (1)\n• At this speed the resistance balances the weight, so the body falls at constant velocity (1)` },
      { q: 'Explain why a body approaching terminal velocity never quite reaches it according to the model.', marks: 2, markScheme: `• The solution contains a decaying exponential term that tends to zero but is never exactly zero (1)\n• The velocity therefore approaches the terminal value asymptotically rather than attaining it in finite time (1)` },
      { q: 'A radioactive substance satisfies dN/dt = −kN. Show that the half-life T satisfies kT = ln 2.', marks: 4, markScheme: `• The solution is N = N₀e^(−kt) (1)\n• At the half-life, N = N₀/2, so e^(−kT) = 1/2 (1)\n• Take natural logarithms: −kT = −ln 2 (1)\n• kT = ln 2 (1)` },
      { q: 'A substance has half-life 10 days. Find the value of k in the model N = N₀e^(−kt), to 3 significant figures.', marks: 3, markScheme: `• Use kT = ln 2 with T = 10 (1)\n• k = (ln 2)/10 (1)\n• k = 0.0693 to 3 s.f. (1)` },
      { q: 'Write down the logistic differential equation and explain why it is preferred to dP/dt = kP for modelling a real population.', marks: 3, markScheme: `• dy/dt = ky(1 − y), or a version with a carrying capacity (1)\n• The exponential model predicts unlimited growth (1)\n• The logistic model includes a ceiling, so growth slows as resources become limiting (1)` },
      { q: 'Explain what technique is needed to separate and integrate dy/dx = y(1 − y), and why.', marks: 3, markScheme: `• Separating gives an integral of 1/(y(1 − y)) with respect to y (1)\n• This has a product in the denominator and no standard integral (1)\n• Partial fractions are needed, splitting it into 1/y + 1/(1 − y) (1)` },
      { q: 'Water drains from a tank so that dV/dt = −k√V. Explain why this equation is separable and describe how V depends on t.', marks: 3, markScheme: `• It can be written as V^(−1/2) dV = −k dt, so the variables separate (1)\n• Integrating gives 2√V = −kt + c (1)\n• So √V is a linear function of t, and V decreases quadratically until the tank empties (1)` },
      { q: 'A tank holds a fixed volume of brine. Salt enters at a constant rate and the well-mixed solution leaves at the same volumetric rate. Explain why the amount of salt S satisfies an equation of the form dS/dt = a − bS.', marks: 4, markScheme: `• Salt enters at a constant rate, contributing a constant term a (1)\n• The concentration of salt is S divided by the fixed volume (1)\n• Salt leaves at a rate proportional to that concentration, so proportional to S (1)\n• The net rate of change is therefore a − bS (1)` },
      { q: 'For dy/dx = k(y − 5) with k > 0 and y > 5, describe what happens to y as x increases, justifying your answer.', marks: 3, markScheme: `• Since y > 5, the factor y − 5 is positive (1)\n• With k positive, dy/dx is positive so y increases (1)\n• The rate grows as y increases, so y moves away from 5 ever faster (1)` },
      { q: 'Explain why the constant of integration must be included before applying an initial condition, not after.', marks: 2, markScheme: `• The initial condition is used to determine the value of that constant (1)\n• Without it there is nothing to determine, and the particular solution cannot be found (1)` },
      { q: 'Solve dy/dx = x²y, giving the general solution.', marks: 4, markScheme: `• Separate: (1/y) dy = x² dx (1)\n• Integrate: ln y = x³/3 + c (1)\n• Exponentiate (1)\n• y = Ae^(x³/3) (1)` },
      { q: 'Solve dy/dx = (1 + y)/x for x > 0.', marks: 4, markScheme: `• Separate: dy/(1 + y) = dx/x (1)\n• Integrate: ln(1 + y) = ln x + c (1)\n• Write c = ln A (1)\n• 1 + y = Ax (1)` },
      { q: 'A population model gives P = 200e^(0.05t). Find the time taken for the population to double, to 3 significant figures.', marks: 4, markScheme: `• Set e^(0.05t) = 2 (1)\n• 0.05t = ln 2 (1)\n• t = (ln 2)/0.05 (1)\n• t = 13.9 (1)` },
      { q: 'Give three criticisms that could be made of an exponential population growth model.', marks: 3, markScheme: `• It predicts unbounded growth, ignoring limited resources (1)\n• The growth constant is assumed fixed, though it may vary with conditions (1)\n• It treats the population as continuous when it is actually discrete (1)` },
      { q: 'Explain why extrapolating a fitted differential equation model far beyond the data range is not justified.', marks: 2, markScheme: `• The model was fitted only over the observed range, where its assumptions held (1)\n• Outside that range conditions may change, so the relationship may no longer apply (1)` },
      { q: 'Solve dy/dt = 4 − y given that y = 0 when t = 0.', marks: 5, markScheme: `• Separate: dy/(4 − y) = dt (1)\n• Integrate: −ln(4 − y) = t + c (1)\n• Rearrange: 4 − y = Ae^(−t) (1)\n• At t = 0, y = 0 so A = 4 (1)\n• y = 4(1 − e^(−t)) (1)` },
      { q: 'For the solution y = 4(1 − e^(−t)), state the long-term value of y and describe how it is approached.', marks: 2, markScheme: `• As t tends to infinity, e^(−t) tends to 0 so y tends to 4 (1)\n• y increases towards 4, with the rate of increase falling as the gap closes, approaching it asymptotically (1)` },
    ]
  },

  '1.12': {
    name: 'Numerical Methods',
    questions: [
      { q: 'Explain why numerical methods are needed in mathematics, and state what they produce.', marks: 2, markScheme: `• Most equations have no exact algebraic solution (1)\n• Numerical methods produce an approximation to a stated degree of accuracy (1)` },
      { q: 'State the change of sign condition for locating a root, including all necessary assumptions.', marks: 3, markScheme: `• If f(a) and f(b) have opposite signs (1)\n• and f is continuous on the interval [a, b] (1)\n• then f(x) = 0 has at least one root between a and b (1)` },
      { q: 'Show that x³ − 2x − 5 = 0 has a root between x = 2 and x = 3.', marks: 3, markScheme: `• f(2) = 8 − 4 − 5 = −1 (1)\n• f(3) = 27 − 6 − 5 = 16 (1)\n• f changes sign and is continuous on [2, 3], so a root lies in the interval (1)` },
      { q: 'Show that eˣ = 3 − x has a root between x = 0 and x = 1.', marks: 4, markScheme: `• Rearrange to f(x) = eˣ + x − 3 (1)\n• f(0) = 1 + 0 − 3 = −2 (1)\n• f(1) = e + 1 − 3 ≈ 0.718 (1)\n• The sign changes and f is continuous, so a root lies between 0 and 1 (1)` },
      { q: 'Explain why the continuity of f must be stated when using a change of sign argument.', marks: 2, markScheme: `• A discontinuous function can change sign without crossing zero (1)\n• The argument would then be invalid, as with a vertical asymptote in the interval (1)` },
      { q: 'Explain how you would show that a root is 1.86 correct to 2 decimal places.', marks: 3, markScheme: `• Evaluate f at the bounds of the rounding interval, 1.855 and 1.865 (1)\n• Show that f changes sign between them (1)\n• Every value in that interval rounds to 1.86, so the root is 1.86 to 2 d.p. (1)` },
      { q: 'Describe one situation in which a change of sign method fails to detect a root, with an example.', marks: 3, markScheme: `• The curve touches the x-axis without crossing it, as at a repeated root (1)\n• Example f(x) = (x − 2)² (1)\n• f is non-negative everywhere, so there is no sign change despite the root at x = 2 (1)` },
      { q: 'Describe a situation in which a change of sign occurs but there is no root, with an example.', marks: 3, markScheme: `• A vertical asymptote lies within the interval (1)\n• Example f(x) = 1/(x − 2), with f(1) = −1 and f(3) = 1 (1)\n• The sign change is caused by the discontinuity at x = 2, not by a root (1)` },
      { q: 'Explain how a change of sign search can miss two roots lying in the same interval.', marks: 2, markScheme: `• If the curve crosses the axis twice within the interval, the signs at the two endpoints agree (1)\n• The method reports no sign change, so both roots are missed (1)` },
      { q: 'Describe the method of fixed point iteration, including what must be done to the equation first.', marks: 3, markScheme: `• Rearrange f(x) = 0 into the form x = g(x) (1)\n• Choose a starting value x₀ (1)\n• Apply x₍ₙ₊₁₎ = g(xₙ) repeatedly until the values converge (1)` },
      { q: 'Rearrange x³ − x − 4 = 0 into a form suitable for iteration, and write down the iterative formula.', marks: 3, markScheme: `• Rearrange to x³ = x + 4 (1)\n• Take the cube root: x = (x + 4)^(1/3) (1)\n• Iterative formula x₍ₙ₊₁₎ = (xₙ + 4)^(1/3) (1)` },
      { q: 'Explain why two different rearrangements of the same equation may behave differently under iteration.', marks: 3, markScheme: `• Convergence depends on the gradient of g near the root (1)\n• Iteration converges when |g′(x)| < 1 near the root and diverges when |g′(x)| > 1 (1)\n• Different rearrangements give different g, so one may converge while another diverges (1)` },
      { q: 'State the condition for a fixed point iteration to converge near a root.', marks: 2, markScheme: `• The iteration converges when the magnitude of g′(x) is less than 1 near the root (1)\n• The smaller the magnitude, the faster the convergence (1)` },
      { q: 'Describe the difference between a staircase and a cobweb diagram, and state when each occurs.', marks: 3, markScheme: `• Both are drawn between the curve y = g(x) and the line y = x (1)\n• A staircase occurs when g′(x) is positive, with successive values approaching the root from one side (1)\n• A cobweb occurs when g′(x) is negative, with values alternating either side of the root (1)` },
      { q: 'The iteration x₍ₙ₊₁₎ = √(2 + xₙ) converges. Find the limit, rejecting any invalid value with a reason.', marks: 4, markScheme: `• At the limit L = √(2 + L) (1)\n• Square and rearrange: L² − L − 2 = 0 (1)\n• Factorise (L − 2)(L + 1) = 0, so L = 2 or L = −1 (1)\n• Reject L = −1 since a square root is non-negative; the limit is 2 (1)` },
      { q: 'State the Newton-Raphson formula and describe its geometric interpretation.', marks: 3, markScheme: `• x₍ₙ₊₁₎ = xₙ − f(xₙ)/f′(xₙ) (1)\n• The tangent to the curve is drawn at the current point (1)\n• The next estimate is where that tangent meets the x-axis (1)` },
      { q: 'Apply one Newton-Raphson iteration to f(x) = x³ − 5 starting from x₀ = 2.', marks: 3, markScheme: `• f(2) = 3 and f′(x) = 3x², so f′(2) = 12 (1)\n• x₁ = 2 − 3/12 (1)\n• x₁ = 1.75 (1)` },
      { q: 'Apply a second Newton-Raphson iteration to f(x) = x³ − 5 from x₁ = 1.75, giving x₂ to 4 decimal places.', marks: 4, markScheme: `• f(1.75) = 5.359375 − 5 = 0.359375 (1)\n• f′(1.75) = 3 × 3.0625 = 9.1875 (1)\n• x₂ = 1.75 − 0.359375/9.1875 (1)\n• x₂ = 1.7109 (1)` },
      { q: 'Apply one Newton-Raphson iteration to f(x) = x² − 2 starting from x₀ = 1.', marks: 3, markScheme: `• f(1) = −1 and f′(1) = 2 (1)\n• x₁ = 1 − (−1)/2 (1)\n• x₁ = 1.5 (1)` },
      { q: 'Show that applying Newton-Raphson to f(x) = x² − a gives the iteration x₍ₙ₊₁₎ = ½(xₙ + a/xₙ).', marks: 4, markScheme: `• f′(x) = 2x (1)\n• x₍ₙ₊₁₎ = xₙ − (xₙ² − a)/(2xₙ) (1)\n• Combine over a common denominator: (2xₙ² − xₙ² + a)/(2xₙ) (1)\n• = (xₙ² + a)/(2xₙ) = ½(xₙ + a/xₙ) (1)` },
      { q: 'Explain why Newton-Raphson usually converges faster than a simple fixed point iteration.', marks: 2, markScheme: `• Near a simple root the error is approximately squared at each step (1)\n• The number of correct digits therefore roughly doubles each iteration, whereas a simple iteration typically reduces the error by a constant factor (1)` },
      { q: 'Describe two circumstances in which the Newton-Raphson method fails.', marks: 4, markScheme: `• If f′(xₙ) = 0 the tangent is horizontal (1)\n• It never meets the x-axis, so the formula involves division by zero and breaks down (1)\n• If the starting value is near a stationary point, the tangent is nearly horizontal (1)\n• The next estimate is thrown far away, so the method may converge to a different root or diverge (1)` },
      { q: 'Explain why a sketch is the clearest way to explain a Newton-Raphson failure.', marks: 2, markScheme: `• The method is defined geometrically by following the tangent to the axis (1)\n• A sketch shows directly why a nearly horizontal tangent sends the next estimate far from the root (1)` },
      { q: 'State the trapezium rule for n strips, defining the strip width.', marks: 3, markScheme: `• Strip width h = (b − a)/n (1)\n• The integral is approximately (h/2)[y₀ + yₙ + 2(y₁ + y₂ + … + y₍ₙ₋₁₎)] (1)\n• The first and last ordinates are counted once and all interior ordinates are doubled (1)` },
      { q: 'For the interval from 1 to 3 divided into 4 strips, find the strip width and list the x-values of the ordinates.', marks: 3, markScheme: `• h = (3 − 1)/4 = 0.5 (1)\n• Five ordinates are needed for four strips (1)\n• x = 1, 1.5, 2, 2.5, 3 (1)` },
      { q: 'Explain the relationship between the number of strips and the number of ordinates in the trapezium rule.', marks: 2, markScheme: `• Each strip is bounded by two ordinates, but adjacent strips share one (1)\n• So n strips require n + 1 ordinates (1)` },
      { q: 'Explain why the trapezium rule gives an overestimate when the curve is concave upwards.', marks: 3, markScheme: `• Each trapezium is bounded above by a chord joining two points on the curve (1)\n• For a concave upwards curve every chord lies above the curve (1)\n• Each trapezium therefore has more area than the region beneath the curve, so the total is too large (1)` },
      { q: 'Explain why the trapezium rule gives an underestimate when the curve is concave downwards.', marks: 2, markScheme: `• For a concave downwards curve each chord lies below the curve (1)\n• Each trapezium therefore has less area than the region beneath the curve, so the total is too small (1)` },
      { q: 'Describe how to justify, in an examination answer, that a trapezium estimate is an overestimate.', marks: 2, markScheme: `• State that the curve is concave upwards on the interval concerned (1)\n• Explain that each chord therefore lies above the curve, so the estimate exceeds the true value (1)` },
      { q: 'Explain the effect on the error of halving the strip width in the trapezium rule.', marks: 2, markScheme: `• The error is approximately proportional to the square of the strip width (1)\n• Halving the width therefore reduces the error by a factor of about 4 (1)` },
      { q: 'Describe how sums of rectangles can be used to obtain bounds on the area under a curve.', marks: 3, markScheme: `• Draw rectangles whose heights are given by ordinates at the left or right of each strip (1)\n• For a monotonic function one choice gives an underestimate and the other an overestimate (1)\n• The true value of the integral therefore lies between the two sums (1)` },
      { q: 'For an increasing function, state whether left-hand rectangles give an upper or a lower bound, and justify your answer.', marks: 2, markScheme: `• They give a lower bound (1)\n• For an increasing function the left-hand ordinate is the smallest value on each strip, so each rectangle sits under the curve (1)` },
      { q: 'Explain what it means for an iteration to diverge, and describe what you would observe.', marks: 2, markScheme: `• The successive values do not settle towards a single limit (1)\n• The terms move steadily further away from the root, often increasing without bound or oscillating with growing amplitude (1)` },
      { q: 'A rearrangement gives x = 3/(x − 1). State a restriction on x and explain why it is needed.', marks: 2, markScheme: `• x must not equal 1 (1)\n• Otherwise the denominator is zero and g(x) is undefined, so the iteration cannot proceed (1)` },
      { q: 'Explain why locating an interval containing a root is usually done before starting an iterative method.', marks: 2, markScheme: `• Iterative methods require a starting value (1)\n• A change of sign search identifies an interval containing the root, providing a sensible starting value close to it (1)` },
      { q: 'The equation x³ − x − 4 = 0 has a root near x = 1.8. Explain why the iteration x₍ₙ₊₁₎ = (xₙ + 4)^(1/3) converges but x₍ₙ₊₁₎ = xₙ³ − 4 does not.', marks: 4, markScheme: `• For the first, g(x) = (x + 4)^(1/3) and g′(x) = (1/3)(x + 4)^(−2/3) (1)\n• Near x = 1.8 this has magnitude well below 1, so the iteration converges (1)\n• For the second, g(x) = x³ − 4 and g′(x) = 3x² (1)\n• Near x = 1.8 this is about 9.7, much greater than 1, so the iteration diverges (1)` },
      { q: 'Explain why the calculator mode matters when applying a numerical method to an equation involving trigonometric functions.', marks: 2, markScheme: `• Trigonometric functions give different values in degrees and radians (1)\n• Using the wrong mode produces entirely wrong iterates and can suggest a root where none exists (1)` },
      { q: 'A trapezium estimate for an integral is 12.4 using 4 strips and 12.35 using 8 strips. Comment on what this suggests about the true value.', marks: 3, markScheme: `• The estimates are converging as the number of strips increases (1)\n• The change from 4 to 8 strips is small, suggesting the true value is close to 12.35 (1)\n• Since the estimates are decreasing, the curve is likely concave upwards and both are overestimates (1)` },
      { q: 'Explain why a numerical answer from an iterative method should always be quoted to a stated accuracy.', marks: 2, markScheme: `• The method gives an approximation, not an exact value (1)\n• Quoting an accuracy makes clear how far the answer can be relied upon, and the accuracy must be justified, for example by a sign change (1)` },
      { q: 'Compare the change of sign method and the Newton-Raphson method, giving one advantage of each.', marks: 4, markScheme: `• Change of sign requires only evaluations of f, not its derivative (1)\n• It is guaranteed to bracket a root once a sign change is found (1)\n• Newton-Raphson converges much more rapidly near a simple root (1)\n• But it requires the derivative and may fail or diverge from a poor starting value (1)` },
    ]
  },

  '1.13': {
    name: 'Vectors',
    questions: [
      { q: 'Explain the difference between a scalar and a vector, giving two examples of each.', marks: 4, markScheme: `• A scalar has magnitude only (1)\n• Examples: mass, time, speed or distance (1)\n• A vector has both magnitude and direction (1)\n• Examples: displacement, velocity, acceleration or force (1)` },
      { q: 'State how vectors are distinguished in print and in handwriting, and how the magnitude of a vector a is written.', marks: 3, markScheme: `• In print vectors are shown in bold type (1)\n• In handwriting they are underlined (1)\n• The magnitude is written |a| or simply a in italic (1)` },
      { q: 'Define a unit vector, and describe how to find a unit vector in the direction of a given vector a.', marks: 2, markScheme: `• A unit vector has magnitude 1 (1)\n• Divide a by its magnitude: â = a/|a| (1)` },
      { q: 'Find the magnitude of the vector 3i + 4j.', marks: 2, markScheme: `• |a|² = 3² + 4² = 25 (1)\n• |a| = 5 (1)` },
      { q: 'Find the magnitude of the vector 2i − 3j + 6k.', marks: 2, markScheme: `• |a|² = 4 + 9 + 36 = 49 (1)\n• |a| = 7 (1)` },
      { q: 'Find a unit vector in the direction of 6i − 8j.', marks: 3, markScheme: `• Magnitude = √(36 + 64) (1)\n• = 10 (1)\n• Unit vector = 0.6i − 0.8j (1)` },
      { q: 'Find a unit vector in the direction of 2i − j + 2k.', marks: 3, markScheme: `• Magnitude = √(4 + 1 + 4) (1)\n• = 3 (1)\n• Unit vector = (2i − j + 2k)/3 (1)` },
      { q: 'Given a = 4i + j and b = i − 2j, find a + b, a − b and 3a.', marks: 3, markScheme: `• a + b = 5i − j (1)\n• a − b = 3i + 3j (1)\n• 3a = 12i + 3j (1)` },
      { q: 'Describe the geometric effect of multiplying a vector by a positive scalar and by a negative scalar.', marks: 2, markScheme: `• A positive scalar scales the magnitude and leaves the direction unchanged (1)\n• A negative scalar scales the magnitude and reverses the direction (1)` },
      { q: 'State the condition for two non-zero vectors to be parallel.', marks: 2, markScheme: `• One must be a scalar multiple of the other (1)\n• That is, a = λb for some non-zero scalar λ (1)` },
      { q: 'Find the value of k for which 2i + kj is parallel to 4i + 6j.', marks: 3, markScheme: `• The vectors are parallel if one is a scalar multiple of the other (1)\n• Comparing i components gives the factor 1/2 (1)\n• k = 6 × 1/2 = 3 (1)` },
      { q: 'Find the value of λ for which 2i + 4j + λk is parallel to i + 2j + 3k.', marks: 3, markScheme: `• Comparing i components gives the scalar factor 2 (1)\n• Check the j components: 4 = 2 × 2, consistent (1)\n• λ = 2 × 3 = 6 (1)` },
      { q: 'Express the vector 3i + 3j in magnitude-direction form.', marks: 3, markScheme: `• Magnitude = √(9 + 9) = 3√2 (1)\n• tan θ = 3/3 = 1 (1)\n• Direction 45° above the positive x-axis (1)` },
      { q: 'Express a vector of magnitude 10 at 30° above the positive x-axis in component form.', marks: 3, markScheme: `• Horizontal component = 10 cos 30° (1)\n• Vertical component = 10 sin 30° (1)\n• Vector = 5√3 i + 5j (1)` },
      { q: 'Find the magnitude and direction of the vector −3i − 4j, giving the direction as an angle measured from the positive x-axis.', marks: 4, markScheme: `• Magnitude = √(9 + 16) = 5 (1)\n• The related acute angle satisfies tan θ = 4/3, giving 53.1° (1)\n• Both components are negative, so the vector points into the third quadrant (1)\n• Direction = 180° + 53.1° = 233.1° (1)` },
      { q: 'Explain why an arctangent calculation alone is not sufficient to determine the direction of a vector.', marks: 2, markScheme: `• The arctangent function returns angles only in the first and fourth quadrants (1)\n• The signs of the components must be used to identify the correct quadrant, and an adjustment made if necessary (1)` },
      { q: 'For points A and B with position vectors a and b, write down an expression for the vector AB, and explain the order of the terms.', marks: 2, markScheme: `• AB = b − a (1)\n• The rule is destination minus start; reversing it gives a vector of the same magnitude in the opposite direction (1)` },
      { q: 'Points A(2, 1) and B(6, 4) are given. Find the vector AB, its magnitude, and a unit vector in its direction.', marks: 4, markScheme: `• AB = b − a = 4i + 3j (1)\n• |AB|² = 16 + 9 = 25 (1)\n• |AB| = 5 (1)\n• Unit vector = 0.8i + 0.6j (1)` },
      { q: 'Points A(2, −1, 4) and B(5, 3, 0) are given. Find the distance AB.', marks: 3, markScheme: `• AB = 3i + 4j − 4k (1)\n• |AB|² = 9 + 16 + 16 = 41 (1)\n• |AB| = √41 (1)` },
      { q: 'Find the distance from the origin to the point with position vector 2i + 3j + 6k.', marks: 2, markScheme: `• Magnitude² = 4 + 9 + 36 = 49 (1)\n• Distance = 7 (1)` },
      { q: 'Write down the position vector of the midpoint of AB in terms of the position vectors a and b.', marks: 2, markScheme: `• The midpoint is halfway along AB (1)\n• Its position vector is (a + b)/2 (1)` },
      { q: 'Find the position vector of the point P dividing AB in the ratio 2 : 1, in terms of a and b.', marks: 4, markScheme: `• P is two-thirds of the way from A to B (1)\n• OP = a + (2/3)(b − a) (1)\n• Expand and simplify (1)\n• OP = (a + 2b)/3 (1)` },
      { q: 'Points A, B and C have position vectors i + j, 3i + 5j and 5i + 9j. Show that they are collinear.', marks: 4, markScheme: `• AB = b − a = 2i + 4j (1)\n• BC = c − b = 2i + 4j (1)\n• BC is a scalar multiple of AB, so the vectors are parallel (1)\n• They share the point B, so A, B and C lie on the same straight line (1)` },
      { q: 'Explain why showing two vectors are parallel is not sufficient to prove three points collinear.', marks: 2, markScheme: `• Parallel vectors can lie on two different, non-intersecting lines (1)\n• A common point must also be identified for the three points to lie on one line (1)` },
      { q: 'OACB is a parallelogram with OA = a and OB = b. Write down expressions for OC and for BA.', marks: 2, markScheme: `• OC = a + b, the diagonal from O (1)\n• BA = a − b (1)` },
      { q: 'Find the position vector of the centroid of a triangle whose vertices have position vectors a, b and c.', marks: 2, markScheme: `• The centroid is the average of the three position vectors (1)\n• Position vector = (a + b + c)/3 (1)` },
      { q: 'In triangle ABC the vertices have position vectors a, b and c, and M is the midpoint of BC. Find an expression for the vector AM.', marks: 3, markScheme: `• The position vector of M is (b + c)/2 (1)\n• AM is the position vector of M minus that of A (1)\n• AM = (b + c)/2 − a (1)` },
      { q: 'Two forces 3i + 2j and −i + 4j act on a particle. Find the resultant force and its magnitude.', marks: 3, markScheme: `• Add the vectors component by component (1)\n• Resultant = 2i + 6j (1)\n• Magnitude = √(4 + 36) = √40 = 2√10 (1)` },
      { q: 'Three forces F₁ = 2i + 3j, F₂ = −5i + j and F₃ act on a particle in equilibrium. Find F₃.', marks: 4, markScheme: `• Equilibrium means the vector sum of the forces is zero (1)\n• F₁ + F₂ = −3i + 4j (1)\n• F₃ = −(F₁ + F₂) (1)\n• F₃ = 3i − 4j (1)` },
      { q: 'Explain what is meant by the resultant of a set of forces, and how it is found using vectors.', marks: 2, markScheme: `• The resultant is the single force having the same effect as the whole set (1)\n• It is found by adding the force vectors component by component (1)` },
      { q: 'Given that |a| = 5 and |b| = 12, state the greatest and least possible values of |a + b| and describe when each occurs.', marks: 4, markScheme: `• Greatest value is 17 (1)\n• This occurs when the vectors point in the same direction (1)\n• Least value is 7 (1)\n• This occurs when they point in opposite directions (1)` },
      { q: 'Explain why |a + b| is not generally equal to |a| + |b|.', marks: 2, markScheme: `• Vectors add according to direction as well as magnitude (1)\n• Only when they are parallel and in the same direction do the magnitudes simply add; otherwise the resultant is shorter (1)` },
      { q: 'Explain why the magnitude of −a equals the magnitude of a.', marks: 2, markScheme: `• Each component is negated, and the magnitude squares each component (1)\n• Squaring removes the sign, so the magnitude is unchanged; only the direction reverses (1)` },
      { q: 'A particle has position vector 2i + j and moves with constant velocity 3i − j. Find its position vector after 4 seconds.', marks: 3, markScheme: `• Displacement = velocity × time = 4(3i − j) (1)\n• = 12i − 4j (1)\n• New position = (2 + 12)i + (1 − 4)j = 14i − 3j (1)` },
      { q: 'Explain how the unit vectors i, j and k are defined, and state which is added when moving from two to three dimensions.', marks: 3, markScheme: `• i and j are unit vectors along the x- and y-axes respectively (1)\n• k is the unit vector along the z-axis (1)\n• k is added when extending to three dimensions (1)` },
      { q: 'Write the column vector with components 3 and −2 in i, j form, and state its magnitude.', marks: 2, markScheme: `• 3i − 2j (1)\n• Magnitude = √(9 + 4) = √13 (1)` },
      { q: 'Explain what is meant by two vectors being equal.', marks: 2, markScheme: `• They must have the same magnitude and the same direction (1)\n• Their position in space is irrelevant, so equal vectors may start from different points (1)` },
      { q: 'A boat is steered with velocity 4i and the current has velocity 3j. Find the resultant velocity and its speed.', marks: 3, markScheme: `• Resultant velocity = 4i + 3j (1)\n• Speed is the magnitude, √(16 + 9) (1)\n• Speed = 5 (1)` },
      { q: 'Points P and Q have position vectors 3i + 4j and 7i + j. Find the position of Q relative to P and the distance PQ.', marks: 3, markScheme: `• Position of Q relative to P = q − p (1)\n• = 4i − 3j (1)\n• Distance = √(16 + 9) = 5 (1)` },
      { q: 'The vector a = 3i − j and b = λ(3i − j) where λ is a non-zero scalar. State the relationship between a and b, and explain what happens if λ is negative.', marks: 3, markScheme: `• a and b are parallel for every non-zero λ (1)\n• If λ is positive they point in the same direction (1)\n• If λ is negative they point in opposite directions, though they remain parallel (1)` },
    ]
  },

  '2.1': {
    name: 'Sampling',
    questions: [
      { q: 'Explain the difference between a population and a sample.', marks: 2, markScheme: `• A population is the entire group being studied (1)\n• A sample is a subset of that population, used to draw conclusions about it (1)` },
      { q: 'Explain the difference between a parameter and a statistic.', marks: 2, markScheme: `• A parameter is a numerical property of the population (1)\n• A statistic is a numerical quantity calculated from a sample (1)` },
      { q: 'Give two reasons why a sample might be used in preference to a census.', marks: 2, markScheme: `• A census is more expensive and time-consuming (1)\n• Testing may be destructive, so a census would destroy the entire population (1)` },
      { q: 'Give one situation in which a census would be more appropriate than a sample, with a reason.', marks: 2, markScheme: `• When the population is small and easily accessible (1)\n• The extra cost is then low and complete accuracy is achieved with no sampling error (1)` },
      { q: 'Explain why a census would be unsuitable for testing the lifetime of light bulbs.', marks: 2, markScheme: `• Testing a bulb to failure destroys it (1)\n• A census would destroy the entire stock, leaving nothing to sell (1)` },
      { q: 'Define simple random sampling.', marks: 2, markScheme: `• Every possible sample of the required size has the same probability of being selected (1)\n• Equivalently, every member of the population is equally likely to be chosen, independently of the others (1)` },
      { q: 'State what a sampling frame is and explain why simple random sampling requires one.', marks: 3, markScheme: `• A sampling frame is a list of all members of the population (1)\n• Selection must be made from a complete list for every member to have an equal chance (1)\n• Without one, some members could never be selected, so the sample would be biased (1)` },
      { q: 'Describe systematic sampling and state one disadvantage.', marks: 3, markScheme: `• Select every kth member from an ordered list, starting from a randomly chosen point (1)\n• It is simple and spreads the sample across the whole list (1)\n• It fails if the list has a repeating pattern matching the sampling interval (1)` },
      { q: 'Describe stratified sampling and state its main advantage.', marks: 3, markScheme: `• Divide the population into subgroups, or strata (1)\n• Sample each stratum in proportion to its size, selecting at random within each (1)\n• Every subgroup is represented in proportion to its size, so the sample is more representative (1)` },
      { q: 'A school has 480 students in Year 12 and 320 in Year 13. Describe how to take a stratified sample of 120 students.', marks: 4, markScheme: `• Total population is 800, so the sampling fraction is 120/800 = 0.15 (1)\n• Year 12: 480 × 0.15 = 72 students (1)\n• Year 13: 320 × 0.15 = 48 students (1)\n• Select the required number from each year group at random (1)` },
      { q: 'A school of 1200 students has 300 in Year 12. Find the number of Year 12 students in a stratified sample of 80.', marks: 3, markScheme: `• Sampling fraction is 80/1200 (1)\n• Year 12 contribution = 300 × 80/1200 (1)\n• = 20 students (1)` },
      { q: 'Explain the difference between quota sampling and stratified sampling.', marks: 3, markScheme: `• Both fix the number to be taken from each category (1)\n• Stratified sampling selects at random within each stratum (1)\n• Quota sampling does not, so the interviewer chooses whoever is convenient, which can introduce bias (1)` },
      { q: 'Describe cluster sampling and state one situation in which it would be preferred.', marks: 3, markScheme: `• Divide the population into groups, or clusters, and select whole clusters at random (1)\n• All members of the chosen clusters are surveyed (1)\n• It is preferred when the population is spread over a wide area and travel costs matter (1)` },
      { q: 'Describe opportunity sampling and explain its main weakness.', marks: 3, markScheme: `• Select whoever is conveniently available at the time (1)\n• It is quick and requires no sampling frame (1)\n• The sample is unlikely to be representative, since availability is related to other characteristics (1)` },
      { q: 'Describe a self-selected sample and explain why such samples are usually biased.', marks: 3, markScheme: `• Participants choose to take part rather than being selected (1)\n• People with strong opinions are more likely to volunteer (1)\n• The sample therefore over-represents strong views and under-represents the indifferent majority (1)` },
      { q: 'Identify the sampling method in each case: (a) every 10th name from an alphabetical register; (b) the first 30 people leaving a station; (c) 3 whole districts chosen from 20.', marks: 3, markScheme: `• (a) Systematic sampling (1)\n• (b) Opportunity sampling (1)\n• (c) Cluster sampling (1)` },
      { q: 'Define bias in the context of sampling.', marks: 2, markScheme: `• A sampling method is biased if it systematically favours certain outcomes or groups (1)\n• The resulting sample is therefore not representative, and estimates from it are systematically wrong (1)` },
      { q: 'A survey is conducted by telephoning numbers from a published directory. Identify the main source of bias and explain its effect.', marks: 3, markScheme: `• People without a listed landline cannot be selected at all (1)\n• This excludes, for example, mobile-only households and those who are ex-directory (1)\n• If those excluded differ systematically from those included, the estimate is biased (1)` },
      { q: 'Explain what is meant by non-response bias.', marks: 2, markScheme: `• Some selected people do not reply to the survey (1)\n• If non-responders differ systematically from responders, the achieved sample is biased even though the selection was random (1)` },
      { q: 'A supermarket surveys shoppers on a Tuesday morning to estimate the mean weekly spending of all customers. Identify two sources of bias and suggest one improvement.', marks: 5, markScheme: `• Only shoppers available on a weekday morning can be selected (1)\n• This under-represents people in full-time work, whose spending may differ (1)\n• Surveying at a single store, or non-response from those in a hurry, is a second source (1)\n• Explain that this distorts the estimate of the population mean (1)\n• Improvement: sample across several days, times of day and stores (1)` },
      { q: 'A factory samples every 12th item from a production line on which a fault recurs every 12th item. Explain the problem.', marks: 3, markScheme: `• The sampling interval matches the period of the fault (1)\n• The sample will therefore either always include a faulty item or never include one (1)\n• The estimated fault rate will be badly wrong in either case (1)` },
      { q: 'Explain why an online poll answered by readers who choose to respond may give a misleading result.', marks: 3, markScheme: `• The sample is self-selected (1)\n• Readers with strong views are far more likely to respond (1)\n• The result reflects the opinions of that subgroup rather than of the population (1)` },
      { q: 'Two researchers take independent random samples from the same population and obtain different sample means. Explain why neither is necessarily wrong.', marks: 3, markScheme: `• Different samples contain different individuals (1)\n• Sample statistics therefore vary from sample to sample, which is called sampling variability (1)\n• Both means are valid estimates of the same population mean; the difference does not indicate an error (1)` },
      { q: 'Explain the effect of increasing the sample size on the reliability of an estimate, and state what it does not fix.', marks: 3, markScheme: `• A larger sample reduces the variability of the estimate (1)\n• The standard deviation of the sample mean is σ/√n, which decreases as n increases (1)\n• It does not remove bias — a badly designed large sample is still biased (1)` },
      { q: 'By what factor is the standard deviation of the sample mean reduced if the sample size is quadrupled? Justify your answer.', marks: 2, markScheme: `• The standard deviation of the sample mean is σ/√n (1)\n• Quadrupling n multiplies √n by 2, so the standard deviation is halved (1)` },
      { q: 'Explain why a conclusion drawn from a sample applies to the population only with some uncertainty.', marks: 2, markScheme: `• The sample may not perfectly represent the population, by chance (1)\n• Conclusions are therefore inferences that carry a degree of uncertainty, not certainties (1)` },
      { q: 'Explain what is meant by making an inference about a population.', marks: 2, markScheme: `• Using data from a sample to draw a conclusion about the whole population (1)\n• For example, using the sample mean as an estimate of the population mean (1)` },
      { q: 'A researcher wishes to survey opinions across a large country with a limited travel budget. Recommend a sampling method and justify your choice.', marks: 3, markScheme: `• Cluster sampling is appropriate (1)\n• Whole regions can be surveyed without travelling to every part of the country (1)\n• This keeps costs down, although the clusters chosen may not fully represent the whole population (1)` },
      { q: 'Explain how random number generators are used in sampling and why they are preferred to informal choice.', marks: 3, markScheme: `• Each population member is numbered, and random numbers select which are included (1)\n• This ensures every member has an equal chance of selection (1)\n• Informal or haphazard choice introduces unconscious preferences, which is a source of bias (1)` },
      { q: 'Explain the purpose of issuing a large data set in advance of an examination.', marks: 3, markScheme: `• Students explore it during the course using a spreadsheet or statistical software (1)\n• They become familiar with the contexts, variables and typical values (1)\n• This allows questions to be set that would be too demanding in an unfamiliar context (1)` },
      { q: 'State what is and is not available to a student working with the large data set in the examination.', marks: 2, markScheme: `• A printout of the full data set is not provided (1)\n• Selected data or summary statistics from it may be given within the examination paper (1)` },
      { q: 'State the change to the large data set arrangements that applies from September 2026.', marks: 2, markScheme: `• Previously there was an assessment cycle using three large data sets in sequence (1)\n• From September 2026 all students on a two-year AS/A Level programme use a single large data set (1)` },
      { q: 'Explain why familiarity with the contexts of the large data set is more useful than memorising individual values.', marks: 3, markScheme: `• The examination provides any specific figures that are needed (1)\n• What cannot be provided is understanding of what the variables mean, their units and how they were collected (1)\n• That understanding is what allows sensible interpretation and judgement of plausibility (1)` },
      { q: 'Explain why an incomplete sampling frame is a serious problem even if the selection method is genuinely random.', marks: 2, markScheme: `• Members omitted from the frame have zero probability of selection (1)\n• Randomness within the frame cannot compensate for a group being excluded altogether, so the sample is biased (1)` },
      { q: 'A college has 480 in Year 12 and 320 in Year 13 and takes a stratified sample of 120. Explain why simply rounding each stratum independently can cause a problem.', marks: 3, markScheme: `• Each stratum size is calculated as a proportion, which may not be a whole number (1)\n• Rounding each independently can make the totals fail to add to the required sample size (1)\n• In this case the figures are exactly 72 and 48, so no rounding is needed and the totals agree (1)` },
      { q: 'Explain how you would evaluate whether a proposed sampling technique is suitable for a given statistical problem.', marks: 4, markScheme: `• Consider whether a complete sampling frame is available (1)\n• Consider the practical constraints of cost, time and access (1)\n• Identify any groups likely to be over- or under-represented (1)\n• Judge whether the resulting sample would be sufficiently representative for the purpose (1)` },
      { q: 'Explain why the sample variance can be used as an estimate of the population variance.', marks: 2, markScheme: `• The sample is drawn from the population, so its spread reflects the population spread (1)\n• Dividing by n − 1 rather than n makes the sample variance an unbiased estimator of the population variance (1)` },
      { q: 'Explain why the wording of a survey question can be a source of bias, giving an example.', marks: 3, markScheme: `• A leading question suggests a particular answer to the respondent (1)\n• Responses then reflect the wording rather than genuine opinion (1)\n• Example: "Do you agree that the unfair new charges should be scrapped?" pushes towards agreement (1)` },
      { q: 'A student claims that a self-selected sample is always worthless. Comment on this claim.', marks: 3, markScheme: `• The claim is too strong (1)\n• Such a sample is biased and cannot be used to estimate population proportions reliably (1)\n• It may still be informative about the range of views held, provided its limitations are clearly stated (1)` },
      { q: 'Summarise the main advantages and disadvantages of simple random sampling.', marks: 4, markScheme: `• Advantage: it is unbiased, since every sample of the required size is equally likely (1)\n• Advantage: it is straightforward to analyse statistically (1)\n• Disadvantage: it requires a complete sampling frame (1)\n• Disadvantage: it may be costly or impractical if the population is large or widely spread (1)` },
    ]
  },

  '2.2': {
    name: 'Data Presentation & Interpretation',
    questions: [
      { q: 'Classify each of the following as categorical, discrete, continuous or ranked: eye colour; number of cars; height; finishing position in a race.', marks: 4, markScheme: `• Eye colour is categorical (1)\n• Number of cars is discrete (1)\n• Height is continuous (1)\n• Finishing position is ranked (1)` },
      { q: 'State what the area of each bar in a histogram represents, and what the vertical axis shows.', marks: 2, markScheme: `• The area of each bar is proportional to the frequency (1)\n• The vertical axis shows frequency density, which is frequency divided by class width (1)` },
      { q: 'Explain the difference between a histogram and a frequency chart.', marks: 3, markScheme: `• A histogram may have unequal class widths, and area represents frequency (1)\n• Its vertical axis is frequency density (1)\n• A frequency chart has equal width bars with frequency itself on the vertical axis (1)` },
      { q: 'A histogram bar has width 5 and frequency density 3. Find the frequency it represents.', marks: 2, markScheme: `• Frequency = frequency density × class width (1)\n• Frequency = 3 × 5 = 15 (1)` },
      { q: 'A histogram class from 10 to 20 has frequency 40. Find its frequency density.', marks: 2, markScheme: `• Class width = 10 (1)\n• Frequency density = 40/10 = 4 (1)` },
      { q: 'Explain why a histogram rather than a bar chart must be used for grouped continuous data with unequal class widths.', marks: 3, markScheme: `• With unequal widths, bar heights alone would misrepresent the frequencies (1)\n• A histogram uses area to represent frequency, which compensates for the differing widths (1)\n• A bar chart is intended for categorical data with no notion of class width (1)` },
      { q: 'Two comparative pie charts represent data sets with totals 50 and 200. Find the ratio of their radii, justifying your answer.', marks: 3, markScheme: `• The areas are proportional to the frequencies (1)\n• Since area is proportional to r², the radii are proportional to the square roots of the frequencies (1)\n• Ratio = √50 : √200 = 1 : 2 (1)` },
      { q: 'Explain why comparative pie charts use area rather than radius proportional to frequency.', marks: 2, markScheme: `• The visual impression of a circle is governed by its area, not its radius (1)\n• Making the radius proportional would exaggerate the larger data set by a factor equal to the ratio squared (1)` },
      { q: 'Describe what a box-and-whisker diagram shows, and state one advantage over a histogram.', marks: 3, markScheme: `• It shows the median, the lower and upper quartiles and the extreme values (1)\n• The box spans the interquartile range (1)\n• It makes comparison between two or more distributions quick and direct (1)` },
      { q: 'Describe what a stem-and-leaf diagram shows and state one advantage and one requirement.', marks: 3, markScheme: `• It displays the distribution while retaining the original data values (1)\n• Advantage: the individual values can still be read off, unlike in a histogram (1)\n• Requirement: a key must be given so the stems and leaves can be interpreted (1)` },
      { q: 'Define the mean, median, mode and midrange.', marks: 4, markScheme: `• Mean is the sum of the values divided by how many there are (1)\n• Median is the middle value when the data are placed in order (1)\n• Mode is the most frequently occurring value (1)\n• Midrange is the average of the smallest and largest values (1)` },
      { q: 'Explain why the median is often preferred to the mean for skewed data.', marks: 3, markScheme: `• The mean is affected by every value, including extreme ones (1)\n• Skewed data contain extreme values in one tail, which pull the mean towards that tail (1)\n• The median depends only on position in the order, so it is resistant to those extremes (1)` },
      { q: 'Explain when a weighted mean is appropriate, and give an example.', marks: 3, markScheme: `• When combining groups of different sizes (1)\n• Each group mean is weighted by the size of that group (1)\n• Example: combining the mean incomes of two regions using their populations as weights (1)` },
      { q: 'Define the range and the interquartile range, and state one advantage of the interquartile range.', marks: 3, markScheme: `• Range is the largest value minus the smallest (1)\n• Interquartile range is Q₃ − Q₁ (1)\n• The interquartile range is unaffected by extreme values, since it uses only the middle half of the data (1)` },
      { q: 'Write down the formula for the sample variance in terms of Sxx and n, and explain the divisor used.', marks: 3, markScheme: `• s² = Sxx/(n − 1) (1)\n• Sxx is the sum of the squared deviations from the mean (1)\n• Dividing by n − 1 rather than n makes s² an unbiased estimator of the population variance (1)` },
      { q: 'A data set of 10 values has Σx = 200 and Sxx = 360. Find the mean and the sample standard deviation.', marks: 4, markScheme: `• Mean = 200/10 = 20 (1)\n• Sample variance = 360/9 (1)\n• = 40 (1)\n• Standard deviation = √40 ≈ 6.32 (1)` },
      { q: 'State the units of the mean, the variance and the standard deviation for a set of lengths measured in centimetres.', marks: 3, markScheme: `• Mean is in centimetres (1)\n• Variance is in square centimetres (1)\n• Standard deviation is in centimetres (1)` },
      { q: 'A data set has mean 50 and standard deviation 4. State the mean and standard deviation after adding 10 to every value, justifying your answers.', marks: 4, markScheme: `• New mean = 60 (1)\n• Adding a constant shifts every value equally, so the mean increases by that constant (1)\n• Standard deviation is unchanged at 4 (1)\n• The spread about the mean is unaffected by a translation (1)` },
      { q: 'A data set has mean 20 and standard deviation 3. State the mean and standard deviation after multiplying every value by 4.', marks: 3, markScheme: `• New mean = 80 (1)\n• New standard deviation = 12 (1)\n• Both are multiplied by the scale factor, since scaling stretches both position and spread (1)` },
      { q: 'State the two criteria given in the specification for identifying an outlier.', marks: 2, markScheme: `• A value at least 2 standard deviations from the mean (1)\n• A value at least 1.5 × IQR beyond the nearer quartile (1)` },
      { q: 'A data set has mean 50 and standard deviation 4. Using the 2-standard-deviation criterion, find the range of values that are not outliers.', marks: 3, markScheme: `• Two standard deviations is 8 (1)\n• Lower boundary 50 − 8 = 42 and upper boundary 50 + 8 = 58 (1)\n• Values between 42 and 58 inclusive are not outliers (1)` },
      { q: 'A data set has Q₁ = 20 and Q₃ = 32. Using the 1.5 × IQR criterion, find the outlier boundaries.', marks: 4, markScheme: `• IQR = 32 − 20 = 12 (1)\n• 1.5 × IQR = 18 (1)\n• Lower boundary = 20 − 18 = 2 (1)\n• Upper boundary = 32 + 18 = 50 (1)` },
      { q: 'Explain what is meant by an outlier, and why the two criteria may not always agree.', marks: 3, markScheme: `• An outlier is a value inconsistent with the rest of the data (1)\n• One criterion uses the mean and standard deviation, both affected by extreme values (1)\n• The other uses quartiles, which are resistant, so the two can classify a borderline value differently (1)` },
      { q: 'Describe what data cleaning involves.', marks: 3, markScheme: `• Dealing with missing data, for example by recording it as missing rather than as zero (1)\n• Correcting or removing clear errors, such as impossible values (1)\n• Deciding how to treat outliers, with the decision justified (1)` },
      { q: 'An adult height is recorded as 1750 cm. Explain how this value should be treated and why.', marks: 3, markScheme: `• The value is physically impossible for an adult (1)\n• It is almost certainly a data-entry error, probably 175.0 cm (1)\n• It should be corrected if the true value can be established, or removed with the reason stated (1)` },
      { q: 'Explain why removing a genuine outlier without justification is poor practice.', marks: 3, markScheme: `• A genuine extreme value is real information about the population (1)\n• Removing it distorts summary statistics and the conclusions drawn (1)\n• Any removal must be justified, for example by showing the value is impossible or was measured in error (1)` },
      { q: 'Describe what a scatter diagram shows and define correlation.', marks: 3, markScheme: `• A scatter diagram plots paired observations of two variables (1)\n• Correlation measures how closely the points lie to a straight line (1)\n• It may be positive, negative, or close to zero if there is no linear pattern (1)` },
      { q: 'Explain why correlation does not imply causation, giving an example.', marks: 3, markScheme: `• Two variables can be related through a third variable rather than by one causing the other (1)\n• Example: ice cream sales and drownings are positively correlated (1)\n• Both are driven by hot weather, so neither causes the other (1)` },
      { q: 'Explain the difference between interpolation and extrapolation, and state which is generally less reliable.', marks: 3, markScheme: `• Interpolation estimates a value within the range of the observed data (1)\n• Extrapolation estimates beyond that range (1)\n• Extrapolation is less reliable, since the relationship may not continue outside the observed range (1)` },
      { q: 'State what this specification requires with respect to regression lines, and what it excludes.', marks: 3, markScheme: `• Learners must interpret a given regression line or other best-fit model (1)\n• This includes judging the reliability of interpolation and extrapolation (1)\n• Calculating the equation of a regression line from data or summary statistics is excluded (1)` },
      { q: 'State what this specification requires with respect to correlation coefficients, and what it excludes.', marks: 3, markScheme: `• A correlation coefficient is given and used to make an inference about the population (1)\n• Learners are not required to know the names of particular coefficients (1)\n• Calculating a correlation coefficient is excluded (1)` },
      { q: 'Explain what a rank correlation coefficient measures and how it differs from an ordinary correlation coefficient.', marks: 2, markScheme: `• A rank correlation coefficient measures the correlation between the ranks of the data (1)\n• An ordinary correlation coefficient uses the actual data values rather than their ranks (1)` },
      { q: 'Explain what happens to a diagram representing an unbiased sample as the sample size increases.', marks: 3, markScheme: `• The diagram becomes more representative of the underlying theoretical distribution (1)\n• Random fluctuations become proportionally smaller (1)\n• For example, the proportion of heads in coin tosses moves steadily closer to 50% (1)` },
      { q: 'A box plot shows the median much closer to Q₁ than to Q₃. Describe the shape of the distribution.', marks: 2, markScheme: `• The upper half of the middle 50% is more spread out than the lower half (1)\n• The distribution has positive skew, with a longer tail towards higher values (1)` },
      { q: 'Explain how a cumulative frequency diagram is used to estimate the median and quartiles.', marks: 3, markScheme: `• Plot cumulative frequency against the upper class boundaries and join the points (1)\n• Read across from half the total frequency to find the median (1)\n• Read across from one quarter and three quarters of the total to find Q₁ and Q₃ (1)` },
      { q: 'State which diagram is most appropriate for each: (a) discrete numerical data; (b) proportions of a whole; (c) bivariate data.', marks: 3, markScheme: `• (a) A vertical line chart (1)\n• (b) A pie chart (1)\n• (c) A scatter diagram (1)` },
      { q: 'A data set contains one very large outlier. Describe its effect on the mean, the median and the range.', marks: 3, markScheme: `• The mean is pulled upwards, since it uses every value (1)\n• The median is largely unaffected, as it depends only on position in the order (1)\n• The range increases substantially, since it depends on the extreme values (1)` },
      { q: 'Explain why the mode is often the most appropriate average for categorical data.', marks: 2, markScheme: `• Categorical data have no numerical order, so a mean or median cannot be calculated (1)\n• The mode identifies the most common category, which is the only meaningful average available (1)` },
      { q: 'Describe a dot plot and state when it is most useful.', marks: 2, markScheme: `• A dot plot represents frequency by stacks of dots, similar to a bar chart (1)\n• It is most useful for small data sets, where individual values remain visible (1)` },
      { q: 'A scatter diagram shows a strong negative correlation. Describe what this means about the two variables and comment on what it does not establish.', marks: 3, markScheme: `• As one variable increases the other tends to decrease (1)\n• The points lie close to a straight line with negative gradient (1)\n• It does not establish that one variable causes the change in the other (1)` },
    ]
  },

  '2.3': {
    name: 'Probability',
    questions: [
      { q: 'State how the probability of an event is calculated when all outcomes are equally likely, and state the range of possible probabilities.', marks: 2, markScheme: `• Probability = number of favourable outcomes divided by total number of outcomes (1)\n• Every probability lies between 0 and 1 inclusive (1)` },
      { q: 'Explain what is meant by a complementary event and write down the relationship between P(A) and P(A′).', marks: 2, markScheme: `• A′ is the event that A does not occur (1)\n• P(A′) = 1 − P(A) (1)` },
      { q: 'A fair die is rolled twice. Find the probability of at least one six, explaining why the complement is the easier route.', marks: 4, markScheme: `• Listing all the favourable cases directly is lengthy (1)\n• P(no sixes) = (5/6)² = 25/36 (1)\n• P(at least one six) = 1 − 25/36 (1)\n• = 11/36 (1)` },
      { q: 'An event has probability 0.15. Find the expected frequency of the event in 200 trials.', marks: 2, markScheme: `• Expected frequency = nP(A) (1)\n• = 200 × 0.15 = 30 (1)` },
      { q: 'Explain the meanings of the notations A ∩ B, A ∪ B and P(A | B).', marks: 3, markScheme: `• A ∩ B means both A and B occur (1)\n• A ∪ B means A or B or both occur (1)\n• P(A | B) is the probability of A given that B has occurred (1)` },
      { q: 'Define mutually exclusive events and write down the addition rule for them.', marks: 2, markScheme: `• Two events are mutually exclusive if they cannot both occur, so P(A ∩ B) = 0 (1)\n• P(A ∪ B) = P(A) + P(B) (1)` },
      { q: 'Define independent events and write down the multiplication rule for them.', marks: 2, markScheme: `• Two events are independent if the occurrence of one does not affect the probability of the other (1)\n• P(A ∩ B) = P(A) × P(B) (1)` },
      { q: 'Explain why two mutually exclusive events with non-zero probabilities cannot be independent.', marks: 3, markScheme: `• If they are mutually exclusive then P(A ∩ B) = 0 (1)\n• If they were independent then P(A ∩ B) = P(A)P(B), which is non-zero (1)\n• These cannot both hold, so mutually exclusive events with non-zero probabilities are dependent (1)` },
      { q: 'Write down the general addition rule for any two events and explain why the final term is subtracted.', marks: 3, markScheme: `• P(A ∪ B) = P(A) + P(B) − P(A ∩ B) (1)\n• Adding P(A) and P(B) counts the overlap twice (1)\n• Subtracting P(A ∩ B) corrects for that double counting (1)` },
      { q: 'Given P(A) = 0.4, P(B) = 0.5 and P(A ∩ B) = 0.2, find P(A ∪ B).', marks: 2, markScheme: `• P(A ∪ B) = 0.4 + 0.5 − 0.2 (1)\n• = 0.7 (1)` },
      { q: 'Given that A and B are independent with P(A) = 0.4 and P(B) = 0.5, find P(A ∩ B) and P(A ∪ B).', marks: 3, markScheme: `• P(A ∩ B) = 0.4 × 0.5 = 0.2 (1)\n• P(A ∪ B) = 0.4 + 0.5 − 0.2 (1)\n• = 0.7 (1)` },
      { q: 'A card is drawn at random from a standard pack of 52. Find the probability that it is a king or a heart.', marks: 4, markScheme: `• P(king) = 4/52 and P(heart) = 13/52 (1)\n• The king of hearts belongs to both, so P(king ∩ heart) = 1/52 (1)\n• P(king ∪ heart) = 4/52 + 13/52 − 1/52 (1)\n• = 16/52 = 4/13 (1)` },
      { q: 'Two fair dice are rolled. Find the probability that the total is 7.', marks: 3, markScheme: `• There are 36 equally likely outcomes (1)\n• Six give a total of 7: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1) (1)\n• Probability = 6/36 = 1/6 (1)` },
      { q: 'Write down the formula for conditional probability and rearrange it to give the multiplication rule.', marks: 2, markScheme: `• P(A | B) = P(A ∩ B)/P(B) (1)\n• Rearranging gives P(A ∩ B) = P(B) × P(A | B) (1)` },
      { q: 'Given P(A) = 0.6 and P(B | A) = 0.5, find P(A ∩ B).', marks: 2, markScheme: `• P(A ∩ B) = P(A) × P(B | A) (1)\n• = 0.6 × 0.5 = 0.3 (1)` },
      { q: 'Given P(A) = 0.5, P(B) = 0.4 and P(A ∪ B) = 0.7, find P(A | B).', marks: 4, markScheme: `• Use the addition rule to find P(A ∩ B) (1)\n• P(A ∩ B) = 0.5 + 0.4 − 0.7 = 0.2 (1)\n• P(A | B) = P(A ∩ B)/P(B) = 0.2/0.4 (1)\n• = 0.5 (1)` },
      { q: 'State the condition, in terms of conditional probability, for two events to be independent.', marks: 2, markScheme: `• A and B are independent if and only if P(A | B) = P(A) (1)\n• That is, knowing B has occurred does not change the probability of A (1)` },
      { q: 'A bag contains 4 red and 6 blue balls. Two are drawn without replacement. Find the probability that both are red.', marks: 3, markScheme: `• P(first red) = 4/10 (1)\n• P(second red given first red) = 3/9 (1)\n• P(both red) = (4/10)(3/9) = 2/15 (1)` },
      { q: 'A bag contains 5 red and 3 blue balls. Two are drawn without replacement. Find the probability that exactly one is red.', marks: 4, markScheme: `• Two orders are possible, red then blue and blue then red (1)\n• P(red then blue) = (5/8)(3/7) = 15/56 (1)\n• P(blue then red) = (3/8)(5/7) = 15/56 (1)\n• Total = 30/56 = 15/28 (1)` },
      { q: 'Explain the difference between drawing with replacement and without replacement, and its effect on independence.', marks: 3, markScheme: `• With replacement, the item is returned so the composition is unchanged (1)\n• The draws are then independent, with the same probabilities each time (1)\n• Without replacement, the composition changes, so the draws are dependent and conditional probabilities are needed (1)` },
      { q: 'Two cards are drawn with replacement from a standard pack. Find the probability that both are hearts.', marks: 3, markScheme: `• P(heart) = 13/52 = 1/4 each time (1)\n• The draws are independent because of replacement (1)\n• P(both hearts) = (1/4)² = 1/16 (1)` },
      { q: 'A fair coin is tossed three times. Find the probability of exactly two heads.', marks: 3, markScheme: `• There are 8 equally likely outcomes (1)\n• Three give exactly two heads: HHT, HTH, THH (1)\n• Probability = 3/8 (1)` },
      { q: 'Three fair coins are tossed. Given that at least one head appears, find the probability that all three are heads.', marks: 4, markScheme: `• P(all three heads) = 1/8 (1)\n• P(at least one head) = 1 − P(no heads) = 1 − 1/8 = 7/8 (1)\n• Apply the conditional probability formula (1)\n• P = (1/8)/(7/8) = 1/7 (1)` },
      { q: 'Describe how a tree diagram is used to calculate probabilities, and state the check that the branches must satisfy.', marks: 3, markScheme: `• Multiply the probabilities along a path to find the probability of that sequence (1)\n• Add the probabilities of all paths giving the required outcome (1)\n• The probabilities on the branches from any single node must sum to 1 (1)` },
      { q: 'Explain how a Venn diagram helps in probability calculations, and state the limit on the number of events in this specification.', marks: 3, markScheme: `• It shows how events overlap, so intersections and unions can be read off directly (1)\n• Filling in the intersection first avoids double counting (1)\n• This specification uses Venn diagrams for up to three events (1)` },
      { q: 'A machine has three independent components, each working with probability 0.9. Find the probability that all three work and the probability that at least one fails.', marks: 4, markScheme: `• The components are independent, so multiply the probabilities (1)\n• P(all work) = 0.9³ (1)\n• = 0.729 (1)\n• P(at least one fails) = 1 − 0.729 = 0.271 (1)` },
      { q: 'A screening test is 95% accurate in both directions, and 1% of a population has the condition. Find the probability that someone who tests positive actually has the condition.', marks: 6, markScheme: `• P(has condition and tests positive) = 0.01 × 0.95 (1)\n• = 0.0095 (1)\n• P(no condition and tests positive) = 0.99 × 0.05 (1)\n• = 0.0495 (1)\n• P(tests positive) = 0.0095 + 0.0495 = 0.059 (1)\n• P(condition | positive) = 0.0095/0.059 ≈ 0.161 (1)` },
      { q: 'Comment on the result of the previous question, explaining why the answer is so much lower than the accuracy of the test.', marks: 3, markScheme: `• The condition is rare, so very few people actually have it (1)\n• The 5% false positive rate applies to the large healthy majority, producing many false positives (1)\n• These outnumber the true positives, so most positive results are false (1)` },
      { q: 'Explain what is meant by reverse conditional probability and describe how such a problem is tackled.', marks: 3, markScheme: `• It means finding P(A | B) when P(B | A) is given (1)\n• The two are not equal and cannot be interchanged (1)\n• Build a tree diagram or table, find P(A ∩ B) and P(B), then apply the conditional probability formula (1)` },
      { q: 'A two-way table gives the numbers of students taking Mathematics and Physics. Explain how a conditional probability is read from such a table.', marks: 3, markScheme: `• Identify the row or column corresponding to the given condition (1)\n• That row or column becomes the restricted sample space (1)\n• Divide the relevant cell by the total of that row or column (1)` },
      { q: 'Explain the difference between P(A | B) and P(B | A), using a real-world example.', marks: 3, markScheme: `• P(A | B) restricts attention to cases where B occurred, and P(B | A) to cases where A occurred (1)\n• The denominators are different, so the values usually differ (1)\n• Example: the probability of a positive test given the disease is high, but the probability of the disease given a positive test may be low if the disease is rare (1)` },
      { q: 'A box contains 3 faulty and 7 working items. Two are chosen at random without replacement. Find the probability that at least one is faulty.', marks: 4, markScheme: `• Use the complement: P(neither faulty) (1)\n• = (7/10)(6/9) (1)\n• = 42/90 = 7/15 (1)\n• P(at least one faulty) = 1 − 7/15 = 8/15 (1)` },
      { q: 'Given that A and B are independent, explain why A′ and B are also independent.', marks: 3, markScheme: `• P(A′ ∩ B) = P(B) − P(A ∩ B) (1)\n• = P(B) − P(A)P(B) using independence (1)\n• = P(B)(1 − P(A)) = P(B)P(A′), which is the condition for independence (1)` },
      { q: 'For mutually exclusive events A and B with P(A) = 0.3 and P(B) = 0.5, find P(A | B) and explain the result.', marks: 3, markScheme: `• P(A ∩ B) = 0 for mutually exclusive events (1)\n• P(A | B) = 0/0.5 = 0 (1)\n• If B has occurred then A cannot have occurred, so the probability is zero (1)` },
      { q: 'A student argues that because two events cannot happen at the same time they must be independent. Explain the error.', marks: 3, markScheme: `• Mutual exclusivity and independence are different concepts (1)\n• If the events cannot both occur, knowing one occurred tells you the other did not (1)\n• That is a very strong dependence, so the two are in fact incompatible for non-zero probabilities (1)` },
      { q: 'A fair die is rolled. Events A and B are defined as "the score is even" and "the score is greater than 4". Determine whether A and B are independent.', marks: 5, markScheme: `• P(A) = 3/6 = 1/2 (1)\n• P(B) = 2/6 = 1/3 (1)\n• A ∩ B is the score 6, so P(A ∩ B) = 1/6 (1)\n• P(A)P(B) = (1/2)(1/3) = 1/6 (1)\n• Since P(A ∩ B) = P(A)P(B), the events are independent (1)` },
      { q: 'Explain what a sample space diagram shows and when it is most useful.', marks: 2, markScheme: `• It lists or displays all the equally likely outcomes of an experiment (1)\n• It is most useful for two-stage experiments with a small number of outcomes, such as rolling two dice (1)` },
      { q: 'A spinner has outcomes with probabilities 0.2, 0.3, x and 0.1. Find x, justifying your method.', marks: 2, markScheme: `• The probabilities of all outcomes must sum to 1 (1)\n• x = 1 − (0.2 + 0.3 + 0.1) = 0.4 (1)` },
      { q: 'Explain why probabilities of events from a tree diagram must be multiplied along branches but added between paths.', marks: 3, markScheme: `• Moving along a path represents a sequence of events all occurring, which corresponds to an intersection (1)\n• Intersections of successive events are found by multiplying, using conditional probabilities where needed (1)\n• Separate paths represent mutually exclusive ways of achieving the outcome, so their probabilities are added (1)` },
      { q: 'Two events A and B satisfy P(A) = 0.7, P(B) = 0.4 and P(A ∪ B) = 0.9. Determine whether A and B are independent.', marks: 5, markScheme: `• P(A ∩ B) = P(A) + P(B) − P(A ∪ B) (1)\n• = 0.7 + 0.4 − 0.9 = 0.2 (1)\n• P(A)P(B) = 0.7 × 0.4 (1)\n• = 0.28 (1)\n• Since 0.2 ≠ 0.28, the events are not independent (1)` },
    ]
  },

  '2.4': {
    name: 'Probability Distributions',
    questions: [
      { q: 'Explain what is meant by a discrete random variable, and state the notation used for the variable and for a particular value.', marks: 3, markScheme: `• A discrete random variable takes separate values, each with a given probability (1)\n• A capital letter such as X denotes the variable (1)\n• A lower-case letter such as x or r denotes a particular value it takes (1)` },
      { q: 'State the condition that the probabilities of a discrete probability distribution must satisfy.', marks: 2, markScheme: `• Every probability must be non-negative (1)\n• The probabilities of all possible values must sum to 1 (1)` },
      { q: 'The random variable X has P(X = x) = kx for x = 1, 2, 3, 4. Find the value of k.', marks: 3, markScheme: `• The probabilities must sum to 1 (1)\n• k(1 + 2 + 3 + 4) = 10k = 1 (1)\n• k = 0.1 (1)` },
      { q: 'Explain what is meant by a discrete uniform distribution, giving an example.', marks: 2, markScheme: `• All the possible outcomes are equally likely (1)\n• Example: the score on a fair six-sided die, where each value has probability 1/6 (1)` },
      { q: 'State the four conditions required for a situation to be modelled by a binomial distribution.', marks: 4, markScheme: `• A fixed number of trials (1)\n• Exactly two outcomes per trial, success and failure (1)\n• The probability of success is the same each trial (1)\n• The trials are independent of one another (1)` },
      { q: 'Explain the meaning of the notation X ~ B(n, p), including the symbol ~.', marks: 3, markScheme: `• The symbol ~ is read "has the distribution" (1)\n• B denotes the binomial distribution (1)\n• n is the number of trials and p the probability of success on each trial (1)` },
      { q: 'For X ~ B(10, 0.4), calculate P(X = 3), giving your answer to 3 significant figures.', marks: 4, markScheme: `• Use P(X = r) = ⁿCᵣ pʳ q^(n−r) (1)\n• P(X = 3) = ¹⁰C₃(0.4)³(0.6)⁷ (1)\n• ¹⁰C₃ = 120 (1)\n• P(X = 3) ≈ 0.215 (1)` },
      { q: 'For X ~ B(8, 0.5), write down P(X = 0) in exact form.', marks: 2, markScheme: `• P(X = 0) = ⁸C₀(0.5)⁰(0.5)⁸ (1)\n• = (0.5)⁸ = 1/256 (1)` },
      { q: 'For X ~ B(5, 0.2), find P(X ≥ 1), explaining why the complement is used.', marks: 3, markScheme: `• Calculating P(X = 1) + P(X = 2) + … is lengthy (1)\n• P(X ≥ 1) = 1 − P(X = 0) = 1 − 0.8⁵ (1)\n• ≈ 0.672 (1)` },
      { q: 'Write down the formula for the mean of a binomial distribution and use it for X ~ B(20, 0.3).', marks: 2, markScheme: `• Mean = np (1)\n• Mean = 20 × 0.3 = 6 (1)` },
      { q: 'In 50 trials with probability of success 0.2, find the expected number of successes.', marks: 2, markScheme: `• Expected frequency = np (1)\n• = 50 × 0.2 = 10 (1)` },
      { q: 'Explain why the number of heads in 20 tosses of a fair coin can be modelled by a binomial distribution, referring to each condition.', marks: 4, markScheme: `• There is a fixed number of trials, 20 (1)\n• Each toss has exactly two outcomes, heads or tails (1)\n• The probability of heads is 0.5 each time (1)\n• The tosses are independent, so B(20, 0.5) is appropriate (1)` },
      { q: 'Explain why a binomial model is not exactly appropriate for drawing balls from a small bag without replacement.', marks: 3, markScheme: `• The composition of the bag changes after each draw (1)\n• So the probability of success is not the same each time and the trials are not independent (1)\n• Two of the binomial conditions therefore fail (1)` },
      { q: 'Explain when a binomial model can still be used as a good approximation for sampling without replacement.', marks: 2, markScheme: `• When the population is very large compared with the sample size (1)\n• The probability of success then changes only negligibly between draws (1)` },
      { q: 'Write down a suitable distribution for the number of sixes in 30 rolls of a fair die, and state its mean.', marks: 3, markScheme: `• X ~ B(30, 1/6) (1)\n• Mean = np = 30 × 1/6 (1)\n• Mean = 5 (1)` },
      { q: 'Explain the meaning of the notation X ~ N(μ, σ²), stating carefully what the second parameter represents.', marks: 3, markScheme: `• N denotes the Normal distribution (1)\n• μ is the mean (1)\n• σ² is the variance, so the standard deviation is σ, its square root (1)` },
      { q: 'For X ~ N(100, 25), write down the standard deviation, and explain the common error made here.', marks: 2, markScheme: `• Standard deviation = √25 = 5 (1)\n• The common error is to read 25 as the standard deviation, when it is the variance (1)` },
      { q: 'Describe four properties of the Normal distribution curve.', marks: 4, markScheme: `• It is symmetric about the mean (1)\n• The mean, median and mode are all equal (1)\n• The total area under the curve is 1, and area represents probability (1)\n• The points of inflection lie at μ ± σ (1)` },
      { q: 'State the approximate proportions of a Normal distribution lying within one and within two standard deviations of the mean.', marks: 2, markScheme: `• About 68% lie within one standard deviation (1)\n• About 95% lie within two standard deviations (1)` },
      { q: 'Explain why the points of inflection of a Normal curve are useful in practice.', marks: 2, markScheme: `• They lie exactly one standard deviation either side of the mean (1)\n• Locating them on a sketch gives a direct visual estimate of the standard deviation (1)` },
      { q: 'Write down the formula for standardising a Normal variable and state the distribution of the standardised variable.', marks: 2, markScheme: `• Z = (X − μ)/σ (1)\n• Z has the standard Normal distribution N(0, 1) (1)` },
      { q: 'For X ~ N(60, 16), find the z-value corresponding to X = 68.', marks: 3, markScheme: `• Standard deviation = √16 = 4 (1)\n• z = (68 − 60)/4 (1)\n• z = 2 (1)` },
      { q: 'For X ~ N(80, 25), find the value of X corresponding to z = −1.6.', marks: 3, markScheme: `• X = μ + zσ (1)\n• = 80 + (−1.6)(5) (1)\n• X = 72 (1)` },
      { q: 'Explain the purpose of standardising a Normal variable.', marks: 2, markScheme: `• It converts any Normal distribution to the standard Normal N(0, 1) (1)\n• A single set of tables or calculator functions can then be used for every Normal distribution (1)` },
      { q: 'For X ~ N(μ, σ²) and Y = aX + b, write down the mean and variance of Y.', marks: 3, markScheme: `• Y is also Normally distributed (1)\n• Mean of Y = aμ + b (1)\n• Variance of Y = a²σ² (1)` },
      { q: 'X ~ N(50, 16) and Y = 3X + 2. State the distribution of Y, showing your working.', marks: 4, markScheme: `• A linear transformation of a Normal variable is Normal (1)\n• Mean = 3 × 50 + 2 = 152 (1)\n• Variance = 3² × 16 = 144 (1)\n• Y ~ N(152, 144) (1)` },
      { q: 'Explain why the additive constant b affects the mean but not the variance in a linear transformation.', marks: 2, markScheme: `• Adding a constant shifts every value by the same amount, moving the mean (1)\n• The spread about the mean is unchanged by a translation, so the variance is unaffected (1)` },
      { q: 'Explain what a continuity correction is and why it is needed.', marks: 3, markScheme: `• It is an adjustment of half a unit made when a continuous distribution models discrete data (1)\n• Each integer is treated as covering the interval half a unit either side of it (1)\n• Without it the probability of the boundary values would be misallocated (1)` },
      { q: 'Using a Normal approximation, write down the corrected form of each of the following: P(X ≤ 10); P(X < 10); P(X ≥ 12); P(X = 12).', marks: 4, markScheme: `• P(X ≤ 10) becomes P(X < 10.5) (1)\n• P(X < 10) becomes P(X < 9.5) (1)\n• P(X ≥ 12) becomes P(X > 11.5) (1)\n• P(X = 12) becomes P(11.5 < X < 12.5) (1)` },
      { q: 'Explain how to decide the direction of a continuity correction.', marks: 2, markScheme: `• Identify which integers the original statement should include (1)\n• Place the boundary half a unit outside the smallest or largest of those integers, so that they all fall within the interval (1)` },
      { q: 'X ~ B(20, 0.5) is approximated by a Normal distribution. Write down the continuity-corrected form of P(X ≥ 12).', marks: 2, markScheme: `• The value 12 must be included (1)\n• P(X ≥ 12) becomes P(X > 11.5) (1)` },
      { q: 'Explain how you can tell from the shape of a binomial distribution whether a Normal approximation is reasonable.', marks: 3, markScheme: `• Sketch or consider the shape of the binomial probability histogram (1)\n• If it is roughly symmetric and bell-shaped, a Normal approximation is reasonable (1)\n• If it is markedly skewed, for instance when p is close to 0 or 1 with small n, the approximation is poor (1)` },
      { q: 'State one situation in which a Normal model would be inappropriate for a set of data, with a reason.', marks: 2, markScheme: `• Data that are markedly skewed (1)\n• The Normal distribution is symmetric, so it cannot represent a distribution with a long tail on one side (1)` },
      { q: 'For X ~ N(μ, σ²), write down P(X > μ) and justify your answer.', marks: 2, markScheme: `• P(X > μ) = 0.5 (1)\n• The distribution is symmetric about the mean, so exactly half the area lies on each side (1)` },
      { q: 'Explain what happens to a histogram of samples drawn from a Normal population as the sample size increases.', marks: 2, markScheme: `• The histogram becomes an increasingly close match to the Normal curve (1)\n• Random fluctuations become proportionally smaller as more data are collected (1)` },
      { q: 'Explain what is meant by critiquing a probability model.', marks: 3, markScheme: `• Examining whether the assumptions of the model hold in the given context (1)\n• Identifying any condition that is doubtful and explaining why it matters (1)\n• Judging whether the model is nevertheless a reasonable approximation for the purpose (1)` },
      { q: 'For X ~ N(0, 1), express P(Z < −1.2) in terms of P(Z < 1.2), justifying your answer.', marks: 3, markScheme: `• The standard Normal distribution is symmetric about 0 (1)\n• So P(Z < −1.2) = P(Z > 1.2) (1)\n• = 1 − P(Z < 1.2) (1)` },
      { q: 'For X ~ B(n, p), state the effect on the mean of doubling n while keeping p fixed.', marks: 2, markScheme: `• The mean is np (1)\n• Doubling n doubles the mean to 2np (1)` },
      { q: 'The number of defective items in a large batch is modelled by a binomial distribution although sampling is without replacement. Discuss whether this is acceptable.', marks: 4, markScheme: `• Strictly the binomial conditions fail, since p changes between draws (1)\n• However, if the batch is very large relative to the sample, the change is negligible (1)\n• The binomial is then a good approximation (1)\n• The assumption should be stated explicitly when the model is used (1)` },
      { q: 'A student writes X ~ N(100, 8) meaning a mean of 100 and a standard deviation of 8. Explain the error and write the distribution correctly.', marks: 3, markScheme: `• The second parameter in the notation is the variance, not the standard deviation (1)\n• A standard deviation of 8 gives a variance of 64 (1)\n• The correct notation is X ~ N(100, 64) (1)` },
    ]
  },

  '2.5': {
    name: 'Statistical Hypothesis Testing',
    questions: [
      { q: 'Define the null hypothesis and the alternative hypothesis.', marks: 2, markScheme: `• The null hypothesis H₀ is the default assumption being tested, always stated as an equality (1)\n• The alternative hypothesis H₁ is what is concluded if H₀ is rejected (1)` },
      { q: 'Explain why hypotheses must be stated in terms of a population parameter rather than a sample statistic.', marks: 2, markScheme: `• The test uses the sample to make an inference about the population (1)\n• The sample statistic is known once the data are collected, so there would be nothing to test; the unknown quantity is the population parameter (1)` },
      { q: 'Define the significance level of a hypothesis test.', marks: 2, markScheme: `• It is the probability of incorrectly rejecting the null hypothesis when it is in fact true (1)\n• It sets the size of the critical region, for example at most 0.05 for a 5% test (1)` },
      { q: 'Define the critical region, the acceptance region and the critical value.', marks: 3, markScheme: `• The critical region, also called the rejection region, contains the values of the test statistic that lead to rejecting H₀ (1)\n• The acceptance region contains those for which H₀ is not rejected (1)\n• The critical value is the boundary between the two (1)` },
      { q: 'Define the p-value and state how it is used to reach a conclusion.', marks: 3, markScheme: `• The p-value is the probability of a result at least as extreme as the one observed, assuming H₀ is true (1)\n• If the p-value is less than the significance level, reject H₀ (1)\n• If it is greater, there is insufficient evidence to reject H₀ (1)` },
      { q: 'Explain when a one-tailed test should be used and when a two-tailed test should be used.', marks: 3, markScheme: `• A one-tailed test is used when the alternative hypothesis specifies a direction of change (1)\n• A two-tailed test is used when a change in either direction is of interest (1)\n• The wording of the question determines which, according to whether a direction is stated (1)` },
      { q: 'A coin is suspected of being biased towards heads. Write down suitable hypotheses and state whether the test is one- or two-tailed.', marks: 3, markScheme: `• H₀: p = 0.5 (1)\n• H₁: p > 0.5 (1)\n• One-tailed, since a direction of bias is specified (1)` },
      { q: 'A coin is suspected of being biased, with no direction stated. Write down suitable hypotheses and explain the type of test.', marks: 3, markScheme: `• H₀: p = 0.5 (1)\n• H₁: p ≠ 0.5 (1)\n• Two-tailed, since a change in either direction would be of interest (1)` },
      { q: 'For a two-tailed test at the 5% level, state the probability associated with each tail and explain why.', marks: 2, markScheme: `• Each tail carries a probability of 0.025 (1)\n• The total significance level is split equally between the two tails (1)` },
      { q: 'Set out the six steps of carrying out a hypothesis test.', marks: 6, markScheme: `• State H₀ and H₁ in terms of a population parameter (1)\n• Assume H₀ is true (1)\n• Calculate the probability of the observed result or something more extreme under that assumption (1)\n• Compare with the significance level, or compare the test statistic with the critical value (1)\n• Decide whether to reject H₀ or not (1)\n• State the conclusion in the context of the original problem (1)` },
      { q: 'Explain why you should not write "accept H₀" when a test does not lead to rejection.', marks: 3, markScheme: `• Failing to reject H₀ does not prove it is true (1)\n• It shows only that the evidence was not strong enough to reject it (1)\n• The correct phrasing is that there is insufficient evidence to reject H₀ (1)` },
      { q: 'Explain why rejecting H₀ gives evidence rather than proof.', marks: 2, markScheme: `• The result observed is unlikely under H₀, but not impossible (1)\n• A rare event may still occur by chance, so the conclusion carries a stated probability of error (1)` },
      { q: 'In a test at the 5% level the p-value is 0.032. State and justify the conclusion.', marks: 2, markScheme: `• 0.032 is less than 0.05 (1)\n• Reject H₀; there is evidence at the 5% level to support the alternative hypothesis, stated in context (1)` },
      { q: 'In a test at the 5% level the p-value is 0.08. State and justify the conclusion.', marks: 2, markScheme: `• 0.08 is greater than 0.05 (1)\n• There is insufficient evidence at the 5% level to reject H₀ (1)` },
      { q: 'A result is significant at the 5% level but not at the 1% level. State what this tells you about the p-value.', marks: 2, markScheme: `• The p-value is less than 0.05 but not less than 0.01 (1)\n• So it lies between 0.01 and 0.05 (1)` },
      { q: 'Explain the effect of lowering the significance level from 5% to 1%.', marks: 3, markScheme: `• The critical region becomes smaller (1)\n• Stronger evidence is therefore required before H₀ is rejected (1)\n• The chance of wrongly rejecting a true H₀ falls, but genuine effects become harder to detect (1)` },
      { q: 'Explain why the significance level must be chosen before the data are examined.', marks: 2, markScheme: `• Choosing it afterwards allows the level to be selected so as to obtain the desired conclusion (1)\n• The test would then no longer control the probability of a false rejection, so it would be invalid (1)` },
      { q: 'For a binomial hypothesis test, state the form of the null hypothesis and identify the test statistic.', marks: 2, markScheme: `• H₀ takes the form p equals a particular value, where p is a probability for the whole population (1)\n• The test statistic is the observed number of successes (1)` },
      { q: 'Explain why, for a binomial test, the probability of the test statistic falling in the rejection region is usually less than the intended significance level.', marks: 3, markScheme: `• The binomial distribution is discrete, so probabilities accumulate in jumps (1)\n• The critical region must be chosen so that its total probability does not exceed the significance level (1)\n• The actual probability is therefore usually strictly less than the intended level (1)` },
      { q: 'A coin is tossed 20 times and 15 heads are obtained. Set up a test at the 5% level of the claim that the coin is biased towards heads, stating the hypotheses and the test statistic.', marks: 4, markScheme: `• H₀: p = 0.5 (1)\n• H₁: p > 0.5, giving a one-tailed test (1)\n• Test statistic is X, the number of heads, with X ~ B(20, 0.5) under H₀ (1)\n• Calculate P(X ≥ 15) and compare with 0.05 (1)` },
      { q: 'Explain how a critical region is identified for a binomial test at a given significance level.', marks: 3, markScheme: `• Calculate cumulative binomial probabilities from the appropriate tail (1)\n• Find the largest region whose total probability does not exceed the significance level (1)\n• The values in that region form the critical region (1)` },
      { q: 'State the distribution of the sample mean for random samples of size n drawn from N(μ, σ²).', marks: 2, markScheme: `• The sample mean is Normally distributed (1)\n• It has mean μ and variance σ²/n, so its standard deviation is σ/√n (1)` },
      { q: 'For X ~ N(100, 36) and samples of size 9, find the standard deviation of the sample mean.', marks: 3, markScheme: `• Variance of the sample mean = 36/9 (1)\n• = 4 (1)\n• Standard deviation = 2 (1)` },
      { q: 'Explain what the Central Limit Theorem states and why it is useful.', marks: 3, markScheme: `• For a large sample, the sample mean is approximately Normally distributed (1)\n• This holds even when the population itself is not Normal (1)\n• It therefore allows a Normal test on a mean in a wide range of practical situations (1)` },
      { q: 'State the conditions under which a hypothesis test for a single mean using the Normal distribution is valid.', marks: 2, markScheme: `• The population variance is known (1)\n• Or the population variance is unknown but the sample size is large (1)` },
      { q: 'Explain why a Normal test on a mean would not be valid with a sample of size 8 and unknown population variance.', marks: 2, markScheme: `• The population variance is not known, so the first condition fails (1)\n• The sample is small, so the second condition fails as well, and neither route to validity is available (1)` },
      { q: 'A random sample of 25 is drawn from N(μ, 100). Test H₀: μ = 40 against H₁: μ > 40 at the 5% level, given a sample mean of 44.', marks: 6, markScheme: `• Under H₀ the sample mean is Normal with mean 40 (1)\n• Variance = 100/25 = 4, so the standard deviation is 2 (1)\n• Test statistic z = (44 − 40)/2 (1)\n• z = 2 (1)\n• The one-tailed 5% critical value is 1.645, and 2 > 1.645 (1)\n• Reject H₀; there is evidence at the 5% level that the population mean exceeds 40 (1)` },
      { q: 'Write down the formula for the test statistic used in a Normal test on a population mean, defining each symbol.', marks: 3, markScheme: `• z = (x̄ − μ)/(σ/√n) (1)\n• x̄ is the sample mean and μ the population mean under H₀ (1)\n• σ is the population standard deviation and n the sample size (1)` },
      { q: 'Explain a common error in which candidates divide by σ instead of σ/√n, and its effect.', marks: 3, markScheme: `• The test concerns the sample mean, not an individual observation (1)\n• The sample mean has standard deviation σ/√n, which is smaller than σ (1)\n• Dividing by σ gives a test statistic that is too small, so genuine effects are missed (1)` },
      { q: 'In a test of H₀: μ = 50 against H₁: μ > 50, the sample mean is 47. Explain what conclusion can be drawn without calculation.', marks: 2, markScheme: `• The sample mean is below the hypothesised value, in the opposite direction to H₁ (1)\n• There is therefore no evidence at all in support of H₁, so H₀ is not rejected (1)` },
      { q: 'Explain the effect of increasing the sample size in a test for a mean, with everything else unchanged.', marks: 3, markScheme: `• The standard deviation of the sample mean, σ/√n, decreases (1)\n• The test statistic for a given difference therefore becomes larger (1)\n• Real differences become easier to detect, so the test is more powerful (1)` },
      { q: 'Explain what correlation measures, and how a rank correlation coefficient differs.', marks: 3, markScheme: `• Correlation measures how closely data points lie to a straight line (1)\n• A rank correlation coefficient measures the correlation between the ranks of the data (1)\n• It therefore reflects the ordering rather than the actual values (1)` },
      { q: 'State the usual null hypothesis in a test for correlation, and what is meant by association.', marks: 3, markScheme: `• The null hypothesis is that there is no correlation in the population (1)\n• For an association test, that there is no association in the population (1)\n• Association refers to a more general relationship between variables than a straight-line one (1)` },
      { q: 'Describe how a given correlation coefficient is used to carry out an informal test for correlation in the population.', marks: 3, markScheme: `• The coefficient calculated from the sample is quoted in the question (1)\n• It is compared with a given critical value, or its given p-value is compared with the significance level (1)\n• A conclusion is then drawn about whether there is correlation in the population, stated in context (1)` },
      { q: 'Explain why a significant correlation does not establish causation, giving an example.', marks: 3, markScheme: `• A third variable may influence both quantities (1)\n• Example: ice cream sales and drownings are positively correlated (1)\n• Both are driven by hot weather, so neither causes the other (1)` },
      { q: 'A researcher performs 20 independent tests at the 5% level on data with no real effect. Find the expected number of significant results and comment.', marks: 3, markScheme: `• Each test has probability 0.05 of a false rejection (1)\n• Expected number = 20 × 0.05 = 1 (1)\n• So about one apparently significant result is expected purely by chance, which is why multiple testing must be interpreted cautiously (1)` },
      { q: 'A student concludes "the coin is definitely biased" after rejecting H₀ at the 5% level. Explain why this is not an acceptable conclusion.', marks: 3, markScheme: `• A hypothesis test provides evidence, not proof (1)\n• There remains up to a 5% chance that a fair coin would produce such a result (1)\n• The conclusion should state that there is evidence at the 5% level that the coin is biased (1)` },
      { q: 'Explain what is meant by failing to detect a real effect, and one way of reducing the chance of it.', marks: 3, markScheme: `• It occurs when H₀ is not rejected even though it is false (1)\n• The evidence was insufficient to reach the critical region (1)\n• Increasing the sample size reduces the variability of the sample statistic and makes detection more likely (1)` },
      { q: 'For a test of H₀: p = 0.4 against H₁: p ≠ 0.4 at the 10% level, describe the critical regions.', marks: 3, markScheme: `• The test is two-tailed, so there are two critical regions (1)\n• One lies in each tail of the distribution (1)\n• Each has probability at most 0.05, so the total does not exceed 0.10 (1)` },
      { q: 'Explain why the conclusion of a hypothesis test must always be stated in context.', marks: 2, markScheme: `• A bare statement about rejecting H₀ does not answer the question that was asked (1)\n• The conclusion must say what the result means for the real situation being investigated (1)` },
    ]
  },

  '3.1': {
    name: 'Models & Quantities',
    questions: [
      { q: 'Explain why modelling assumptions are used in mechanics, and why they should be stated.', marks: 3, markScheme: `• Real situations are too complicated to analyse exactly (1)\n• Assumptions simplify the situation enough to make the mathematics tractable (1)\n• The conclusions are only valid if the assumptions hold, so they must be stated for the answer to be meaningful (1)` },
      { q: 'Explain what is meant by modelling an object as a particle, and state one consequence.', marks: 3, markScheme: `• A particle has mass but negligible size (1)\n• All forces may therefore be taken to act at a single point (1)\n• Rotation of the object is ignored (1)` },
      { q: 'Give one situation in which the particle model is reasonable and one in which it is not, with reasons.', marks: 4, markScheme: `• Reasonable: a car travelling along a motorway (1)\n• Its size is small compared with the distances involved and rotation is irrelevant (1)\n• Unreasonable: a ladder leaning against a wall (1)\n• Its length and the distribution of its mass are essential to the problem (1)` },
      { q: 'State what the modelling assumptions "light" and "inextensible" mean for a string, and what each allows you to deduce.', marks: 4, markScheme: `• Light means the string has negligible mass (1)\n• So the tension is the same throughout its length (1)\n• Inextensible means it cannot stretch (1)\n• So connected particles have accelerations of equal magnitude (1)` },
      { q: 'State what modelling a pulley as smooth means and what it allows you to deduce.', marks: 2, markScheme: `• There is no friction at the pulley (1)\n• The tension is therefore unchanged in passing over it, so it is equal on both sides of the string (1)` },
      { q: 'Explain what the assumption "uniform" means and how it is used in a moments problem.', marks: 2, markScheme: `• The mass is evenly distributed throughout the body (1)\n• The weight may therefore be taken to act at the geometric centre, which for a rod is its midpoint (1)` },
      { q: 'Explain the difference between a smooth and a rough surface.', marks: 2, markScheme: `• A smooth surface exerts no frictional force (1)\n• A rough surface may exert a frictional force opposing motion or the tendency to move (1)` },
      { q: 'Explain what is meant by a rigid body, and how it differs from a particle.', marks: 3, markScheme: `• A rigid body does not bend or deform under load (1)\n• Unlike a particle it has extent, so the point at which a force acts matters (1)\n• A system of forces can therefore produce a turning effect as well as a translation (1)` },
      { q: 'State the meaning of the modelling assumption "thin" and give an example of its use.', marks: 2, markScheme: `• The thickness of the object is negligible (1)\n• A sheet of metal may then be modelled as a lamina, or a rod as a line (1)` },
      { q: 'Write down the SI base quantities and units used in mechanics.', marks: 3, markScheme: `• Length, measured in metres (m) (1)\n• Time, measured in seconds (s) (1)\n• Mass, measured in kilograms (kg) (1)` },
      { q: 'Write down the SI units of velocity, acceleration and force.', marks: 3, markScheme: `• Velocity in metres per second, m s⁻¹ (1)\n• Acceleration in metres per second per second, m s⁻² (1)\n• Force in newtons, N (1)` },
      { q: 'Write down the SI unit of moment and explain why it is not quoted in joules.', marks: 2, markScheme: `• The unit of moment is the newton metre, N m (1)\n• Although the base units coincide with those of energy, the units are kept distinct to distinguish a turning effect from an energy (1)` },
      { q: 'Express the newton in terms of SI base units, justifying your answer.', marks: 2, markScheme: `• From F = ma, force is mass times acceleration (1)\n• So 1 N = 1 kg m s⁻² (1)` },
      { q: 'Explain the difference between mass and weight, stating the units of each.', marks: 4, markScheme: `• Mass is a scalar property of the object, measured in kilograms (1)\n• Weight is the force of gravity acting on it, measured in newtons (1)\n• Weight is given by W = mg (1)\n• Mass is the same everywhere, whereas weight depends on the local value of g (1)` },
      { q: 'Find the weight of a mass of 5 kg, taking g = 9.8.', marks: 2, markScheme: `• W = mg (1)\n• W = 5 × 9.8 = 49 N (1)` },
      { q: 'A 2 kg mass hangs at rest from a light inextensible string. Find the tension, taking g = 9.8.', marks: 3, markScheme: `• The mass is in equilibrium, so the tension balances the weight (1)\n• T = mg = 2 × 9.8 (1)\n• T = 19.6 N (1)` },
      { q: 'Explain what happens to the mass and the weight of an object taken to the Moon.', marks: 3, markScheme: `• The mass is unchanged, since it is a property of the object (1)\n• The weight decreases, because g is smaller on the Moon (1)\n• Weight is a force that depends on the local gravitational field (1)` },
      { q: 'State the value of g used in examinations for this specification, and comment on whether g is a universal constant.', marks: 3, markScheme: `• Unless otherwise specified, g is taken to be 9.8 (1)\n• g is not a universal constant; it depends on location in the universe (1)\n• On Earth it is modelled as constant for the purposes of these problems (1)` },
      { q: 'Estimate the percentage error introduced by using g = 10 instead of g = 9.8.', marks: 3, markScheme: `• Absolute difference = 0.2 (1)\n• Percentage error = 0.2/9.8 × 100 (1)\n• Approximately 2% (1)` },
      { q: 'Convert 36 km h⁻¹ into metres per second, showing your working.', marks: 3, markScheme: `• 36 km = 36000 m (1)\n• 1 hour = 3600 s (1)\n• 36000/3600 = 10 m s⁻¹ (1)` },
      { q: 'Convert 5 m s⁻¹ into kilometres per hour.', marks: 2, markScheme: `• Multiply by 3600 and divide by 1000 (1)\n• 5 × 3.6 = 18 km h⁻¹ (1)` },
      { q: 'Express a mass of 200 g and a length of 25 cm in SI base units.', marks: 2, markScheme: `• 200 g = 0.2 kg (1)\n• 25 cm = 0.25 m (1)` },
      { q: 'Classify each of the following as a scalar or a vector: mass; velocity; speed; force; time; acceleration.', marks: 3, markScheme: `• Scalars: mass, speed, time (1)\n• Vectors: velocity, force (1)\n• Acceleration is a vector (1)` },
      { q: 'Explain the difference between a base quantity and a derived quantity, giving one example of each.', marks: 3, markScheme: `• A base quantity is one of the fundamental quantities, not defined in terms of others (1)\n• Example: mass, measured in kilograms (1)\n• A derived quantity is defined in terms of base quantities, such as force in kg m s⁻² (1)` },
      { q: 'Explain why checking the units of an answer is a useful way of detecting errors.', marks: 3, markScheme: `• Each physical quantity has characteristic units (1)\n• An answer whose units do not match the quantity asked for must contain an error (1)\n• For example an acceleration quoted in kilograms indicates that mass and acceleration have been confused (1)` },
      { q: 'A moment of 12 N m is produced by a force acting perpendicular to a rod. Give one possible combination of force and distance.', marks: 2, markScheme: `• Moment = force × perpendicular distance (1)\n• For example a force of 4 N acting 3 m from the pivot (1)` },
      { q: 'A force of 1 N acts on a mass of 1 kg. Find the acceleration produced, and state what this shows about the definition of the newton.', marks: 3, markScheme: `• a = F/m = 1/1 (1)\n• a = 1 m s⁻² (1)\n• The newton is defined as the force giving a mass of 1 kg an acceleration of 1 m s⁻² (1)` },
      { q: 'Explain what is meant by the modelling assumption "long term".', marks: 2, markScheme: `• It refers to the behaviour of the system after a long time has elapsed (1)\n• Transient effects present at the start are assumed to have died away (1)` },
      { q: 'A model of a falling object assumes no air resistance. Explain when this is reasonable and when it is not.', marks: 4, markScheme: `• Reasonable for a dense compact object falling a short distance (1)\n• The resistance is then small compared with the weight (1)\n• Unreasonable for a light object with a large surface area, such as a feather or a parachute (1)\n• Resistance is then comparable with the weight and dominates the motion (1)` },
      { q: 'Explain what is meant by refining a model, and give an example.', marks: 3, markScheme: `• Refining means removing or weakening a simplifying assumption to improve realism (1)\n• The model becomes more complicated but more accurate (1)\n• Example: introducing air resistance into a projectile model, so the path is no longer a parabola (1)` },
      { q: 'A train is modelled as a set of connected particles rather than a single particle. Explain when this is necessary.', marks: 3, markScheme: `• When the forces between the carriages are required (1)\n• A single particle model has no internal structure, so coupling forces do not appear (1)\n• Treating each carriage separately allows the coupling forces to be found (1)` },
      { q: 'Explain why the assumption that a string is inextensible is essential in a connected-particle problem.', marks: 2, markScheme: `• If the string cannot stretch, the two particles must move together (1)\n• Their accelerations therefore have equal magnitude, which allows a single value of a to be used in both equations (1)` },
      { q: 'A bridge cable is modelled as a particle. Explain why this is inappropriate.', marks: 3, markScheme: `• The cable has substantial length and its mass is distributed along it (1)\n• The particle model treats all mass as acting at a point (1)\n• The distribution of mass along the cable is central to the problem, so the model discards exactly what matters (1)` },
      { q: 'State two derived quantities used in mechanics that are not forces, giving their units.', marks: 2, markScheme: `• Velocity, measured in m s⁻¹ (1)\n• Acceleration, measured in m s⁻², or moment in N m (1)` },
      { q: 'A student writes "the acceleration is 3 kg". Identify the error and give the correct units.', marks: 2, markScheme: `• Kilograms measure mass, not acceleration (1)\n• Acceleration is measured in m s⁻² (1)` },
      { q: 'Explain why the tension throughout a light string is the same, but would not be if the string had significant mass.', marks: 3, markScheme: `• For a light string, the portion of string between any two points has negligible weight (1)\n• So no force is needed to support it and the tension does not change along the string (1)\n• A heavy string would need extra tension at the top to support the weight of the string below, so the tension would vary (1)` },
      { q: 'A ball is modelled as a particle in a projectile problem. State two features of the real ball that this assumption discards.', marks: 2, markScheme: `• Its size, so effects such as air resistance depending on surface area are ignored (1)\n• Its rotation, so spin and any resulting curve of the flight path are ignored (1)` },
      { q: 'Explain the difference between the assumptions "smooth" and "light" as applied to a pulley.', marks: 2, markScheme: `• Smooth means there is no friction at the pulley, so the tension is unchanged across it (1)\n• Light means the pulley itself has negligible mass, so no force is needed to accelerate it (1)` },
      { q: 'Describe how you would decide which modelling assumptions to state in an answer.', marks: 3, markScheme: `• Identify the simplifications actually used in setting up the equations (1)\n• State those that affect the result, such as smoothness, lightness or inextensibility (1)\n• Explain briefly what each allows, rather than listing terms without justification (1)` },
      { q: 'Explain why the conclusions of a mechanics problem should be checked for physical plausibility.', marks: 3, markScheme: `• The model may be a poor representation of the real situation (1)\n• An implausible answer, such as a negative mass or a speed greater than expected, signals an error or an inappropriate assumption (1)\n• Checking magnitude and sign against expectation is a quick way to detect mistakes (1)` },
    ]
  },

  '3.2': {
    name: 'Kinematics in 1 Dimension',
    questions: [
      { q: 'Explain the difference between distance travelled and displacement.', marks: 2, markScheme: `• Distance travelled is the total length of the path covered, a scalar (1)\n• Displacement is the net change in position, a vector with direction (1)` },
      { q: 'Explain the difference between speed and velocity, and between acceleration and magnitude of acceleration.', marks: 3, markScheme: `• Speed is the magnitude of velocity, so it is a scalar and never negative (1)\n• Velocity is a vector, carrying direction as well as magnitude (1)\n• Acceleration is a signed vector quantity, whereas its magnitude is never negative (1)` },
      { q: 'Explain the difference between position and displacement.', marks: 2, markScheme: `• Position is measured from a fixed origin (1)\n• Displacement is the change in position from a specified starting point (1)` },
      { q: 'Write down the formulae for average speed and average velocity.', marks: 2, markScheme: `• Average speed = distance travelled divided by elapsed time (1)\n• Average velocity = overall displacement divided by elapsed time (1)` },
      { q: 'A body travels 100 m north then 100 m south in 40 seconds. Find its average speed and its average velocity.', marks: 4, markScheme: `• Distance travelled = 200 m (1)\n• Average speed = 200/40 = 5 m s⁻¹ (1)\n• Overall displacement = 0 (1)\n• Average velocity = 0 (1)` },
      { q: 'State what the gradient and the area represent for a displacement-time graph and for a velocity-time graph.', marks: 4, markScheme: `• Gradient of a displacement-time graph gives velocity (1)\n• Area under a displacement-time graph has no physical meaning (1)\n• Gradient of a velocity-time graph gives acceleration (1)\n• Area under a velocity-time graph gives displacement (1)` },
      { q: 'A trapezium on a velocity-time graph has parallel sides 4 and 10 and width 6. Find the displacement it represents.', marks: 3, markScheme: `• Area of a trapezium = ½(sum of parallel sides) × width (1)\n• = ½(4 + 10) × 6 (1)\n• Displacement = 42 m (1)` },
      { q: 'A body travels at 12 m s⁻¹ for 5 s, then decelerates uniformly to rest over the next 4 s. Find the total distance travelled.', marks: 4, markScheme: `• Sketch or describe the velocity-time graph as a rectangle followed by a triangle (1)\n• Rectangle area = 12 × 5 = 60 m (1)\n• Triangle area = ½ × 12 × 4 = 24 m (1)\n• Total distance = 84 m (1)` },
      { q: 'Explain what area below the time axis on a velocity-time graph represents, and how it is treated when finding distance travelled.', marks: 3, markScheme: `• It represents displacement in the negative direction (1)\n• For displacement it is counted as negative (1)\n• For distance travelled its magnitude is added, so the sign is ignored (1)` },
      { q: 'Write down the five constant acceleration formulae.', marks: 5, markScheme: `• v = u + at (1)\n• s = ut + ½at² (1)\n• s = vt − ½at² (1)\n• s = ½(u + v)t (1)\n• v² = u² + 2as (1)` },
      { q: 'State the condition under which the constant acceleration formulae may be used, and what must be done otherwise.', marks: 2, markScheme: `• They may be used only when the acceleration is constant (1)\n• If the acceleration varies, calculus must be used instead (1)` },
      { q: 'A particle starts from rest and accelerates uniformly at 2 m s⁻² for 5 s. Find its final velocity and the distance travelled.', marks: 4, markScheme: `• Use v = u + at with u = 0 (1)\n• v = 10 m s⁻¹ (1)\n• Use s = ut + ½at² (1)\n• s = ½ × 2 × 25 = 25 m (1)` },
      { q: 'A car travelling at 20 m s⁻¹ decelerates uniformly at 4 m s⁻² until it stops. Find the time taken and the distance travelled.', marks: 4, markScheme: `• Use v = u + at with v = 0, u = 20, a = −4 (1)\n• t = 5 s (1)\n• Use s = ½(u + v)t (1)\n• s = ½ × 20 × 5 = 50 m (1)` },
      { q: 'A body has initial velocity 5 m s⁻¹ and accelerates at 3 m s⁻² over 10 m. Find its final speed to 3 significant figures.', marks: 3, markScheme: `• Use v² = u² + 2as, which avoids the unknown time (1)\n• v² = 25 + 60 = 85 (1)\n• v = 9.22 m s⁻¹ (1)` },
      { q: 'A car slows from 30 m s⁻¹ to rest in 6 s. Find its acceleration and comment on the sign.', marks: 3, markScheme: `• a = (v − u)/t = (0 − 30)/6 (1)\n• a = −5 m s⁻² (1)\n• The negative sign indicates deceleration, since the acceleration opposes the direction of motion (1)` },
      { q: 'A body accelerates uniformly from 10 to 30 m s⁻¹ in 4 s. Find the distance covered.', marks: 3, markScheme: `• Use s = ½(u + v)t (1)\n• = ½(10 + 30)(4) (1)\n• s = 80 m (1)` },
      { q: 'Explain how to choose which constant acceleration formula to use in a given problem.', marks: 2, markScheme: `• Each formula omits one of the five quantities (1)\n• Choose the one that omits the quantity that is neither known nor required (1)` },
      { q: 'A stone is dropped from rest. Taking g = 9.8, find its speed and the distance fallen after 2 s.', marks: 4, markScheme: `• Use v = u + at with u = 0 and a = 9.8 (1)\n• v = 19.6 m s⁻¹ (1)\n• Use s = ½at² (1)\n• s = ½ × 9.8 × 4 = 19.6 m (1)` },
      { q: 'A stone falls from rest through 45 m. Taking g = 9.8, find the time taken to 3 significant figures.', marks: 3, markScheme: `• Use s = ½at² with s = 45 (1)\n• t² = 90/9.8 = 9.184 (1)\n• t = 3.03 s (1)` },
      { q: 'A stone is thrown downwards at 5 m s⁻¹ from a height and falls for 2 s. Taking g = 9.8, find the distance fallen.', marks: 3, markScheme: `• Use s = ut + ½at² with u = 5 (1)\n• s = 10 + ½ × 9.8 × 4 (1)\n• s = 10 + 19.6 = 29.6 m (1)` },
      { q: 'A ball is thrown vertically upwards at 14.7 m s⁻¹. Taking g = 9.8, find the maximum height reached above the point of projection.', marks: 4, markScheme: `• At the maximum height the velocity is zero (1)\n• Use v² = u² + 2as with v = 0 and a = −9.8 (1)\n• 0 = 216.09 − 19.6s (1)\n• s = 11.025 m (1)` },
      { q: 'Explain why the acceleration of a ball thrown vertically upwards is the same at every stage of its flight, including at the highest point.', marks: 3, markScheme: `• The only force acting is the weight, which is constant and downwards (1)\n• The acceleration is therefore g downwards throughout (1)\n• At the highest point the velocity is momentarily zero, but the acceleration is not (1)` },
      { q: 'Explain the importance of fixing a positive direction at the start of a vertical motion problem.', marks: 3, markScheme: `• Displacement, velocity and acceleration are all signed quantities (1)\n• They must all be measured consistently with the same positive direction (1)\n• Changing the convention partway through introduces sign errors that invalidate the answer (1)` },
      { q: 'Write down the calculus relationships between displacement, velocity and acceleration in both directions.', marks: 4, markScheme: `• Velocity is the derivative of displacement with respect to time (1)\n• Acceleration is the derivative of velocity with respect to time (1)\n• Velocity is the integral of acceleration with respect to time (1)\n• Displacement is the integral of velocity with respect to time (1)` },
      { q: 'For s = t³ − 3t, find expressions for the velocity and the acceleration, and evaluate the velocity at t = 2.', marks: 4, markScheme: `• v = ds/dt = 3t² − 3 (1)\n• a = dv/dt = 6t (1)\n• At t = 2, v = 12 − 3 (1)\n• v = 9 m s⁻¹ (1)` },
      { q: 'A particle has acceleration a = 6t and velocity 2 m s⁻¹ when t = 0. Find its velocity at time t.', marks: 4, markScheme: `• Integrate the acceleration: v = 3t² + c (1)\n• Apply the initial condition at t = 0 (1)\n• 2 = 0 + c, so c = 2 (1)\n• v = 3t² + 2 (1)` },
      { q: 'Explain why the constant of integration must not be omitted when finding velocity from acceleration.', marks: 2, markScheme: `• The constant represents the initial velocity (1)\n• Omitting it assumes the body starts from rest, which is generally false and gives a wrong answer (1)` },
      { q: 'For s = t³ − 6t² + 9t, find the times at which the particle is instantaneously at rest.', marks: 4, markScheme: `• v = 3t² − 12t + 9 (1)\n• Set v = 0 (1)\n• Factorise: 3(t − 1)(t − 3) = 0 (1)\n• t = 1 and t = 3 (1)` },
      { q: 'For s = t³ − 6t² + 9t, find the total distance travelled between t = 0 and t = 4.', marks: 5, markScheme: `• The particle is at rest at t = 1 and t = 3, so the direction reverses there (1)\n• Evaluate s at t = 0, 1, 3, 4 giving 0, 4, 0, 4 (1)\n• The particle moves forward 4 m, then back 4 m (1)\n• then forward 4 m again (1)\n• Total distance = 12 m (1)` },
      { q: 'For s = t³ − 6t² + 9t, find the displacement between t = 0 and t = 4, and explain why it differs from the distance travelled.', marks: 3, markScheme: `• s(4) − s(0) = 4 − 0 (1)\n• Displacement = 4 m (1)\n• The displacement is the net change in position, whereas the distance counts the return journey as well (1)` },
      { q: 'Explain the general method for finding distance travelled when the velocity changes sign during the interval.', marks: 3, markScheme: `• Find the times at which the velocity is zero (1)\n• Split the interval at those times (1)\n• Find the displacement over each part and add the magnitudes (1)` },
      { q: 'Explain why integrating velocity straight through an interval in which it changes sign gives the displacement rather than the distance.', marks: 2, markScheme: `• Intervals in which the velocity is negative contribute negatively to the integral (1)\n• Positive and negative contributions therefore partially cancel, giving the net change rather than the total path length (1)` },
      { q: 'Two cars travel in the same direction at 30 and 20 m s⁻¹. Find the velocity of the first relative to the second and explain its significance.', marks: 3, markScheme: `• Relative velocity = 30 − 20 (1)\n• = 10 m s⁻¹ (1)\n• The gap closes at only 10 m s⁻¹ even though both cars are moving quickly, so overtaking takes longer than the individual speeds suggest (1)` },
      { q: 'A velocity-time graph is a straight line through the origin. Describe the motion.', marks: 2, markScheme: `• The body starts from rest, since the velocity is zero at t = 0 (1)\n• The gradient is constant, so the acceleration is constant (1)` },
      { q: 'A displacement-time graph is a horizontal line. Describe the motion.', marks: 2, markScheme: `• The gradient is zero, so the velocity is zero (1)\n• The body is at rest at a fixed position (1)` },
      { q: 'Explain why the suvat formulae cannot be applied to a body whose acceleration is given by a = 6t.', marks: 2, markScheme: `• The acceleration varies with time rather than being constant (1)\n• The formulae are derived on the assumption of constant acceleration, so calculus must be used instead (1)` },
      { q: 'For a body with constant acceleration, explain why the average velocity equals half the sum of the initial and final velocities.', marks: 3, markScheme: `• With constant acceleration the velocity-time graph is a straight line (1)\n• The area under it is a trapezium, of area ½(u + v)t (1)\n• Dividing that displacement by t gives the average velocity ½(u + v) (1)` },
      { q: 'A car accelerates from rest at 2 m s⁻² for 10 s, then travels at constant speed for 20 s. Find the total distance travelled.', marks: 4, markScheme: `• Speed after 10 s = 2 × 10 = 20 m s⁻¹ (1)\n• Distance in the first phase = ½ × 2 × 100 = 100 m (1)\n• Distance in the second phase = 20 × 20 = 400 m (1)\n• Total = 500 m (1)` },
      { q: 'A ball is thrown vertically upwards at 19.6 m s⁻¹ from ground level. Taking g = 9.8, find the total time before it returns to the ground.', marks: 4, markScheme: `• By symmetry the time up equals the time down (1)\n• Time to the highest point: 0 = 19.6 − 9.8t, so t = 2 s (1)\n• Total time = 2 × 2 (1)\n• Total time = 4 s (1)` },
      { q: 'Explain why a body momentarily at rest need not have zero acceleration, giving an example.', marks: 3, markScheme: `• Velocity and acceleration are independent quantities at any instant (1)\n• A ball at the top of its flight has zero velocity (1)\n• Its acceleration is still g downwards, which is why it does not remain at rest (1)` },
    ]
  },

  '3.3': {
    name: 'Kinematics in 2 Dimensions',
    questions: [
      { q: 'Write down the relationships between position, velocity and acceleration for motion in two dimensions.', marks: 3, markScheme: `• Velocity is the derivative of the position vector with respect to time (1)\n• Acceleration is the derivative of the velocity vector with respect to time (1)\n• Conversely, velocity is the integral of acceleration and position the integral of velocity (1)` },
      { q: 'Explain why differentiating and integrating vectors can be carried out component by component.', marks: 3, markScheme: `• The i and j directions are fixed and independent of time (1)\n• Each component is therefore an independent function of t (1)\n• The calculus can be applied to each component separately (1)` },
      { q: 'A particle has position vector r = 3t i + t² j. Find its velocity and acceleration.', marks: 3, markScheme: `• Differentiate each component with respect to t (1)\n• v = 3i + 2t j (1)\n• a = 2j (1)` },
      { q: 'For the particle with r = 3t i + t² j, find the speed at t = 2.', marks: 3, markScheme: `• v = 3i + 2t j, so at t = 2, v = 3i + 4j (1)\n• Speed is the magnitude, √(3² + 4²) (1)\n• Speed = 5 (1)` },
      { q: 'Explain the difference between velocity and speed for two-dimensional motion.', marks: 2, markScheme: `• Velocity is a vector, with components in the i and j directions (1)\n• Speed is a scalar, equal to the magnitude of the velocity vector (1)` },
      { q: 'A particle has acceleration a = 2i + 6t j and velocity i at t = 0. Find its velocity at time t.', marks: 4, markScheme: `• Integrate the acceleration component by component (1)\n• v = 2t i + 3t² j + c (1)\n• At t = 0 the velocity is i, so c = i (1)\n• v = (1 + 2t)i + 3t² j (1)` },
      { q: 'A particle has a = 6t i − 2j, with v = 0 and r = 0 at t = 0. Find its position vector at time t.', marks: 5, markScheme: `• Integrate the acceleration: v = 3t² i − 2t j + c₁ (1)\n• v = 0 at t = 0 gives c₁ = 0 (1)\n• Integrate the velocity: r = t³ i − t² j + c₂ (1)\n• r = 0 at t = 0 gives c₂ = 0 (1)\n• r = t³ i − t² j (1)` },
      { q: 'Explain why a vector constant of integration is needed rather than a scalar one.', marks: 2, markScheme: `• Each component of the integral has its own arbitrary constant (1)\n• Together these form a constant vector, which is fixed by the initial conditions in both directions (1)` },
      { q: 'Explain the difference between distance from the origin, displacement and distance travelled in two dimensions.', marks: 3, markScheme: `• Distance from the origin at time t is the magnitude of the position vector (1)\n• Displacement is the change in position vector between two times, a vector quantity (1)\n• Distance travelled is the length of the path followed, generally greater than the magnitude of the displacement (1)` },
      { q: 'For r = 2t i + t² j, find the average velocity between t = 0 and t = 2.', marks: 4, markScheme: `• Position at t = 2 is 4i + 4j (1)\n• Position at t = 0 is the zero vector (1)\n• Displacement = 4i + 4j over 2 seconds (1)\n• Average velocity = 2i + 2j (1)` },
      { q: 'Write down the vector forms of the constant acceleration formulae.', marks: 4, markScheme: `• v = u + at (1)\n• s = ut + ½at² (1)\n• s = vt − ½at² (1)\n• s = ½(u + v)t (1)` },
      { q: 'A particle has initial velocity 2i and constant acceleration j. Find its displacement after 4 s.', marks: 3, markScheme: `• Use s = ut + ½at² (1)\n• s = 2i(4) + ½ j(16) (1)\n• s = 8i + 8j (1)` },
      { q: 'A particle starts at 2i + j and moves with constant velocity 3i − j. Find its position vector at t = 4.', marks: 3, markScheme: `• Displacement = 4(3i − j) = 12i − 4j (1)\n• Add to the initial position (1)\n• r = 14i − 3j (1)` },
      { q: 'Explain why, for constant acceleration, the change in velocity is always parallel to the acceleration.', marks: 2, markScheme: `• From v = u + at, the change in velocity is at (1)\n• Since t is a scalar, at is a scalar multiple of a and therefore parallel to it (1)` },
      { q: 'Explain what the path of a particle looks like when the acceleration is zero.', marks: 2, markScheme: `• With zero acceleration the velocity is constant in both magnitude and direction (1)\n• The particle therefore moves in a straight line at constant speed (1)` },
      { q: 'Write down expressions for the position of B relative to A, and the velocity of A relative to B.', marks: 2, markScheme: `• Position of B relative to A = r_B − r_A (1)\n• Velocity of A relative to B = v_A − v_B (1)` },
      { q: 'A is at 3i + 4j and B is at 7i + j. Find the position of B relative to A and the distance between them.', marks: 3, markScheme: `• Position of B relative to A = (7 − 3)i + (1 − 4)j (1)\n• = 4i − 3j (1)\n• Distance = √(16 + 9) = 5 (1)` },
      { q: 'A has velocity 5i + 2j and B has velocity 3i − j. Find the velocity of A relative to B.', marks: 3, markScheme: `• Subtract the velocity vectors (1)\n• (5 − 3)i + (2 − (−1))j (1)\n• = 2i + 3j (1)` },
      { q: 'State the condition for two particles to collide, and explain why checking one component is not enough.', marks: 3, markScheme: `• The position vectors must be equal at the same instant (1)\n• Both components must therefore agree for a single common value of t (1)\n• If the components give different times, the paths cross but the particles are never at that point together (1)` },
      { q: 'Particle A has position vector (t + 1)i + 2t j and particle B has (3t − 1)i + (t + 1)j. Show that they collide and state the time and position.', marks: 5, markScheme: `• Equate the i components: t + 1 = 3t − 1 (1)\n• This gives t = 1 (1)\n• Equate the j components: 2t = t + 1 (1)\n• This also gives t = 1, so both agree (1)\n• Collision at t = 1, at the point 2i + 2j (1)` },
      { q: 'Two particles have the same constant velocity vector. State the velocity of one relative to the other and describe what this means.', marks: 2, markScheme: `• The relative velocity is the zero vector (1)\n• The separation between them stays constant, so they move as though at rest relative to each other (1)` },
      { q: 'Describe how you would find the time at which two particles moving with constant velocities are closest together.', marks: 4, markScheme: `• Write the relative position vector as a function of t (1)\n• Find an expression for the magnitude of that vector, or its square (1)\n• Minimise the expression, usually by differentiating and setting the derivative to zero (1)\n• The minimum of the magnitude gives the time and value of closest approach (1)` },
      { q: 'Explain how to find the Cartesian equation of the path of a particle from its position vector.', marks: 3, markScheme: `• Write the i and j components as x and y in terms of t (1)\n• Eliminate t between the two equations, usually by rearranging the simpler one (1)\n• The resulting relationship between x and y is the Cartesian equation of the path (1)` },
      { q: 'A particle has r = 3t i + t² j. Find the Cartesian equation of its path and name the curve.', marks: 3, markScheme: `• x = 3t so t = x/3 (1)\n• y = t² = x²/9 (1)\n• The path is a parabola (1)` },
      { q: 'A particle has r = 2t i + (t² − 1)j. Find the Cartesian equation of its path.', marks: 3, markScheme: `• x = 2t so t = x/2 (1)\n• y = (x/2)² − 1 (1)\n• y = x²/4 − 1 (1)` },
      { q: 'A particle has r = 4t i + (3t − 5t²)j. Find the Cartesian equation of its path and describe the curve.', marks: 4, markScheme: `• x = 4t so t = x/4 (1)\n• Substitute into the j component (1)\n• y = 3x/4 − 5x²/16 (1)\n• The path is a parabola, as expected for constant acceleration perpendicular to part of the motion (1)` },
      { q: 'A particle has r = (t − 2)i + (t² − 4)j. Determine whether it passes through the origin.', marks: 4, markScheme: `• The i component is zero when t = 2 (1)\n• The j component is zero when t = 2 or t = −2 (1)\n• Both components vanish at t = 2 (1)\n• So the particle does pass through the origin, at t = 2 (1)` },
      { q: 'A particle has r = (t² − 4t)i + 3t j. Find the times at which it crosses the j-axis.', marks: 3, markScheme: `• The particle is on the j-axis when the i component is zero (1)\n• t² − 4t = 0, so t(t − 4) = 0 (1)\n• t = 0 or t = 4 (1)` },
      { q: 'A particle has r = t² i + (2t − t²)j. Determine whether its velocity is ever zero.', marks: 4, markScheme: `• v = 2t i + (2 − 2t)j (1)\n• The i component is zero only at t = 0 (1)\n• At t = 0 the j component equals 2, which is not zero (1)\n• The two components are never zero simultaneously, so the velocity is never zero (1)` },
      { q: 'A boat is steered with velocity 4i and the current has velocity 3j. Find the resultant velocity and the speed.', marks: 3, markScheme: `• Resultant velocity = 4i + 3j (1)\n• Speed = √(16 + 9) (1)\n• Speed = 5 (1)` },
      { q: 'A particle is projected with initial velocity 5i + 12j. Find its initial speed and the angle of projection to 1 decimal place.', marks: 4, markScheme: `• Speed = √(25 + 144) (1)\n• Speed = 13 (1)\n• tan θ = 12/5 (1)\n• θ = 67.4° above the i-direction (1)` },
      { q: 'For a particle with constant acceleration a = 0 and initial velocity 3i − 4j, find the distance from the starting point after 5 s.', marks: 3, markScheme: `• Displacement = 5(3i − 4j) = 15i − 20j (1)\n• Magnitude = √(225 + 400) (1)\n• Distance = 25 (1)` },
      { q: 'Explain why the vector s = ½(u + v)t is valid for two-dimensional motion with constant acceleration.', marks: 2, markScheme: `• Each component undergoes constant acceleration independently (1)\n• The one-dimensional result therefore applies to each component, and combining them gives the vector form (1)` },
      { q: 'Explain what the position vector of a particle measures, and state what its magnitude represents.', marks: 2, markScheme: `• The position vector gives the position of the particle relative to a fixed origin (1)\n• Its magnitude is the distance of the particle from that origin (1)` },
      { q: 'A particle moves so that r = (t + 1)i + (2t − 3)j. Show that its path is a straight line.', marks: 4, markScheme: `• x = t + 1 so t = x − 1 (1)\n• y = 2(x − 1) − 3 (1)\n• y = 2x − 5 (1)\n• This is the equation of a straight line, consistent with the velocity i + 2j being constant (1)` },
      { q: 'Explain the difference between the direction of the velocity vector and the direction of the position vector.', marks: 2, markScheme: `• The velocity vector points along the direction of motion, tangent to the path (1)\n• The position vector points from the origin to the particle, which is generally a different direction (1)` },
      { q: 'A particle has velocity 4i − 3j. Find its speed and the angle its motion makes with the i-direction.', marks: 3, markScheme: `• Speed = √(16 + 9) = 5 (1)\n• tan θ = −3/4, so the related acute angle is 36.9° (1)\n• The motion is 36.9° below the i-direction (1)` },
      { q: 'Explain how the number of components changes when moving from two-dimensional to three-dimensional kinematics.', marks: 2, markScheme: `• Two-dimensional vectors have two components, in the i and j directions (1)\n• Three-dimensional vectors have a third component in the k direction, and magnitudes involve the sum of three squares (1)` },
      { q: 'Two particles start at the same point with different constant velocities. Describe how their separation changes with time.', marks: 3, markScheme: `• The relative velocity is constant and non-zero (1)\n• The relative position is that relative velocity multiplied by t (1)\n• The separation therefore increases linearly with time, in a fixed direction (1)` },
      { q: 'Explain why finding the Cartesian equation of a path can be more useful than the parametric form.', marks: 3, markScheme: `• The Cartesian equation shows the shape of the path directly (1)\n• It allows features such as intercepts and turning points to be identified (1)\n• The parametric form is better for questions about timing, since it retains the time information the Cartesian form discards (1)` },
    ]
  },

  '3.4': {
    name: 'Projectiles',
    questions: [
      { q: 'State the four standard modelling assumptions used for projectile motion.', marks: 4, markScheme: `• There is no air resistance (1)\n• The projectile is modelled as a particle (1)\n• The horizontal distance is small enough that gravity always acts in the same direction (1)\n• The vertical distance is small enough that gravity is constant in magnitude (1)` },
      { q: 'Explain the central idea that makes projectile problems tractable.', marks: 3, markScheme: `• Horizontal and vertical motion are treated independently (1)\n• Horizontally there is no acceleration, so the velocity is constant (1)\n• Vertically the acceleration is g downwards, so the constant acceleration formulae apply (1)` },
      { q: 'For a projectile launched at speed u and angle θ, write down the horizontal and vertical components of the initial velocity.', marks: 2, markScheme: `• Horizontal component = u cos θ (1)\n• Vertical component = u sin θ (1)` },
      { q: 'For a projectile launched at speed u and angle θ, write down expressions for the horizontal and vertical displacement at time t.', marks: 2, markScheme: `• Horizontal displacement = u cos θ × t (1)\n• Vertical displacement = u sin θ × t − ½gt² (1)` },
      { q: 'Write down an expression for the vertical component of a projectile\'s velocity at time t, and explain what happens to it at the highest point.', marks: 3, markScheme: `• Vertical velocity = u sin θ − gt (1)\n• At the highest point the vertical velocity is zero (1)\n• The horizontal component is unchanged, so the velocity there is horizontal, not zero (1)` },
      { q: 'A projectile is launched at 20 m s⁻¹ at 30° to the horizontal. Find the components of the initial velocity, taking g = 9.8.', marks: 3, markScheme: `• Horizontal = 20 cos 30° (1)\n• = 17.3 m s⁻¹ to 3 s.f. (1)\n• Vertical = 20 sin 30° = 10 m s⁻¹ (1)` },
      { q: 'For that same projectile, find the time to reach the highest point and the maximum height above the point of projection.', marks: 4, markScheme: `• At the highest point the vertical velocity is zero (1)\n• 0 = 10 − 9.8t, so t = 1.02 s (1)\n• Use v² = u² + 2as vertically (1)\n• Maximum height = 100/19.6 = 5.10 m (1)` },
      { q: 'For that same projectile on level ground, find the time of flight and the range.', marks: 4, markScheme: `• By symmetry the time of flight is twice the time to the highest point (1)\n• Time of flight = 2.04 s (1)\n• Range = u² sin 2θ / g = 400 sin 60° / 9.8 (1)\n• Range = 35.3 m to 3 s.f. (1)` },
      { q: 'Write down formulae for the time of flight, maximum height and range of a projectile launched at speed u and angle θ on level ground.', marks: 3, markScheme: `• Time of flight = 2u sin θ / g (1)\n• Maximum height = u² sin²θ / (2g) (1)\n• Range = u² sin 2θ / g (1)` },
      { q: 'Show that the range of a projectile on level ground is greatest when the angle of projection is 45°.', marks: 4, markScheme: `• Range = u² sin 2θ / g (1)\n• u² and g are fixed, so the range is greatest when sin 2θ is greatest (1)\n• sin 2θ has maximum value 1 when 2θ = 90° (1)\n• So θ = 45°, giving a maximum range of u²/g (1)` },
      { q: 'Explain why two different angles of projection can give the same range, and find the partner angle to 25°.', marks: 4, markScheme: `• Range depends on sin 2θ (1)\n• sin 2θ = sin(180° − 2θ), so θ and 90° − θ give the same range (1)\n• The partner of 25° is 90° − 25° (1)\n• = 65° (1)` },
      { q: 'A ball is thrown horizontally at 15 m s⁻¹ from a height of 20 m. Taking g = 9.8, find the time to reach the ground.', marks: 4, markScheme: `• The initial vertical velocity is zero (1)\n• Use s = ½gt² vertically with s = 20 (1)\n• t² = 40/9.8 = 4.082 (1)\n• t = 2.02 s to 3 s.f. (1)` },
      { q: 'For that same ball, find the horizontal distance travelled before landing.', marks: 3, markScheme: `• The horizontal velocity is constant at 15 m s⁻¹ (1)\n• Horizontal distance = 15 × 2.02 (1)\n• = 30.3 m to 3 s.f. (1)` },
      { q: 'Explain why a ball thrown horizontally and a ball dropped from the same height reach the ground at the same time.', marks: 3, markScheme: `• Both have zero initial vertical velocity (1)\n• The vertical motion depends only on gravity, which acts equally on both (1)\n• The horizontal motion has no effect on the vertical fall, so the times are equal (1)` },
      { q: 'A projectile launched at 40 m s⁻¹ vertically upwards. Taking g = 9.8, find the maximum height reached.', marks: 3, markScheme: `• Use v² = u² + 2as with v = 0 (1)\n• 0 = 1600 − 19.6s (1)\n• s = 81.6 m to 3 s.f. (1)` },
      { q: 'A ball is projected at 25 m s⁻¹ at an angle with sin θ = 0.6. Taking g = 9.8, find the maximum height.', marks: 4, markScheme: `• Vertical component = 25 × 0.6 (1)\n• = 15 m s⁻¹ (1)\n• Maximum height = 15²/(2 × 9.8) (1)\n• = 11.5 m to 3 s.f. (1)` },
      { q: 'Derive the Cartesian equation of the path of a projectile launched from the origin at speed u and angle θ.', marks: 5, markScheme: `• Horizontal: x = u cos θ × t (1)\n• Vertical: y = u sin θ × t − ½gt² (1)\n• Rearrange the horizontal equation to t = x/(u cos θ) (1)\n• Substitute into the vertical equation (1)\n• y = x tan θ − gx²/(2u² cos²θ) (1)` },
      { q: 'Explain why the path of a projectile under the standard assumptions is a parabola.', marks: 3, markScheme: `• The Cartesian equation is y = x tan θ − gx²/(2u² cos²θ) (1)\n• This is a quadratic in x (1)\n• The coefficient of x² is negative, so the curve is a parabola opening downwards (1)` },
      { q: 'A projectile must clear a wall of height 3 m at a horizontal distance of 20 m. Describe the check required, and explain why checking the range alone is insufficient.', marks: 4, markScheme: `• Substitute x = 20 into the equation of the path (1)\n• Confirm that the resulting y exceeds 3 (1)\n• The range only tells you where the projectile lands, not its height along the way (1)\n• The projectile could have sufficient range yet still be below 3 m at x = 20 (1)` },
      { q: 'Explain why checking that the maximum height exceeds the height of an obstacle is not sufficient to show that the obstacle is cleared.', marks: 2, markScheme: `• The maximum height occurs at one particular horizontal distance (1)\n• The obstacle may be at a different distance, where the projectile is lower (1)` },
      { q: 'Write down an expression for the speed of a projectile at time t in terms of u, θ, g and t.', marks: 3, markScheme: `• Horizontal component of velocity is u cos θ (1)\n• Vertical component is u sin θ − gt (1)\n• Speed = √((u cos θ)² + (u sin θ − gt)²) (1)` },
      { q: 'Explain why, for projection and landing at the same level, the landing speed equals the speed of projection.', marks: 3, markScheme: `• The horizontal component of velocity is unchanged throughout (1)\n• The vertical component has the same magnitude on landing as on projection, by symmetry of the parabola (1)\n• The combined speed is therefore the same, with the direction now below the horizontal (1)` },
      { q: 'A projectile is launched from a height h above the point where it lands. Write down the equation used to find the time of flight and explain the sign convention.', marks: 4, markScheme: `• Take upwards as positive with the launch point as the origin (1)\n• The vertical displacement on landing is −h (1)\n• −h = u sin θ × t − ½gt² (1)\n• Solve this quadratic for t and take the positive root (1)` },
      { q: 'Explain why a projectile launched from a height has a longer time of flight than one launched at the same speed and angle on level ground.', marks: 3, markScheme: `• On level ground the projectile returns to its launch height (1)\n• Launched from a height, it must fall further before landing (1)\n• The extra descent takes additional time, so the flight is longer (1)` },
      { q: 'Explain why a projectile passes a given height below its maximum twice during its flight.', marks: 3, markScheme: `• The vertical displacement equation is a quadratic in t (1)\n• Setting it equal to a given height gives two roots (1)\n• These correspond to the projectile rising through that height and later falling back through it (1)` },
      { q: 'A projectile launched at 30° has a range of 50 m on level ground. Taking g = 9.8, find the initial speed to 3 significant figures.', marks: 4, markScheme: `• Use range = u² sin 2θ / g (1)\n• 50 = u² sin 60° / 9.8 (1)\n• u² = 50 × 9.8 / 0.866 (1)\n• u = 23.8 m s⁻¹ (1)` },
      { q: 'Describe the effect of introducing air resistance into a projectile model.', marks: 4, markScheme: `• The range is reduced (1)\n• The maximum height is reduced (1)\n• The path is no longer a symmetric parabola, with the descent steeper than the ascent (1)\n• Calculations involving air resistance are excluded from this specification (1)` },
      { q: 'Explain why the assumption that gravity acts in a constant direction is reasonable for most projectile problems.', marks: 2, markScheme: `• Gravity acts towards the centre of the Earth, so its direction varies over large horizontal distances (1)\n• Over the small distances involved in these problems the variation is negligible (1)` },
      { q: 'A stone is thrown at 14 m s⁻¹ at 45° from level ground. Taking g = 9.8, find the range to 3 significant figures.', marks: 3, markScheme: `• Range = u² sin 2θ / g (1)\n• = 196 × sin 90° / 9.8 (1)\n• = 20.0 m (1)` },
      { q: 'Explain the standard method for setting out a projectile solution to avoid confusing the two directions.', marks: 3, markScheme: `• Resolve the initial velocity into horizontal and vertical components before anything else (1)\n• Set out the horizontal and vertical working in separate columns (1)\n• Use time as the only quantity linking them (1)` },
      { q: 'For a projectile on level ground, explain why the time to the highest point is half the total time of flight.', marks: 3, markScheme: `• The vertical motion is symmetric about the highest point (1)\n• The time to rise from the launch height equals the time to fall back to it (1)\n• So the total time is twice the time to the highest point (1)` },
      { q: 'A projectile has initial vertical component 21 m s⁻¹. Taking g = 9.8, find the time at which it is 10 m above the point of projection, giving both answers to 3 significant figures.', marks: 5, markScheme: `• Use s = ut − ½gt² with s = 10 (1)\n• 10 = 21t − 4.9t² (1)\n• Rearrange to 4.9t² − 21t + 10 = 0 (1)\n• Apply the quadratic formula (1)\n• t = 0.546 s and t = 3.74 s (1)` },
      { q: 'Explain the physical meaning of the two roots obtained in the previous question.', marks: 2, markScheme: `• The smaller root is the time at which the projectile passes that height on the way up (1)\n• The larger root is the time at which it passes the same height on the way down (1)` },
      { q: 'Explain why the horizontal component of a projectile\'s velocity remains constant.', marks: 2, markScheme: `• The only force acting after release is the weight, which is vertical (1)\n• There is therefore no horizontal force and no horizontal acceleration (1)` },
      { q: 'A projectile is launched at 30 m s⁻¹ at 60° to the horizontal. Taking g = 9.8, find the maximum height to 3 significant figures.', marks: 4, markScheme: `• Vertical component = 30 sin 60° (1)\n• = 25.98 m s⁻¹ (1)\n• Maximum height = 25.98²/(2 × 9.8) (1)\n• = 34.4 m (1)` },
      { q: 'State how the initial velocity of a projectile can be determined, and what information is required.', marks: 3, markScheme: `• The initial speed and angle can be found from sufficient information about the flight (1)\n• For example the range together with the angle of projection on level ground (1)\n• Or the coordinates of two points on the path, giving two equations to solve simultaneously (1)` },
      { q: 'Explain why the angle at which a projectile lands on level ground equals the angle of projection.', marks: 3, markScheme: `• The horizontal component of velocity is unchanged (1)\n• The vertical component has equal magnitude but opposite sign on landing (1)\n• The ratio of the components, and hence the angle to the horizontal, is therefore the same, but now directed below the horizontal (1)` },
      { q: 'Explain what would change in a projectile model if the launch and landing points were at different heights.', marks: 3, markScheme: `• The symmetry of the flight is lost (1)\n• The time of flight is no longer twice the time to the highest point (1)\n• The standard range formula no longer applies, and the quadratic for the time of flight must be solved directly (1)` },
      { q: 'A ball is kicked at 20 m s⁻¹ at 40° to the horizontal. Taking g = 9.8, find the time of flight on level ground to 3 significant figures.', marks: 3, markScheme: `• Vertical component = 20 sin 40° = 12.86 m s⁻¹ (1)\n• Time of flight = 2 × 12.86 / 9.8 (1)\n• = 2.62 s (1)` },
      { q: 'Compare the maximum height and range of a projectile launched at 30° with one launched at 60° at the same speed, and explain the relationship.', marks: 4, markScheme: `• The ranges are equal, since sin 60° = sin 120° (1)\n• The maximum heights are different (1)\n• Maximum height depends on sin²θ, which is larger for 60° (1)\n• The 60° projectile therefore rises higher and stays in the air longer, but travels the same horizontal distance (1)` },
    ]
  },

  '3.5': {
    name: 'Forces',
    questions: [
      { q: 'Name four forces commonly appearing in mechanics problems and state the direction of each.', marks: 4, markScheme: `• Weight acts vertically downwards (1)\n• The normal reaction acts perpendicular to the surface of contact (1)\n• Tension acts along a string, pulling inwards (1)\n• Friction acts along the surface, opposing motion or the tendency to move (1)` },
      { q: 'Explain the difference between tension and thrust, and state which can occur in a string.', marks: 3, markScheme: `• Tension pulls the objects at each end towards one another (1)\n• Thrust, or compression, pushes them apart (1)\n• A string can only pull, so it can carry tension but not thrust; a rod can carry either (1)` },
      { q: 'Explain why the normal reaction is not always equal to the weight, giving two examples.', marks: 4, markScheme: `• The normal reaction depends on all the other forces acting perpendicular to the surface (1)\n• Pressing down on a block increases the normal reaction above the weight (1)\n• On an inclined plane the normal reaction is mg cos θ, which is less than the weight (1)\n• In a lift accelerating upwards the reaction exceeds the weight (1)` },
      { q: 'Explain what is meant by describing a surface as smooth or as rough.', marks: 2, markScheme: `• Smooth means there is no frictional force (1)\n• Rough means a frictional force may act, opposing motion or the tendency to move (1)` },
      { q: 'Explain what a force diagram should show, and one common omission.', marks: 3, markScheme: `• It should show every force acting on the body concerned (1)\n• It should show only forces acting on that body, not forces it exerts on others (1)\n• The normal reaction or the weight is commonly omitted (1)` },
      { q: 'Explain the difference between internal and external forces in a system, and why the distinction matters.', marks: 3, markScheme: `• An internal force acts between parts of the system (1)\n• An external force acts on the system from outside (1)\n• When the whole system is treated as one body, internal forces cancel in pairs and can be ignored (1)` },
      { q: 'A force of 20 N acts at 30° above the horizontal. Find its horizontal and vertical components.', marks: 3, markScheme: `• Horizontal component = 20 cos 30° (1)\n• = 17.3 N to 3 s.f. (1)\n• Vertical component = 20 sin 30° = 10 N (1)` },
      { q: 'For a body on a plane inclined at angle θ, write down the components of the weight parallel and perpendicular to the plane.', marks: 2, markScheme: `• Component parallel to the plane = mg sin θ (1)\n• Component perpendicular to the plane = mg cos θ (1)` },
      { q: 'A 10 kg block rests on a plane inclined at 30°. Taking g = 9.8, find the components of the weight parallel and perpendicular to the plane.', marks: 4, markScheme: `• Weight = 10 × 9.8 = 98 N (1)\n• Parallel component = 98 sin 30° (1)\n• = 49 N (1)\n• Perpendicular component = 98 cos 30° = 84.9 N to 3 s.f. (1)` },
      { q: 'Explain why it is preferable to resolve parallel and perpendicular to an inclined plane rather than horizontally and vertically.', marks: 3, markScheme: `• The normal reaction is perpendicular to the plane and the friction is along it (1)\n• Choosing these directions places each of those forces along a single axis (1)\n• Each equation then contains fewer unknowns, so the algebra is simpler (1)` },
      { q: 'Describe a way of checking whether sin or cos is correct for the component of weight along an inclined plane.', marks: 3, markScheme: `• Consider the limiting case θ = 0, where the plane is horizontal (1)\n• The component along the plane should then be zero (1)\n• Since sin 0 = 0, the sine is correct for the component along the plane (1)` },
      { q: 'State the condition for a particle to be in equilibrium, and describe how it is used in practice.', marks: 3, markScheme: `• A particle is in equilibrium if and only if the resultant of the forces acting on it is zero (1)\n• Equivalently, resolving in any direction gives a total of zero (1)\n• In practice, resolve in two perpendicular directions to obtain two equations (1)` },
      { q: 'Explain what is meant by saying that forces in equilibrium form a closed polygon.', marks: 3, markScheme: `• The vector sum of the forces is the zero vector (1)\n• Drawing the force vectors head to tail therefore returns to the starting point (1)\n• For three forces this gives a closed triangle (1)` },
      { q: 'Two perpendicular forces of 3 N and 4 N act on a particle. Find the magnitude of the resultant and the angle it makes with the 3 N force.', marks: 4, markScheme: `• Magnitude = √(3² + 4²) (1)\n• = 5 N (1)\n• tan θ = 4/3 (1)\n• θ = 53.1° to 1 d.p. (1)` },
      { q: 'A force is given as 3i + 4j newtons. Find its magnitude.', marks: 2, markScheme: `• Magnitude² = 9 + 16 = 25 (1)\n• Magnitude = 5 N (1)` },
      { q: 'Explain why a crate pushed at constant velocity across a rough floor is in equilibrium, and state what this tells you about the applied force.', marks: 3, markScheme: `• Constant velocity means zero acceleration (1)\n• By Newton\'s second law the resultant force is therefore zero, so the crate is in equilibrium (1)\n• The applied horizontal force exactly balances the frictional force (1)` },
      { q: 'Write down the relationship between the frictional force, the coefficient of friction and the normal reaction.', marks: 2, markScheme: `• F ≤ μR, where μ is the coefficient of friction and R the normal reaction (1)\n• Equality holds when the body is on the point of sliding, which is called limiting friction (1)` },
      { q: 'Explain why F = μR should not be used for a stationary body that is not on the point of moving.', marks: 3, markScheme: `• Friction takes whatever value is needed to prevent motion, up to the maximum μR (1)\n• For a body well below that maximum, the friction equals the applied force (1)\n• Using μR would overstate the friction and give a wrong answer (1)` },
      { q: 'With μ = 0.4 and R = 50 N, find the maximum possible frictional force, and describe what happens if a horizontal push of 15 N and then 25 N is applied.', marks: 4, markScheme: `• Maximum friction = μR = 0.4 × 50 = 20 N (1)\n• A 15 N push is below the maximum, so friction equals 15 N and the block stays at rest (1)\n• A 25 N push exceeds the maximum (1)\n• The block slides, with friction acting at its limiting value of 20 N (1)` },
      { q: 'A 4 kg block rests on a rough horizontal surface with μ = 0.25. Taking g = 9.8, find the horizontal force needed to make it start to slide.', marks: 4, markScheme: `• Resolve vertically: R = mg (1)\n• R = 4 × 9.8 = 39.2 N (1)\n• At the point of sliding, F = μR = 0.25 × 39.2 (1)\n• F = 9.8 N (1)` },
      { q: 'State the units of the coefficient of friction, justifying your answer.', marks: 2, markScheme: `• The coefficient of friction has no units (1)\n• It is the ratio of two forces, so the units cancel (1)` },
      { q: 'Write down the relationship defining the angle of friction.', marks: 2, markScheme: `• The angle of friction λ satisfies tan λ = μ (1)\n• It is the angle of the resultant of the normal reaction and limiting friction, measured from the normal (1)` },
      { q: 'Show that a block on a rough plane inclined at angle θ remains at rest provided tan θ ≤ μ.', marks: 5, markScheme: `• Resolve perpendicular to the plane: R = mg cos θ (1)\n• Resolve parallel: the component tending to move the block is mg sin θ (1)\n• For equilibrium this cannot exceed limiting friction, so mg sin θ ≤ μR (1)\n• Substitute for R: mg sin θ ≤ μ mg cos θ (1)\n• Divide by mg cos θ, which is positive for 0 < θ < 90°, to obtain tan θ ≤ μ (1)` },
      { q: 'A block sits on a rough plane inclined at 20° with μ = 0.5. Determine whether it slides, justifying your answer.', marks: 3, markScheme: `• The block stays at rest if tan θ ≤ μ (1)\n• tan 20° ≈ 0.364 (1)\n• Since 0.364 < 0.5, the block remains at rest (1)` },
      { q: 'Explain why the condition for a block to remain at rest on a slope is independent of its mass.', marks: 3, markScheme: `• Both the component of weight along the plane and the normal reaction are proportional to the mass (1)\n• The mass therefore cancels when the two are compared (1)\n• The condition reduces to tan θ ≤ μ, which contains no reference to mass (1)` },
      { q: 'State the direction in which friction acts on a block in limiting equilibrium on a rough slope, with a reason.', marks: 2, markScheme: `• Friction acts up the plane (1)\n• It opposes the tendency of the block to slide down under its own weight (1)` },
      { q: 'Explain why pulling a heavy case with a force angled above the horizontal is easier than pushing it downwards at an angle.', marks: 4, markScheme: `• Pulling upwards at an angle has an upward vertical component (1)\n• This reduces the normal reaction and therefore the maximum friction (1)\n• Pushing downwards at an angle increases the normal reaction (1)\n• The maximum friction increases, so a larger force is needed to move the case (1)` },
      { q: 'A body hangs in equilibrium from two strings at different angles. State how many independent equations can be obtained and how.', marks: 2, markScheme: `• Two independent equations (1)\n• They are obtained by resolving in two perpendicular directions, typically horizontally and vertically (1)` },
      { q: 'A block on a smooth plane inclined at 30° is released from rest. Taking g = 9.8, find its acceleration down the plane.', marks: 4, markScheme: `• The plane is smooth, so there is no friction (1)\n• The only force along the plane is mg sin 30° (1)\n• ma = mg sin 30°, so a = g sin 30° (1)\n• a = 4.9 m s⁻² (1)` },
      { q: 'Explain why a person in a lift accelerating upwards feels heavier.', marks: 3, markScheme: `• The equation of motion is R − mg = ma (1)\n• So R = m(g + a), which exceeds the weight (1)\n• The sensation of weight comes from the normal reaction from the floor, which has increased (1)` },
      { q: 'A lift is descending and decelerating. State whether the normal reaction on a passenger exceeds their weight, with a reason.', marks: 3, markScheme: `• Decelerating while descending means the acceleration is directed upwards (1)\n• The equation R − mg = ma then applies with a positive (1)\n• So the reaction exceeds the weight (1)` },
      { q: 'Explain why "in equilibrium" does not necessarily mean "at rest".', marks: 2, markScheme: `• Equilibrium means the resultant force is zero, so the acceleration is zero (1)\n• A body moving at constant velocity also has zero acceleration, so it too is in equilibrium (1)` },
      { q: 'Describe the meaning of the terms driving force and resistance in the context of a moving vehicle.', marks: 2, markScheme: `• The driving force is the forward force produced by the engine (1)\n• Resistance covers air resistance and other forces opposing the motion (1)` },
      { q: 'Explain why the acceleration due to gravity is not a universal constant, and state what value is used in examinations for this specification.', marks: 3, markScheme: `• The value of g depends on location in the universe, and even varies slightly across the Earth (1)\n• On Earth it is modelled as constant for these problems (1)\n• Examinations use g = 9.8 unless otherwise specified (1)` },
      { q: 'State whether the inverse square law for gravitation is required by this specification.', marks: 2, markScheme: `• The inverse square law for gravitation is excluded from this specification (1)\n• Gravity is instead modelled as producing a constant acceleration g near the Earth\'s surface (1)` },
      { q: 'Two forces 3i + 2j and −i + 4j act on a particle. Find the resultant and its magnitude to 3 significant figures.', marks: 3, markScheme: `• Resultant = 2i + 6j (1)\n• Magnitude = √(4 + 36) (1)\n• = 6.32 N (1)` },
      { q: 'A particle is in equilibrium under three forces, two of which are 4i + j and −i − 3j. Find the third force.', marks: 3, markScheme: `• The three forces must sum to the zero vector (1)\n• The sum of the two given forces is 3i − 2j (1)\n• The third force is −3i + 2j (1)` },
      { q: 'Explain the difference between a resultant force and an equilibrant.', marks: 2, markScheme: `• The resultant is the single force having the same effect as a set of forces (1)\n• The equilibrant is equal in magnitude and opposite in direction to the resultant, and would hold the system in equilibrium (1)` },
      { q: 'A 5 kg block rests on a horizontal table with no other vertical forces. Taking g = 9.8, find the normal reaction.', marks: 3, markScheme: `• Resolve vertically, with the block in equilibrium (1)\n• R = mg (1)\n• R = 49 N (1)` },
      { q: 'Explain why a normal reaction is described as a contact force, and what happens to it when contact is lost.', marks: 2, markScheme: `• It arises only where two surfaces are in contact, as the surface pushes back on the body (1)\n• If contact is lost the normal reaction becomes zero, which is the condition used for a body leaving a surface (1)` },
    ]
  },

  '3.6': {
    name: "Newton's Laws of Motion",
    questions: [
      { q: "State Newton's three laws of motion.", marks: 3, markScheme: `• First law: an object continues at rest or in uniform motion in a straight line unless acted on by a resultant force (1)\n• Second law: a resultant force F on an object of fixed mass m gives an acceleration a with F = ma (1)\n• Third law: when one object exerts a force on another, there is a reaction equal in magnitude and opposite in direction (1)` },
      { q: 'Explain what is meant by the equation of motion of a particle, and describe how one is written down.', marks: 4, markScheme: `• It is the application of Newton\'s second law to that particle in a chosen direction (1)\n• Draw a force diagram showing all forces on the body (1)\n• Choose a positive direction, usually the direction of acceleration (1)\n• Resolve in that direction and set the total equal to ma (1)` },
      { q: 'Explain why the F in F = ma must be the resultant force.', marks: 3, markScheme: `• The acceleration is produced by the combined effect of all the forces acting (1)\n• Using only one force ignores the others, such as friction or weight (1)\n• The equation would then give the wrong acceleration (1)` },
      { q: 'A resultant force of 20 N acts on a mass of 4 kg. Find the acceleration.', marks: 2, markScheme: `• a = F/m (1)\n• a = 20/4 = 5 m s⁻² (1)` },
      { q: 'A mass of 2 kg accelerates at 3 m s⁻². Find the resultant force.', marks: 2, markScheme: `• F = ma (1)\n• F = 2 × 3 = 6 N (1)` },
      { q: 'A car of mass 1000 kg has a driving force of 3000 N and a resistance of 1000 N. Find its acceleration.', marks: 3, markScheme: `• Resultant force = 3000 − 1000 (1)\n• = 2000 N (1)\n• a = 2000/1000 = 2 m s⁻² (1)` },
      { q: 'A body of mass 5 kg falls against an air resistance of 19 N. Taking g = 9.8, find its acceleration.', marks: 4, markScheme: `• Weight = 5 × 9.8 = 49 N (1)\n• Resultant force downwards = 49 − 19 (1)\n• = 30 N (1)\n• a = 30/5 = 6 m s⁻² (1)` },
      { q: 'A car of mass 800 kg decelerates under a resistance of 2000 N. Find the magnitude of the deceleration.', marks: 3, markScheme: `• The resultant force is 2000 N opposing the motion (1)\n• a = 2000/800 (1)\n• Deceleration = 2.5 m s⁻² (1)` },
      { q: 'A 1200 kg car travelling at 20 m s⁻¹ brakes to rest in 40 m. Find the constant braking force required.', marks: 5, markScheme: `• Use v² = u² + 2as to find the acceleration (1)\n• 0 = 400 + 2a(40) (1)\n• a = −5 m s⁻² (1)\n• Apply F = ma (1)\n• Braking force = 1200 × 5 = 6000 N (1)` },
      { q: 'Explain how equilibrium arises as a special case of the equation of motion.', marks: 2, markScheme: `• Equilibrium means the acceleration is zero (1)\n• Substituting a = 0 into F = ma gives a resultant force of zero, which is the condition for equilibrium (1)` },
      { q: 'A resultant force 6i + 8j newtons acts on a 2 kg particle. Find the acceleration and its magnitude.', marks: 4, markScheme: `• The second law applies component by component (1)\n• a = (6i + 8j)/2 (1)\n• a = 3i + 4j m s⁻² (1)\n• Magnitude = 5 m s⁻² (1)` },
      { q: 'A particle of mass 0.5 kg has resultant force 3i − 4j newtons. Find its acceleration.', marks: 3, markScheme: `• a = F/m (1)\n• Divide each component by 0.5, which is the same as multiplying by 2 (1)\n• a = 6i − 8j m s⁻² (1)` },
      { q: 'State whether problems involving variable mass are required by this specification.', marks: 2, markScheme: `• Variable mass problems are excluded (1)\n• The mass in F = ma may therefore always be treated as constant (1)` },
      { q: 'For a person of mass m in a lift, write down the equation of motion when the lift accelerates upwards at a, and hence find the normal reaction.', marks: 3, markScheme: `• Taking upwards as positive: R − mg = ma (1)\n• Rearranging gives R = m(g + a) (1)\n• The reaction exceeds the weight, so the person feels heavier (1)` },
      { q: 'A 70 kg passenger is in a lift accelerating upwards at 2 m s⁻². Taking g = 9.8, find the normal reaction.', marks: 3, markScheme: `• R = m(g + a) (1)\n• = 70 × 11.8 (1)\n• R = 826 N (1)` },
      { q: 'A lift accelerates downwards at a. Write down the equation of motion for a passenger and describe the effect on the normal reaction.', marks: 3, markScheme: `• Taking downwards as positive: mg − R = ma (1)\n• So R = m(g − a) (1)\n• The reaction is less than the weight, so the passenger feels lighter (1)` },
      { q: 'Explain the condition under which a passenger in a descending lift would feel weightless.', marks: 3, markScheme: `• Weightlessness corresponds to a normal reaction of zero (1)\n• From R = m(g − a), this occurs when a = g (1)\n• The lift would be in free fall (1)` },
      { q: "A book rests on a table. Explain why the book's weight and the table's normal reaction are not a Newton's third law pair.", marks: 4, markScheme: `• A third-law pair consists of forces acting on two different bodies (1)\n• Both the weight and the normal reaction act on the book (1)\n• They are equal here only because the book is in equilibrium (1)\n• The true partner of the book\'s weight is the gravitational pull of the book on the Earth (1)` },
      { q: "State a simple test for whether two forces form a Newton's third law pair.", marks: 2, markScheme: `• Check whether the two forces act on different bodies (1)\n• If they act on the same body they cannot be a third-law pair, however equal and opposite they appear (1)` },
      { q: 'Explain the two assumptions about a string and a pulley that are used in connected-particle problems, and what each allows.', marks: 4, markScheme: `• The string is light and inextensible (1)\n• So the tension is the same throughout and both particles have accelerations of equal magnitude (1)\n• The pulley is smooth (1)\n• So the tension is unchanged across it, and is equal on both sides (1)` },
      { q: 'Describe the two strategies for solving a connected-particle problem, and state what each is best used for.', marks: 4, markScheme: `• Treat the whole system as one body (1)\n• Internal tensions cancel, so this gives the acceleration most directly (1)\n• Alternatively write the equation of motion for each particle separately (1)\n• This is needed to find the tension or coupling force, which appears explicitly (1)` },
      { q: 'Masses of 5 kg and 3 kg hang from a light inextensible string over a smooth pulley. Taking g = 9.8, find the acceleration of the system.', marks: 4, markScheme: `• For the 5 kg mass, taking downwards positive: 5g − T = 5a (1)\n• For the 3 kg mass, taking upwards positive: T − 3g = 3a (1)\n• Add the equations to eliminate T: 2g = 8a (1)\n• a = 2.45 m s⁻² (1)` },
      { q: 'For that same system, find the tension in the string and check your answer.', marks: 4, markScheme: `• Substitute a = 2.45 into T − 3g = 3a (1)\n• T = 3(9.8 + 2.45) (1)\n• T = 36.75 N (1)\n• Check with the other equation: 5(9.8 − 2.45) = 36.75 N, which agrees (1)` },
      { q: 'Explain why the tension in a pulley system with unequal masses must lie between the two weights.', marks: 3, markScheme: `• The heavier mass accelerates downwards, so the tension is less than its weight (1)\n• The lighter mass accelerates upwards, so the tension exceeds its weight (1)\n• The tension therefore lies strictly between the two weights, which provides a useful check (1)` },
      { q: 'A 4 kg block on a smooth table is connected over a smooth pulley to a 2 kg hanging mass. Taking g = 9.8, find the acceleration.', marks: 4, markScheme: `• Treat the system as one body of total mass 6 kg (1)\n• The only external driving force is the weight of the hanging mass, 2g (1)\n• 2 × 9.8 = 6a (1)\n• a = 3.27 m s⁻² to 3 s.f. (1)` },
      { q: 'For that same system, find the tension in the string.', marks: 3, markScheme: `• Write the equation for the block on the table alone (1)\n• T = 4a (1)\n• T = 4 × 3.267 = 13.1 N to 3 s.f. (1)` },
      { q: 'An engine of mass 20 000 kg pulls a carriage of mass 10 000 kg with a total driving force of 45 000 N and no resistance. Find the acceleration and the force in the coupling.', marks: 5, markScheme: `• Whole system: total mass = 30 000 kg (1)\n• 45 000 = 30 000a (1)\n• a = 1.5 m s⁻² (1)\n• For the carriage alone, the coupling force is the only horizontal force (1)\n• T = 10 000 × 1.5 = 15 000 N (1)` },
      { q: 'A train of total mass 50 000 kg accelerates at 0.2 m s⁻² against a resistance of 5000 N. Find the driving force.', marks: 4, markScheme: `• Resultant force = ma = 50 000 × 0.2 (1)\n• = 10 000 N (1)\n• Driving force = resultant plus resistance (1)\n• = 15 000 N (1)` },
      { q: 'Explain why you cannot find an internal tension from the whole-system equation of motion.', marks: 2, markScheme: `• Internal forces occur in equal and opposite pairs within the system (1)\n• They cancel when the system is treated as one body, so the tension does not appear in that equation (1)` },
      { q: 'A block of mass m on a rough horizontal surface is pulled by a horizontal force P. Write down its equation of motion.', marks: 3, markScheme: `• Resolve vertically: R = mg (1)\n• The frictional force is μR, opposing the motion (1)\n• P − μR = ma (1)` },
      { q: 'A 2 kg particle is released on a smooth plane inclined at 30°. Taking g = 9.8, find its acceleration down the plane.', marks: 4, markScheme: `• The plane is smooth, so friction is zero (1)\n• The force along the plane is mg sin 30° (1)\n• ma = mg sin 30°, so a = g sin 30° (1)\n• a = 4.9 m s⁻² (1)` },
      { q: 'Explain what is meant by terminal velocity and how it arises.', marks: 3, markScheme: `• A falling body meets a resistance that increases with speed (1)\n• When the resistance equals the weight the resultant force becomes zero (1)\n• The acceleration is then zero, so the speed stops increasing; that speed is the terminal velocity (1)` },
      { q: 'Explain why the accelerations of two particles joined by an inextensible string over a pulley have equal magnitude but may have different directions.', marks: 3, markScheme: `• The string cannot stretch, so the length between the particles is fixed (1)\n• Any movement of one particle is matched by an equal movement of the other (1)\n• The directions differ because one descends while the other rises (1)` },
      { q: 'Explain the importance of choosing consistent positive directions for the two particles in a pulley problem.', marks: 3, markScheme: `• Each particle needs a positive direction in which it actually accelerates (1)\n• Usually downwards for the descending mass and upwards for the rising one (1)\n• An inconsistent choice introduces a sign error, typically producing a negative or impossible tension (1)` },
      { q: 'Explain why the second law is described as a vector equation.', marks: 3, markScheme: `• Both force and acceleration are vector quantities (1)\n• The equation therefore holds in each direction independently (1)\n• It may be applied component by component, for example horizontally and vertically (1)` },
      { q: 'A particle is in equilibrium under three forces. Explain what the second law tells you in this case.', marks: 2, markScheme: `• The acceleration is zero, so ma = 0 (1)\n• The resultant of the three forces must therefore be zero (1)` },
      { q: 'A lift moves upwards at constant velocity. State the normal reaction on a passenger of mass m, with a reason.', marks: 2, markScheme: `• Constant velocity means zero acceleration (1)\n• So R = mg, exactly the passenger\'s weight (1)` },
      { q: "Explain how Newton's first law is contained within the second law.", marks: 3, markScheme: `• Setting F = 0 in F = ma gives a = 0 (1)\n• Zero acceleration means the velocity is constant (1)\n• So a body with no resultant force stays at rest or continues in uniform motion, which is the first law (1)` },
      { q: 'A 3 kg block is pulled along a smooth horizontal surface by a force of 12 N. Find the acceleration.', marks: 2, markScheme: `• The surface is smooth, so the resultant horizontal force is 12 N (1)\n• a = 12/3 = 4 m s⁻² (1)` },
      { q: 'A student says the tension in a string over a pulley must equal the weight of the hanging mass. Explain why this is wrong when the system is accelerating.', marks: 3, markScheme: `• If the tension equalled the weight, the resultant force on the hanging mass would be zero (1)\n• The mass would then have zero acceleration, contradicting the fact that the system is accelerating (1)\n• The tension must be less than the weight for a descending mass, so that there is a net downward force (1)` },
    ]
  },

  '3.7': {
    name: 'Rigid Bodies',
    questions: [
      { q: 'Explain why the point at which a force acts matters for a rigid body but not for a particle.', marks: 3, markScheme: `• A particle has no size, so all forces act at a single point and can only produce translation (1)\n• A rigid body has extent, so the line of action of a force matters (1)\n• A system of forces can therefore produce a turning effect as well as a translation (1)` },
      { q: 'Define the moment of a force about a point and state its units.', marks: 2, markScheme: `• Moment = force × perpendicular distance from the point to the line of action (1)\n• Units are newton metres, N m (1)` },
      { q: 'A force of 12 N acts perpendicular to a rod, 0.5 m from a pivot. Find the moment about the pivot.', marks: 2, markScheme: `• Moment = 12 × 0.5 (1)\n• = 6 N m (1)` },
      { q: 'A force of 40 N acts perpendicular to a 3 m rod at the end furthest from the pivot. Find the moment.', marks: 2, markScheme: `• Moment = 40 × 3 (1)\n• = 120 N m (1)` },
      { q: 'Explain why a force acting through the pivot has zero moment about that pivot.', marks: 2, markScheme: `• The perpendicular distance from the pivot to the line of action is zero (1)\n• The moment is the product of force and that distance, so the moment is zero (1)` },
      { q: 'Explain why a moment is quoted in newton metres rather than joules, despite the base units being the same.', marks: 2, markScheme: `• A moment is a turning effect, whereas a joule measures energy (1)\n• Keeping the units distinct avoids confusing two physically different quantities (1)` },
      { q: 'State the two conditions for a rigid body to be in equilibrium.', marks: 2, markScheme: `• The resultant force is zero (1)\n• The sum of the moments about any one point is zero (1)` },
      { q: 'Explain why the force condition alone is not sufficient for a rigid body to be in equilibrium, giving an example.', marks: 3, markScheme: `• A body can have zero resultant force yet still rotate (1)\n• Example: two equal and opposite forces applied at different points along a rod (1)\n• There is no net force, but the two moments act in the same rotational sense, so the rod turns (1)` },
      { q: 'Explain why, for a body in equilibrium, moments may be taken about any point.', marks: 2, markScheme: `• Once the resultant force is zero, the total moment is the same about every point (1)\n• Any convenient point may therefore be chosen without changing the result (1)` },
      { q: 'Describe the standard technique for choosing a pivot when taking moments, and why it helps.', marks: 3, markScheme: `• Take moments about a point through which an unknown force acts (1)\n• That force then has zero moment and disappears from the equation (1)\n• The equation therefore contains one fewer unknown, so it can be solved directly (1)` },
      { q: 'State where the weight of a body may be taken to act, and give its location for a uniform rod and a uniform rectangular lamina.', marks: 3, markScheme: `• The weight may be taken to act at the centre of mass (1)\n• For a uniform rod this is the midpoint (1)\n• For a uniform rectangular lamina it is at the intersection of the diagonals (1)` },
      { q: 'A uniform rod has length 2a. State where its weight acts, and explain why this is not the case for a non-uniform rod.', marks: 3, markScheme: `• The weight acts at the midpoint, a distance a from either end (1)\n• A non-uniform rod has mass distributed unevenly along its length (1)\n• Its centre of mass is therefore not at the midpoint, and must be given or found (1)` },
      { q: 'A light rod is pivoted at its centre. A 30 N weight hangs 2 m from the pivot. Find the distance at which a 40 N weight balances it.', marks: 3, markScheme: `• For balance the moments about the pivot are equal (1)\n• 30 × 2 = 40 × d (1)\n• d = 1.5 m (1)` },
      { q: 'Two children of weights 300 N and 500 N sit on a seesaw pivoted at its centre. If the lighter sits 2 m from the pivot, find where the heavier must sit.', marks: 3, markScheme: `• Equate the moments about the pivot (1)\n• 300 × 2 = 500 × d (1)\n• d = 1.2 m (1)` },
      { q: 'A uniform rod of weight 100 N and length 6 m rests on supports at its two ends. Find each reaction, justifying your method.', marks: 3, markScheme: `• By symmetry the two reactions are equal (1)\n• Resolving vertically, R₁ + R₂ = 100 (1)\n• Each reaction is 50 N (1)` },
      { q: 'A uniform plank of weight 200 N and length 4 m rests on supports at each end, with a 100 N load at its midpoint. Find each reaction.', marks: 4, markScheme: `• Both the plank weight and the load act at the midpoint, so the arrangement is symmetric (1)\n• The two reactions are therefore equal (1)\n• Resolving vertically: R₁ + R₂ = 300 (1)\n• Each reaction is 150 N (1)` },
      { q: 'A uniform rod of weight 60 N and length 4 m is hinged at A and held horizontal by a vertical string at B. Find the tension in the string.', marks: 4, markScheme: `• Take moments about A, which eliminates the hinge force (1)\n• The weight acts at the midpoint, 2 m from A (1)\n• T × 4 = 60 × 2 (1)\n• T = 30 N (1)` },
      { q: 'For that same rod, find the vertical force exerted by the hinge.', marks: 3, markScheme: `• Resolve vertically for the whole rod (1)\n• Hinge force + T = 60 (1)\n• Hinge force = 60 − 30 = 30 N upwards (1)` },
      { q: 'A non-uniform rod AB of length 4 m and weight 50 N rests horizontally on supports at A and B. The reaction at A is 20 N. Find the distance of the centre of mass from A.', marks: 5, markScheme: `• Resolve vertically: R_A + R_B = 50 (1)\n• R_B = 30 N (1)\n• Take moments about A, with the centre of mass at distance x (1)\n• 50x = 30 × 4 = 120 (1)\n• x = 2.4 m from A (1)` },
      { q: 'A non-uniform rod of weight 80 N and length 5 m rests on supports at its ends, with reactions 30 N and 50 N. Find the distance of the centre of mass from the 30 N end.', marks: 4, markScheme: `• Check the reactions sum to the weight: 30 + 50 = 80 (1)\n• Take moments about the 30 N end (1)\n• 80x = 50 × 5 = 250 (1)\n• x = 3.125 m (1)` },
      { q: 'Explain why the centre of mass of a rod on two supports lies closer to the support with the larger reaction.', marks: 3, markScheme: `• Taking moments about one support, the weight moment must balance the moment of the other reaction (1)\n• A larger reaction at a support means more of the weight is carried there (1)\n• The centre of mass must therefore be nearer that support, giving it the shorter lever arm relative to the other (1)` },
      { q: 'State the condition for a body resting on two supports to be on the point of tipping about one of them.', marks: 2, markScheme: `• The reaction at the other support falls to zero (1)\n• All the weight is then carried by the support about which tipping occurs (1)` },
      { q: 'A uniform plank of length 6 m and weight 300 N rests on supports 1 m from each end. A child of weight 200 N stands at one end. Find the reaction at the nearer support.', marks: 5, markScheme: `• The supports are 1 m and 5 m from one end, and the weight acts at 3 m (1)\n• Take moments about the far support at 5 m (1)\n• R × 4 = 300 × 2 + 200 × 5 (1)\n• R × 4 = 600 + 1000 = 1600 (1)\n• R = 400 N (1)` },
      { q: 'Explain how a tipping problem is converted into an ordinary moments calculation.', marks: 3, markScheme: `• Set the reaction at the support the body lifts away from equal to zero (1)\n• Take moments about the remaining support (1)\n• Solve the resulting equation for the required distance or load (1)` },
      { q: 'A plank overhangs a support and a person walks out along the overhang. Explain what determines the point at which the plank tips.', marks: 3, markScheme: `• The plank tips when the moment of the person about the support exceeds the opposing moment of the plank\'s weight (1)\n• The person\'s moment grows as they walk further out (1)\n• Tipping begins at the position where the two moments are equal (1)` },
      { q: 'State the restrictions placed by this specification on the bodies and forces considered in moments problems.', marks: 4, markScheme: `• The bodies are rods and rectangular laminas, which may be non-uniform (1)\n• The forces are coplanar (1)\n• They act perpendicular to the rod or to an edge of the lamina (1)\n• A vector treatment of moments is excluded (1)` },
      { q: 'State whether finding the centre of mass of a composite body is required by this specification.', marks: 2, markScheme: `• It is excluded from this specification (1)\n• Questions are restricted to cases where the centre of mass is given, found by symmetry, or found from consideration of moments (1)` },
      { q: 'Set out the standard method for solving a moments problem involving a rod on supports.', marks: 4, markScheme: `• Draw the rod with every force marked, including the weight at the centre of mass (1)\n• Resolve vertically to relate the reactions to the total downward force (1)\n• Take moments about a well-chosen point to eliminate one unknown (1)\n• Solve and check the answer is physically sensible (1)` },
      { q: 'For a body in equilibrium under vertical forces, state how many independent equations are available and hence how many unknowns can be found.', marks: 2, markScheme: `• Two independent equations: one from resolving and one from taking moments (1)\n• At most two unknowns can therefore be determined (1)` },
      { q: 'Explain why a consistent sign convention is needed when adding moments.', marks: 2, markScheme: `• Moments act in one of two rotational senses, clockwise or anticlockwise (1)\n• Without a consistent convention, opposing moments would be added rather than subtracted, giving a wrong total (1)` },
      { q: 'A uniform beam of weight 400 N and length 8 m is supported at one end and at a point 6 m from that end. Find the reaction at the further support.', marks: 4, markScheme: `• The weight acts at the midpoint, 4 m from the first support (1)\n• Take moments about the first support (1)\n• R × 6 = 400 × 4 (1)\n• R = 267 N to 3 s.f. (1)` },
      { q: 'For that same beam, find the reaction at the first support.', marks: 3, markScheme: `• Resolve vertically: R₁ + R₂ = 400 (1)\n• R₁ = 400 − 266.7 (1)\n• R₁ = 133 N to 3 s.f. (1)` },
      { q: 'Explain what happens to the moment of a force if both the force and its distance from the pivot are doubled.', marks: 2, markScheme: `• The moment is the product of the two quantities (1)\n• Doubling both multiplies the moment by 4 (1)` },
      { q: 'A single non-zero force acts on a rigid body along a line not passing through its centre of mass. Describe the resulting motion.', marks: 3, markScheme: `• There is a non-zero resultant force, so the body accelerates (1)\n• There is also a non-zero moment about the centre of mass, so the body rotates (1)\n• The body is therefore not in equilibrium, undergoing both translation and rotation (1)` },
      { q: 'Explain why taking moments about two different points for a body in equilibrium does not always give new information.', marks: 3, markScheme: `• Only two independent equations are available for a system of coplanar parallel forces (1)\n• A second moments equation may be a combination of the first moments equation and the resolving equation (1)\n• It is then a valid check, but provides nothing new for solving (1)` },
      { q: 'A uniform rod of weight W and length 2a rests on a support at a distance a/2 from one end. Explain what happens and what would be needed to keep it horizontal.', marks: 3, markScheme: `• The centre of mass is at distance a from the end, so it lies beyond the support (1)\n• The weight therefore produces an unbalanced moment about the support (1)\n• An additional force, applied on the short side of the support, is needed to provide a balancing moment (1)` },
      { q: 'A ladder rests against a smooth wall and rough ground. State which forces have a moment about the foot of the ladder.', marks: 3, markScheme: `• The weight of the ladder, acting at its centre of mass, has a moment about the foot (1)\n• The reaction from the wall has a moment about the foot (1)\n• The reaction and friction at the foot both pass through that point, so they have zero moment about it (1)` },
      { q: 'Explain why taking moments about the foot of a ladder is a useful choice.', marks: 2, markScheme: `• Both the normal reaction and the friction at the foot act through that point (1)\n• Both therefore have zero moment about it, removing two unknowns from the equation at once (1)` },
      { q: 'A uniform rod of weight 80 N and length 4 m rests on a support 1 m from one end, with a load hung at that end. Find the load needed for the rod to be on the point of tipping.', marks: 5, markScheme: `• On the point of tipping, the rod turns about the support (1)\n• The weight acts at the midpoint, 1 m from the support on the far side (1)\n• The load acts 1 m from the support on the near side (1)\n• Equate moments: L × 1 = 80 × 1 (1)\n• L = 80 N (1)` },
      { q: 'Explain how you would check that an answer to a moments problem is physically sensible.', marks: 3, markScheme: `• Confirm that the reactions sum to the total downward force (1)\n• Check that no reaction is negative, since a support can only push (1)\n• Check that any centre of mass found lies within the length of the body, and nearer the larger reaction (1)` },
    ]
  },

};

if (typeof module !== 'undefined') { module.exports = MATHS_OCR_B_ALEVEL_PRACTICE; }
